INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('5481075c-3b52-4edf-9b93-ff6c31daf0be'::uuid, 'Reading the Ocean with Stick Charts', 'Marshallese navigators developed charts from lashed strips of palm or coconut material, sometimes adding shells to represent islands. Yet calling these objects maps can mislead. They did not simply shrink coastlines onto a fixed scale. Instead, their curves and crossings represented how long ocean swells were bent, reflected or interrupted by atolls. An island still below the horizon could alter the motion of a canoe, giving a skilled navigator evidence of nearby land.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('3e4c3304-0c69-43c7-adb3-b396641c5da2'::uuid, '5481075c-3b52-4edf-9b93-ff6c31daf0be'::uuid, 'What was the principal function of a mattang?', ARRAY['To teach general patterns of swell interaction around an island', 'To show every atoll in the Marshall Islands at a fixed scale', 'To record the daily position of a canoe during a voyage', 'To provide a code that any navigator could read without instruction'], 'To teach general patterns of swell interaction around an island', 'The passage explicitly calls the mattang a schematic teaching device for general swell interaction. It was not a fixed-scale map of every atoll, a voyage log, or a universally readable code, so the other three options conflict with the passage.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('faf6ee57-b8ac-490b-a2ad-89a01234d112'::uuid, '5481075c-3b52-4edf-9b93-ff6c31daf0be'::uuid, 'Why could a navigator detect an island before seeing it?', ARRAY['Shell markers floated from the island towards the canoe', 'The island altered swells and therefore changed the canoe''s motion', 'The chart predicted the island''s appearance from the stars alone', 'The navigator measured the island''s coastline against a fixed scale'], 'The island altered swells and therefore changed the canoe''s motion', 'The first paragraph states that atolls alter swells and that this can be felt through the canoe. Shells were attached to some charts, not released at sea; the passage does not attribute detection to stars; and the charts were not fixed-scale coastline maps.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('4c7e33e9-a75d-4970-b3f3-31ae28df59d2'::uuid, '5481075c-3b52-4edf-9b93-ff6c31daf0be'::uuid, 'Which conclusion is best supported by the fact that charts were generally studied on land?', ARRAY['Their makers considered ocean swells too changeable to be represented', 'They were ceremonial objects with no navigational relevance', 'Their value depended on learning that could later be applied without consulting the object', 'Navigators lacked a safe way to carry lightweight objects in canoes'], 'Their value depended on learning that could later be applied without consulting the object', 'The chart was studied during apprenticeship, then its principles were recalled while the navigator read the sea directly. Swells were represented, so they were not considered too changeable; the objects had navigational relevance, so they were not merely ceremonial; and no transport difficulty is stated.', 2, 'hard');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('3348272b-1c70-4654-ad98-e36eb6fb6181'::uuid, '5481075c-3b52-4edf-9b93-ff6c31daf0be'::uuid, 'What paradox does the author identify in museum display?', ARRAY['A chart may look fragile although it was originally made from metal', 'A chart may appear abstract although every line reproduced a measured coastline', 'A chart may seem ancient although all surviving examples were made recently for tourists', 'A chart may look self-contained although its use relied on teaching, memory and bodily skill'], 'A chart may look self-contained although its use relied on teaching, memory and bodily skill', 'The final paragraph contrasts a self-contained museum object with a practice involving instruction, memory and bodily attention. The passage says the charts used plant strips, not metal; denies that the lines reproduce coastlines; and makes no claim that all surviving examples are modern tourist objects.', 3, 'normal');
INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('89052d68-8561-471c-ab88-da03c30ea209'::uuid, 'When Iron Gall Ink Bites into Paper', 'For centuries, iron gall ink was a standard writing medium in Europe. Recipes varied, but the usual ingredients were an extract of oak galls, iron sulphate, water and gum arabic. Galls contain tannins, which react with iron salts to form a dark colourant. Gum arabic helps the liquid flow from a pen and bind to the writing surface. Fresh writing could appear bluish black before ageing towards brown.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('629c51ee-482f-45e2-b55c-b61f72080f31'::uuid, '89052d68-8561-471c-ab88-da03c30ea209'::uuid, 'What role does gum arabic play in the ink as described?', ARRAY['It supplies the iron ions that oxidise cellulose', 'It removes excess acid during deacidification', 'It improves flow and helps bind the ink to the writing surface', 'It changes damaged brown ink back to bluish black'], 'It improves flow and helps bind the ink to the writing surface', 'The first paragraph gives flow and binding as gum arabic''s functions. Iron sulphate, not gum, supplies iron; deacidification is a conservation treatment rather than an ingredient function; and no reversal of aged colour is described.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('efbde862-806c-47da-8245-7703abce14ce'::uuid, '89052d68-8561-471c-ab88-da03c30ea209'::uuid, 'Why can excess moisture enlarge the area of ink corrosion?', ARRAY['It allows reactive iron and acids to migrate into nearby paper', 'It converts gum arabic directly into sulphuric acid', 'It makes tannins reproduce throughout the paper fibres', 'It permanently strengthens cellulose around the written line'], 'It allows reactive iron and acids to migrate into nearby paper', 'The passage directly links moisture with migration of iron ions and acids. It does not say gum becomes acid or tannins reproduce, and strengthening cellulose is the opposite of the described deterioration.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('e2819377-d42f-4e75-b651-72c17c83488f'::uuid, '89052d68-8561-471c-ab88-da03c30ea209'::uuid, 'Why might a conservator hesitate before placing an affected sheet in an aqueous treatment?', ARRAY['Water always erases iron gall ink immediately and completely', 'Aqueous treatment can address acidity but never oxidation', 'Indicator papers work only after a manuscript has been washed', 'Water could redistribute soluble damaging compounds through the sheet'], 'Water could redistribute soluble damaging compounds through the sheet', 'The passage identifies redistribution of soluble material as a risk requiring prior testing. It does not say water always erases the ink; some combined treatments address both acidity and oxidation; and indicator testing is described as part of assessment before treatment.', 2, 'hard');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('14d01a0f-dc44-4da3-8416-b39394c60047'::uuid, '89052d68-8561-471c-ab88-da03c30ea209'::uuid, 'Which approach best matches the passage''s account of conservation?', ARRAY['Reinforce every damaged sheet because support stops the underlying chemistry', 'Assess each object and balance chemical, physical and preventive measures', 'Apply the same deacidification formula to every manuscript', 'Avoid stable dry storage once chemical treatment has been completed'], 'Assess each object and balance chemical, physical and preventive measures', 'The passage presents conservation as case-specific risk management using assessment, possible chemical treatment, support and storage. Reinforcement alone does not stop corrosion, one recipe is explicitly rejected, and preventive storage remains important after intervention.', 3, 'normal');
INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('e3075813-ac78-489a-ad70-ad1857366808'::uuid, 'The Thirteen Towers of Chankillo', 'In Peru''s coastal Casma Valley, thirteen stone towers stand at intervals along a low ridge. They formed the most visible part of Chankillo, a ceremonial complex used during the late Early Horizon, roughly between 250 and 200 BCE. Other structures included a triple-walled hilltop building, plazas and compounds. The site''s dry landscape preserved a relationship between architecture and horizon that eventually helped researchers explain the towers.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('8e64794e-861e-4517-a8db-da4e967e63a2'::uuid, 'e3075813-ac78-489a-ad70-ad1857366808'::uuid, 'The towers could be used to identify dates between the two solstices, not merely the solstices themselves.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'True. The passage says the Sun appeared beside different towers and gaps as its rising position moved, allowing the system to indicate many dates through the year. This is explicit confirmation, not an inference from outside knowledge.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('9ea052e8-37a4-4be5-a7b5-9bcb19ac2b29'::uuid, 'e3075813-ac78-489a-ad70-ad1857366808'::uuid, 'Both observation points are equally visible above ground today.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'False. The western point survives clearly, whereas the eastern point is less visible above ground and is known from its foundations. The statement is specifically contradicted.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('a228d533-d875-4fa5-8d12-9d49a09f05fe'::uuid, 'e3075813-ac78-489a-ad70-ad1857366808'::uuid, 'The people who announced dates at Chankillo were hereditary priests.', ARRAY['True', 'False', 'Can''t tell'], 'Can''t tell', 'Can''t tell. The passage suggests controlled access and a possible connection between specialist knowledge and authority, but it states that the institution and the identities of the calendar readers are unknown. Nothing confirms or contradicts hereditary priesthood.', 2, 'hard');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('b42d90d5-f9be-46d0-9cbe-9f6c2e89343b'::uuid, 'e3075813-ac78-489a-ad70-ad1857366808'::uuid, 'The western viewpoint was used for sunsets, while the eastern viewpoint was used for sunrises.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'False. The passage assigns sunrise observations to the western point and corresponding sunset observations to the eastern point. The statement reverses the stated relationship.', 3, 'normal');
INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('a9d469f6-033a-430e-a420-ad3753f65b7b'::uuid, 'Concrete Ears on the British Coast', 'Before radar, British engineers tried to hear attacking aircraft while they were still beyond visual range. Their acoustic mirrors were concave concrete surfaces that reflected engine noise towards a focal point. A listener, and later sometimes a microphone, was positioned there. The mirror did not amplify sound electronically; its geometry concentrated sound arriving from the direction in which the structure faced.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('8786f7cc-0b3b-4c9c-b714-796df0d77baf'::uuid, 'a9d469f6-033a-430e-a420-ad3753f65b7b'::uuid, 'How did an acoustic mirror make distant engine noise easier to detect?', ARRAY['It converted sound directly into radio waves', 'It reflected sound towards a focal point', 'It electronically amplified every coastal noise', 'It forced aircraft to fly along a predictable route'], 'It reflected sound towards a focal point', 'The opening paragraph states that the concave surface concentrated reflected sound at a focal point. Radio-wave transmission belongs to radar; the mirror did not amplify electronically; and it had no effect on an aircraft''s route.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('c0080d87-2be9-4cfc-ad7c-20e62e928395'::uuid, 'a9d469f6-033a-430e-a420-ad3753f65b7b'::uuid, 'Which change most directly reduced the practical value of a given detection range?', ARRAY['Concrete became unable to reflect sound', 'Aircraft crossed the remaining distance more quickly', 'Coastal waves stopped producing background noise', 'Operators ceased to use trained hearing'], 'Aircraft crossed the remaining distance more quickly', 'Faster aircraft shortened the response time after detection, directly reducing the value of the same range. The passage does not say concrete lost reflectivity or that background noise stopped, and trained hearing remained part of operation rather than being abandoned.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('2dd9c15a-77f7-4d63-b452-ac713d9519fe'::uuid, 'a9d469f6-033a-430e-a420-ad3753f65b7b'::uuid, 'Which limitation would enlarging a mirror be least likely to solve?', ARRAY['The decreasing response time caused by faster aircraft', 'The need to gather more sound from a target direction', 'The difficulty of detecting relatively faint engine noise', 'The wish to obtain warning from a greater distance'], 'The decreasing response time caused by faster aircraft', 'A larger collector might gather more sound and extend detection, addressing the other three aims. It cannot slow the aircraft after detection, so the shrinking interval for response remains. This combines the passage''s discussion of scale with its separate speed constraint.', 2, 'hard');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('53a0a9d8-89de-4bc4-b58a-9b86213ff6f9'::uuid, 'a9d469f6-033a-430e-a420-ad3753f65b7b'::uuid, 'Why does the author say the mirrors were not failed radar prototypes?', ARRAY['They were built only after radar had entered routine service', 'They transmitted stronger radio signals than early radar sets', 'They detected passively through sound and belonged to a distinct technical approach', 'They were intended exclusively to guide ships rather than detect aircraft'], 'They detected passively through sound and belonged to a distinct technical approach', 'The conclusion distinguishes passive acoustic detection from radar''s transmitted radio waves. The mirrors predated radar, did not transmit radio signals, and were designed for aircraft warning rather than exclusively for shipping.', 3, 'normal');
INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('f0cf8651-9bc0-42ed-896b-84b6eb350475'::uuid, 'How Wood Frogs Survive Freezing', 'A wood frog overwintering beneath leaf litter may cool below the freezing point and allow ice to form through much of its body. Its heartbeat and breathing stop, and blood no longer circulates. This is freeze tolerance, not simply the avoidance of freezing. The distinction matters because ice is permitted in spaces around cells while intracellular ice, which can rupture membranes and disrupt cell structures, is restricted.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('0cf2718a-73f9-4f02-898c-7e9146af9697'::uuid, 'f0cf8651-9bc0-42ed-896b-84b6eb350475'::uuid, 'A frozen wood frog continues to circulate blood slowly throughout winter.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'False. The passage explicitly states that the heartbeat stops and blood no longer circulates. This directly contradicts continued slow circulation.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('16cb8091-9bde-4a3a-9809-f8ea7d93afbf'::uuid, 'f0cf8651-9bc0-42ed-896b-84b6eb350475'::uuid, 'Cryoprotectants prevent all ice from forming anywhere in a wood frog''s body.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'False. Ice is allowed in spaces around cells, and the passage explicitly says cryoprotectants reduce injury rather than keep the entire animal liquid.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('70ba2ee6-4a94-41ec-ae07-2be4b633243f'::uuid, 'f0cf8651-9bc0-42ed-896b-84b6eb350475'::uuid, 'Repeated mild freeze-thaw events always increase the amount and distribution of protective solutes.', ARRAY['True', 'False', 'Can''t tell'], 'Can''t tell', 'Can''t tell. The passage says repeated mild freeze-thaw events may increase the amount and distribution of protective solutes. That does not establish that they always do so, and the passage supplies no counterexample that would directly contradict the universal claim.', 2, 'hard');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('feaff4d1-8179-490e-bec6-eb15763e88db'::uuid, 'f0cf8651-9bc0-42ed-896b-84b6eb350475'::uuid, 'The heart begins beating again before the thawed frog regains normal movement.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'True. The final paragraph states that the heart resumes beating before normal movement returns, so the order is explicitly entailed.', 3, 'normal');
INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('9c9ef7f7-2fca-486f-b90c-00f78fb134ca'::uuid, 'Bacterial Compasses', 'Magnetotactic bacteria are not one species but a varied group of aquatic microorganisms that respond to magnetic fields. Inside each cell are magnetosomes: membrane-bound compartments containing crystals of magnetite or greigite, both iron-bearing magnetic minerals. In many species the compartments form a chain. The combined magnetic moment turns the whole cell until its long axis lies approximately along a magnetic field line, rather like a compass needle.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('d33ececf-0786-4f4d-b128-bf777682d06a'::uuid, '9c9ef7f7-2fca-486f-b90c-00f78fb134ca'::uuid, 'What directly propels magnetotactic bacteria through their environment?', ARRAY['The passive pull of the magnetosome chain', 'The oxic-anoxic interface', 'Greigite released outside the cell', 'Flagella'], 'Flagella', 'The passage distinguishes alignment from propulsion and states that the bacteria swim using flagella. Magnetosomes orient the cell, the interface is an environmental boundary, and greigite remains within magnetosomes rather than being released to propel the cell.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('db290e7c-526d-4627-8140-5c4d664fe539'::uuid, '9c9ef7f7-2fca-486f-b90c-00f78fb134ca'::uuid, 'How can magnetic alignment make the search for a preferred zone more efficient?', ARRAY['It identifies the oxygen concentration without any chemical sensing', 'It makes every cell swim north regardless of location', 'It reduces movement from a three-dimensional search to one mainly along a field line', 'It supplies energy by dissolving the mineral crystals'], 'It reduces movement from a three-dimensional search to one mainly along a field line', 'The second paragraph gives this dimensional reduction as the benefit. Chemical sensing still matters, northward swimming is not universal, and the crystals provide orientation rather than energy by dissolution.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('211bf6d8-c34f-4b8a-aa52-98fd7dd3053a'::uuid, '9c9ef7f7-2fca-486f-b90c-00f78fb134ca'::uuid, 'A mutation leaves a bacterium''s flagella and chemical sensing intact but scatters its magnetosomes instead of arranging them in a chain. Which outcome is most supported?', ARRAY['It would align normally but lose all ability to propel itself', 'It would become unable to form any iron-bearing crystal', 'It could still swim and sense chemicals, but its magnetic alignment would likely be less effective', 'It would necessarily reverse its preferred oxygen level'], 'It could still swim and sense chemicals, but its magnetic alignment would likely be less effective', 'The passage separates flagellar propulsion and chemical sensing from the chain''s combined magnetic alignment. Normal alignment is unlikely if the chain is disrupted; scattered crystals can still exist; and no necessary change in oxygen preference follows.', 2, 'hard');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('4cb4979d-4555-4b94-8458-22a0631eae6b'::uuid, '9c9ef7f7-2fca-486f-b90c-00f78fb134ca'::uuid, 'Which statement best describes magnetotaxis and chemotaxis in the passage?', ARRAY['They cooperate, with one providing alignment and the other helping guide behavioural choice', 'They are alternative systems, and each species possesses only one', 'They are identical names for movement caused by flagella', 'They operate only in bacteria living near the magnetic equator'], 'They cooperate, with one providing alignment and the other helping guide behavioural choice', 'The passage explicitly says the two systems work together: magnetic fields orient while chemical sensing affects swimming decisions. It rejects rivalry, distinguishes both from propulsion, and describes broad aquatic occurrence rather than restriction to the equator.', 3, 'normal');
INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('1bf80f0c-615d-4165-a80d-401e17931f39'::uuid, 'Printing in Prussian Blue', 'The cyanotype is a photographic printing process recognised by its Prussian-blue image. John Herschel described the process in 1842. Unlike many early photographic methods based on silver compounds, it uses iron salts, commonly ferric ammonium citrate and potassium ferricyanide. The two solutions are stored separately and mixed before a support such as paper or cloth is coated under subdued light.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('3d3d2ac0-63cf-44c3-a3ec-406986baa639'::uuid, '1bf80f0c-615d-4165-a80d-401e17931f39'::uuid, 'Which statement correctly describes preparation of the sensitiser?', ARRAY['One solution is used only to wash the finished print', 'Mixing them permanently removes their sensitivity to ultraviolet light', 'They react only when heated inside a camera', 'They are stored separately as components of the light-sensitive working mixture'], 'They are stored separately as components of the light-sensitive working mixture', 'The passage states that the two solutions are stored separately and mixed before the support is coated, which the correct option directly restates. Neither solution is reserved only for washing; mixing does not remove ultraviolet sensitivity; and preparation requires neither heating nor a camera.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('b2d8fe16-7d1d-4d4e-9439-52629f8072f8'::uuid, '1bf80f0c-615d-4165-a80d-401e17931f39'::uuid, 'What produces the pale shape in an Atkins-style algae photogram?', ARRAY['The specimen shields part of the sensitised sheet from ultraviolet light', 'The specimen releases a bleaching chemical into every exposed area', 'A lens enlarges a small negative of the specimen', 'Silver compounds darken only the paper beneath the specimen'], 'The specimen shields part of the sensitised sheet from ultraviolet light', 'The algae acts as an opaque object, leaving protected areas light. No bleaching secretion is described; the print is made by direct contact rather than lens enlargement; and cyanotype uses iron salts rather than silver compounds.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('ed78c8b8-0284-4ed3-9804-2e19b4182111'::uuid, '1bf80f0c-615d-4165-a80d-401e17931f39'::uuid, 'A transparent plan is placed against sensitised paper, but a small gap remains between the two surfaces. What problem is most consistent with the passage?', ARRAY['The final copy will automatically be enlarged beyond the original plan', 'The exposed regions will remain white because ultraviolet light cannot cross air', 'The process will switch from iron chemistry to silver chemistry', 'Fine details may become less sharply defined because close contact determines the image'], 'Fine details may become less sharply defined because close contact determines the image', 'The process depends on close contact, so a gap can weaken edge definition. Contact printing does not enlarge; ultraviolet light can cross the gap; and physical separation cannot change iron salts into a silver process.', 2, 'hard');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('0882b60a-8be3-4f98-9549-1d1625e36d5f'::uuid, '1bf80f0c-615d-4165-a80d-401e17931f39'::uuid, 'Which statement best captures the author''s view of cyanotype''s simplicity?', ARRAY['It ensures that every print remains unchanged under all display conditions', 'It makes the process practical, but does not remove chemical and conservation constraints', 'It means exposure time and contact have no effect on the image', 'It makes washing unnecessary once ultraviolet exposure is complete'], 'It makes the process practical, but does not remove chemical and conservation constraints', 'The final paragraph balances practical simplicity against sensitivity to alkalis, washing and display. The other options claim absolute stability or deny the importance of exposure, contact and washing, all of which the passage identifies as important.', 3, 'normal');
INSERT INTO verbal_reasoning_passages (id, title, body, is_free) VALUES ('8c61ed74-264f-43c5-8942-3931876ddffd'::uuid, 'Islands That Survived on Maps', 'A phantom island is land shown on charts although later investigation finds no island at the stated position. Such features arose for different reasons. A sailor might mistake a mirage or floating pumice for new land, while mistaken coordinates could relocate a genuine sighting. A copied report could then acquire authority as later mapmakers repeated it, particularly when surveying a remote ocean was expensive and a failure to sight low land did not conclusively prove absence.
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6d3449b4-bcdb-41a6-8dfc-818fefbdd23e'::uuid, '8c61ed74-264f-43c5-8942-3931876ddffd'::uuid, 'Every phantom island originated as a deliberate deception by a mapmaker.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'False. The passage lists mistaken clouds, pumice, misplaced real islands and stories as possible origins. These examples directly contradict the claim that every phantom was deliberate deception.', 0, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('3b3e3f36-6d6f-470e-bb19-06dfbd9fe60c'::uuid, '8c61ed74-264f-43c5-8942-3931876ddffd'::uuid, 'Several maps showing Frisland could have descended from a single claim.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'True. The passage explicitly says that several maps could descend from one claim and describes Frisland as widely copied from the Zeno narrative. The statement is directly entailed.', 1, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('9345713e-e0c6-440e-ac82-7ae29adbcc63'::uuid, '8c61ed74-264f-43c5-8942-3931876ddffd'::uuid, 'Before the 2012 voyage, every official hydrographic service still accepted Sandy Island as real.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'False. The passage explicitly says some official hydrographic charts had already omitted Sandy Island before the Southern Surveyor investigated its supposed position.', 2, 'normal');
INSERT INTO verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6992b836-c150-4015-8d2a-d05565da42f4'::uuid, '8c61ed74-264f-43c5-8942-3931876ddffd'::uuid, 'Sandy Island persisted in global datasets because their compilers deliberately ignored the 2012 voyage.', ARRAY['True', 'False', 'Can''t tell'], 'Can''t tell', 'Can''t tell. The passage says the outline persisted through inherited data and that the 2012 voyage found no island, but it does not describe a deliberate decision by compilers to ignore that voyage. Intent is neither confirmed nor contradicted.', 3, 'hard');
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('9a485920-7f6d-4434-84dd-e2c3768d27b0'::uuid, 'Ceramic Piece Classifications', 'syllogism'::dm_question_type, 'At a ceramics studio, all cobalt pieces are glazed. No glazed piece is porous. Some display pieces are cobalt. Every numbered piece is a display piece. Some porous pieces are numbered. For each statement, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, NULL, v_base_order + 1, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9a485920-7f6d-4434-84dd-e2c3768d27b0'::uuid, 'Some display pieces are glazed.', 'Yes', 'Some display pieces are cobalt, and every cobalt piece is glazed.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9a485920-7f6d-4434-84dd-e2c3768d27b0'::uuid, 'No cobalt piece is porous.', 'Yes', 'All cobalt pieces are glazed, while no glazed piece is porous.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9a485920-7f6d-4434-84dd-e2c3768d27b0'::uuid, 'Some numbered pieces are porous.', 'Yes', 'The premises explicitly state that some porous pieces are numbered.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9a485920-7f6d-4434-84dd-e2c3768d27b0'::uuid, 'Every display piece is glazed.', 'No', 'Only some display pieces are known to be cobalt and therefore glazed.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9a485920-7f6d-4434-84dd-e2c3768d27b0'::uuid, 'Some numbered pieces are cobalt.', 'No', 'Numbered pieces are display pieces, but display status does not imply cobalt.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('3cb31e21-99fc-495a-bbdb-1f91b0902ad6'::uuid, 'Conservation Flight Permissions', 'syllogism'::dm_question_type, 'For a conservation project, every thermal flight is a survey flight. All survey flights are authorised. No authorised flight passes over the reserve. Some night flights are thermal flights. Some training flights pass over the reserve. For each statement, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, NULL, v_base_order + 2, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('3cb31e21-99fc-495a-bbdb-1f91b0902ad6'::uuid, 'Some night flights are authorised.', 'Yes', 'Some night flights are thermal, thermal flights are surveys, and all surveys are authorised.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('3cb31e21-99fc-495a-bbdb-1f91b0902ad6'::uuid, 'No thermal flight passes over the reserve.', 'Yes', 'Every thermal flight is authorised through the survey rule, and authorised flights never pass over the reserve.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('3cb31e21-99fc-495a-bbdb-1f91b0902ad6'::uuid, 'Some training flights are not authorised.', 'Yes', 'Some training flights pass over the reserve, whereas no authorised flight does.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('3cb31e21-99fc-495a-bbdb-1f91b0902ad6'::uuid, 'Every night flight is a survey flight.', 'No', 'Only some night flights are stated to be thermal and hence surveys.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('3cb31e21-99fc-495a-bbdb-1f91b0902ad6'::uuid, 'No survey flight is a training flight.', 'No', 'A training flight outside the reserve could also be a survey; the premises do not exclude this.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('bc483abe-96f8-41ae-b4f9-bb138cb3bfed'::uuid, 'Cold-Chain Crate Routes', 'syllogism'::dm_question_type, 'Every crate is routed north or south, but never both. Every fragile crate is routed north. Every refrigerated crate is routed north. No refrigerated crate is urgent. Some crates are refrigerated, and some south-routed crates are urgent. For each statement, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, NULL, v_base_order + 3, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('bc483abe-96f8-41ae-b4f9-bb138cb3bfed'::uuid, 'Every fragile crate is not routed south.', 'Yes', 'Fragile crates go north, and no crate can be both north- and south-routed.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('bc483abe-96f8-41ae-b4f9-bb138cb3bfed'::uuid, 'Some north-routed crates are not urgent.', 'Yes', 'Some crates are refrigerated; refrigerated crates go north and are not urgent.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('bc483abe-96f8-41ae-b4f9-bb138cb3bfed'::uuid, 'No south-routed crate is refrigerated.', 'Yes', 'All refrigerated crates go north, and the two routes are exclusive.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('bc483abe-96f8-41ae-b4f9-bb138cb3bfed'::uuid, 'Some urgent crates are not routed north.', 'Yes', 'Some south-routed crates are urgent, and south-routed crates cannot also be north-routed.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('bc483abe-96f8-41ae-b4f9-bb138cb3bfed'::uuid, 'Some north-routed crates are fragile.', 'No', 'Fragile crates would be north-routed, but the premises do not say that any fragile crates exist.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('5384576a-eaaa-4199-b403-29f856f0a893'::uuid, 'Festival Mentor Roles', 'syllogism'::dm_question_type, 'At a festival, every mentor is a performer. No performer is a novice. Some coordinators are novices. Every coordinator is either a mentor or an auditor, but not both. Some auditors are performers. For each statement, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, NULL, v_base_order + 4, 'hard', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('5384576a-eaaa-4199-b403-29f856f0a893'::uuid, 'No mentor is a novice.', 'Yes', 'Every mentor is a performer, and no performer is a novice.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('5384576a-eaaa-4199-b403-29f856f0a893'::uuid, 'Some coordinators are auditors.', 'Yes', 'The novice coordinators cannot be mentors, so under the exclusive rule they must be auditors.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('5384576a-eaaa-4199-b403-29f856f0a893'::uuid, 'Some auditors are novices.', 'Yes', 'The novice coordinators identified as auditors provide the required existence.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('5384576a-eaaa-4199-b403-29f856f0a893'::uuid, 'No auditor is a mentor.', 'No', 'The auditor-versus-mentor exclusion applies to coordinators only, not to every auditor.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('5384576a-eaaa-4199-b403-29f856f0a893'::uuid, 'Some performers are not mentors.', 'No', 'The known auditor performers could also be mentors because they need not be coordinators.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('4deea9db-d47e-49e4-85d3-20692069915a'::uuid, 'Courier Loading Sequence', 'logic_puzzle'::dm_question_type, 'Four crates F, G, H and J are loaded in slots 1 to 4, one per slot. F is loaded before G. H is loaded immediately before J. F is not in slot 1. Which statement must be true?', NULL, NULL, NULL, 'A', 'The H-J consecutive block cannot occupy slots 2-3 or 3-4 because there would be no later place for G after a non-slot-1 F. Thus H-J occupy 1-2, leaving F-G in 3-4, so F must be in slot 3.', v_base_order + 5, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4deea9db-d47e-49e4-85d3-20692069915a'::uuid, 'A', 'F is in slot 3.', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4deea9db-d47e-49e4-85d3-20692069915a'::uuid, 'B', 'H is in slot 2.', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4deea9db-d47e-49e4-85d3-20692069915a'::uuid, 'C', 'J is in slot 4.', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4deea9db-d47e-49e4-85d3-20692069915a'::uuid, 'D', 'G is in slot 2.', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('327da49a-c1ec-4cbc-a80e-2dc8d032c2b5'::uuid, 'Exhibition Room Order', 'logic_puzzle'::dm_question_type, 'Artists P, Q, R and S each occupy one of four rooms in order from 1 to 4. P is in a room adjacent to Q. R is before P. S is not in room 4. Q is not in room 2. Which complete order could be correct?', NULL, NULL, NULL, 'A', 'R, S, P, Q satisfies every rule: P and Q are adjacent, R is before P, S is not fourth, and Q is not second. Each other order breaks at least one stated constraint.', v_base_order + 6, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('327da49a-c1ec-4cbc-a80e-2dc8d032c2b5'::uuid, 'A', 'R, S, P, Q', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('327da49a-c1ec-4cbc-a80e-2dc8d032c2b5'::uuid, 'B', 'S, Q, R, P', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('327da49a-c1ec-4cbc-a80e-2dc8d032c2b5'::uuid, 'C', 'P, R, S, Q', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('327da49a-c1ec-4cbc-a80e-2dc8d032c2b5'::uuid, 'D', 'R, P, Q, S', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('d8eb18f8-b743-4372-b477-2c6bdc58bb23'::uuid, 'Research Talk Programme', 'logic_puzzle'::dm_question_type, 'Six talks F, G, H, J, K and L are scheduled in slots 1 to 6. H is immediately after F. J is earlier than K. G is not adjacent to L. K is in slot 6. F is in neither slot 1 nor slot 5. Which order could be correct?', NULL, NULL, NULL, 'A', 'Only G, J, F, H, L, K meets every condition. B places G next to L, C puts F in slot 1, and D places G next to L.', v_base_order + 7, 'hard', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d8eb18f8-b743-4372-b477-2c6bdc58bb23'::uuid, 'A', 'G, J, F, H, L, K', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d8eb18f8-b743-4372-b477-2c6bdc58bb23'::uuid, 'B', 'J, F, H, G, L, K', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d8eb18f8-b743-4372-b477-2c6bdc58bb23'::uuid, 'C', 'F, H, J, L, G, K', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d8eb18f8-b743-4372-b477-2c6bdc58bb23'::uuid, 'D', 'G, L, J, F, H, K', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('69e9c207-6fbf-4fd2-bc8e-953bf2e925d0'::uuid, 'Three Delivery Assignments', 'logic_puzzle'::dm_question_type, 'Ali, Bea and Chen each make one delivery, using the red, blue or green route, at 09:00, 10:00 or 11:00. No route or time is repeated. Ali does not use red. The blue-route delivery is at 10:00. Bea delivers at 09:00. Chen uses green. Which statement must be true?', NULL, NULL, NULL, 'C', 'Bea cannot use blue because blue is at 10:00, and Chen already uses green. Bea therefore uses red, leaving blue at 10:00 for Ali. Chen then takes the remaining time, 11:00.', v_base_order + 8, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69e9c207-6fbf-4fd2-bc8e-953bf2e925d0'::uuid, 'A', 'Ali uses red at 09:00.', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69e9c207-6fbf-4fd2-bc8e-953bf2e925d0'::uuid, 'B', 'Bea uses blue at 09:00.', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69e9c207-6fbf-4fd2-bc8e-953bf2e925d0'::uuid, 'C', 'Chen uses green at 11:00.', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69e9c207-6fbf-4fd2-bc8e-953bf2e925d0'::uuid, 'D', 'Chen uses green at 10:00.', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('f60cd109-354f-4d41-957c-af8ba892328d'::uuid, 'Community Garden Attendance', 'interpreting_info'::dm_question_type, 'The table summarises bookings, attendance and late tool returns for three community-garden groups. Use only the table. For each statement, answer Yes if it is supported and No if it is not.', '{"headers":["Group","Booked","Attended","Late tool returns"],"rows":[["North","80","68","5"],["East","75","63","9"],["West","60","54","3"]]}'::jsonb, NULL, NULL, NULL, NULL, v_base_order + 9, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f60cd109-354f-4d41-957c-af8ba892328d'::uuid, 'The West group had an attendance rate of 90%.', 'Yes', 'West attendance was 54 out of 60 bookings, which is 90%.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f60cd109-354f-4d41-957c-af8ba892328d'::uuid, 'Twelve people booked with the East group but did not attend.', 'Yes', 'There were 75 East bookings and 63 attendances, a difference of 12.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f60cd109-354f-4d41-957c-af8ba892328d'::uuid, 'The North attendance rate was higher than the East attendance rate.', 'Yes', 'North was 68/80 = 85%, while East was 63/75 = 84%.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f60cd109-354f-4d41-957c-af8ba892328d'::uuid, 'Across the three groups, 185 people attended.', 'Yes', 'The total is 68 + 63 + 54 = 185.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f60cd109-354f-4d41-957c-af8ba892328d'::uuid, 'North recorded twice as many late tool returns as West.', 'No', 'Twice West''s three late returns would be six, not North''s five.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('c1ebad13-53b5-4b06-ab9b-635e6d4ce969'::uuid, 'Stage-Light Bench Tests', 'interpreting_info'::dm_question_type, 'Four stage-light models underwent bench testing. The table shows tests completed, tests passed and total energy used. Use only the table. For each statement, answer Yes if it is supported and No if it is not.', '{"headers":["Model","Tests completed","Tests passed","Energy used (kWh)"],"rows":[["Alpha","40","34","76"],["Beta","50","45","95"],["Gamma","30","27","66"],["Delta","60","48","120"]]}'::jsonb, NULL, NULL, NULL, NULL, v_base_order + 10, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('c1ebad13-53b5-4b06-ab9b-635e6d4ce969'::uuid, 'Alpha passed 85% of its tests.', 'Yes', 'Alpha passed 34 of 40 tests, and 34/40 = 85%.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('c1ebad13-53b5-4b06-ab9b-635e6d4ce969'::uuid, 'Beta failed five tests.', 'Yes', 'Beta completed 50 tests and passed 45, leaving five failures.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('c1ebad13-53b5-4b06-ab9b-635e6d4ce969'::uuid, 'Gamma used an average of 2.2 kWh per completed test.', 'Yes', 'Gamma used 66 kWh over 30 tests, so 66/30 = 2.2 kWh.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('c1ebad13-53b5-4b06-ab9b-635e6d4ce969'::uuid, 'Delta had a higher pass rate than Beta.', 'No', 'Delta passed 48/60 = 80%, below Beta''s 45/50 = 90%.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('c1ebad13-53b5-4b06-ab9b-635e6d4ce969'::uuid, 'The four models passed 154 tests altogether.', 'Yes', 'The pass total is 34 + 45 + 27 + 48 = 154.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('cf87523f-cfc0-483e-b25c-a3fadd2adeaa'::uuid, 'Estuary Sample Review', 'interpreting_info'::dm_question_type, 'A laboratory received 120 estuary samples: 45 from the upper reach, 38 from the middle reach and the remainder from the lower reach. Contamination was found in 18 upper, 12 middle and 10 lower samples. Fifteen contaminated samples were retested, and nine of those were confirmed contaminated. Use only this information. For each statement, answer Yes if it is supported and No if it is not.', NULL, NULL, NULL, NULL, NULL, v_base_order + 11, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cf87523f-cfc0-483e-b25c-a3fadd2adeaa'::uuid, 'Forty samples were initially found to be contaminated.', 'Yes', 'The initial contaminated total is 18 + 12 + 10 = 40.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cf87523f-cfc0-483e-b25c-a3fadd2adeaa'::uuid, 'The lower reach supplied 37 samples.', 'Yes', 'The lower count is 120 - 45 - 38 = 37.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cf87523f-cfc0-483e-b25c-a3fadd2adeaa'::uuid, 'The upper reach had the greatest contaminated proportion.', 'Yes', 'The proportions are 18/45 = 40%, 12/38 about 31.6%, and 10/37 about 27.0%.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cf87523f-cfc0-483e-b25c-a3fadd2adeaa'::uuid, 'More than half of the contaminated samples were retested.', 'No', 'Only 15 of 40 contaminated samples were retested, which is 37.5%.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cf87523f-cfc0-483e-b25c-a3fadd2adeaa'::uuid, 'Six retested samples were not confirmed contaminated.', 'Yes', 'Fifteen were retested and nine confirmed, leaving six not confirmed.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('ca5c9554-11f8-499d-b08c-560f986deda7'::uuid, 'Composite Panel Inspection', 'interpreting_info'::dm_question_type, 'A plant inspected 240 composite panels: 150 from line A and the remainder from line B. Twelve per cent of line A panels were defective, while 14 line B panels were defective. Of all defective panels, 20 were repaired; three repaired panels failed reinspection. Non-defective panels and repaired panels that passed were shipped. All others were scrapped. Use only this information. For each statement, answer Yes if it is supported and No if it is not.', NULL, NULL, NULL, NULL, NULL, v_base_order + 12, 'hard', FALSE, TRUE);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('ca5c9554-11f8-499d-b08c-560f986deda7'::uuid, 'Thirty-two panels were initially defective.', 'Yes', 'Line A had 12% of 150 = 18 defects; adding 14 from line B gives 32.', 1);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('ca5c9554-11f8-499d-b08c-560f986deda7'::uuid, 'Seventeen repaired panels were shipped.', 'Yes', 'Of 20 repaired panels, three failed reinspection, so 17 passed and were shipped.', 2);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('ca5c9554-11f8-499d-b08c-560f986deda7'::uuid, 'Line A had a lower defect rate than line B.', 'Yes', 'Line A was 12%, while line B was 14/90, about 15.6%.', 3);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('ca5c9554-11f8-499d-b08c-560f986deda7'::uuid, 'A total of 225 panels were shipped.', 'Yes', 'There were 240 - 32 = 208 non-defective panels and 17 repaired passes, totalling 225.', 4);
INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('ca5c9554-11f8-499d-b08c-560f986deda7'::uuid, 'Exactly 10% of all inspected panels were scrapped.', 'No', 'Fifteen were scrapped, and 15/240 = 6.25%, not 10%.', 5);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('eb38c6d4-6cd1-4ccb-8112-d1c305c2a514'::uuid, 'Advance Booking Cap for Rehearsal Rooms', 'recognising_assumptions'::dm_question_type, 'Should the civic arts centre limit each person to two advance rehearsal-room reservations at a time so that more users can obtain a slot?', NULL, NULL, NULL, 'B', 'B directly connects the proposed cap with improved access and supplies relevant local evidence about concentrated reservations, no-shows and denied users. The other arguments rely on convenience, loyalty or preference without showing the proposal would or would not achieve its aim.', v_base_order + 13, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('eb38c6d4-6cd1-4ccb-8112-d1c305c2a514'::uuid, 'A', 'Yes; two is an easy number for staff to remember.', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('eb38c6d4-6cd1-4ccb-8112-d1c305c2a514'::uuid, 'B', 'Yes; a six-month booking audit found that users holding three or more future reservations accounted for 31% of no-shows while 146 other users were denied a slot.', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('eb38c6d4-6cd1-4ccb-8112-d1c305c2a514'::uuid, 'C', 'No; frequent users have been attending the centre for many years.', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('eb38c6d4-6cd1-4ccb-8112-d1c305c2a514'::uuid, 'D', 'No; some users prefer to plan several months ahead.', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('d7446382-a588-4328-aeb1-de60d64b3735'::uuid, 'Returnable Cups at a Stadium', 'recognising_assumptions'::dm_question_type, 'Should a stadium require returnable cups at all events in order to reduce the total waste caused by drink containers?', NULL, NULL, NULL, 'C', 'C is the strongest argument because audited evidence from the same stadium directly measures the proposal against its stated aim and indicates that total waste increased. The other options are aesthetic, appeal to popularity, or cite preference rather than total waste.', v_base_order + 14, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d7446382-a588-4328-aeb1-de60d64b3735'::uuid, 'A', 'Yes; discarded cups look untidy after an event.', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d7446382-a588-4328-aeb1-de60d64b3735'::uuid, 'B', 'Yes; several famous stadiums use returnable cups.', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d7446382-a588-4328-aeb1-de60d64b3735'::uuid, 'C', 'No; the stadium''s audited season trial found that a 42% cup-loss rate and replacement production created 18% more container waste than its current system.', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d7446382-a588-4328-aeb1-de60d64b3735'::uuid, 'D', 'No; some spectators like taking branded cups home.', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('8f4fecdf-4094-4658-8d42-9f4486f147ac'::uuid, 'Live Ferry Occupancy Updates', 'recognising_assumptions'::dm_question_type, 'Should the harbour publish live ferry occupancy estimates to reduce passenger waiting and missed sailings?', NULL, NULL, NULL, 'A', 'A directly addresses both intended outcomes and provides comparative trial evidence. The other options concern appearance, individual preference or an irrelevant timetable design feature.', v_base_order + 15, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8f4fecdf-4094-4658-8d42-9f4486f147ac'::uuid, 'A', 'Yes; during an eight-week controlled trial, terminals displaying the estimates recorded 24% less average waiting and 19% fewer missed sailings than matched terminals without them.', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8f4fecdf-4094-4658-8d42-9f4486f147ac'::uuid, 'B', 'Yes; digital display boards make a harbour appear modern.', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8f4fecdf-4094-4658-8d42-9f4486f147ac'::uuid, 'C', 'No; some passengers enjoy deciding at the last minute.', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8f4fecdf-4094-4658-8d42-9f4486f147ac'::uuid, 'D', 'No; the harbour timetable already uses blue lettering.', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('c18aacbf-d7fb-4608-8b8e-55541ea335b8'::uuid, 'Automated Gallery Tours', 'recognising_assumptions'::dm_question_type, 'Should a gallery replace all staffed tours with automated audio tours to reduce operating costs without reducing visitor access?', NULL, NULL, NULL, 'D', 'D is the strongest argument because it uses relevant comparative evidence to challenge the claim that access would be preserved. The other arguments do not measure operating costs and access together.', v_base_order + 16, 'hard', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c18aacbf-d7fb-4608-8b8e-55541ea335b8'::uuid, 'A', 'Yes; audio devices can use the gallery''s new logo.', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c18aacbf-d7fb-4608-8b8e-55541ea335b8'::uuid, 'B', 'Yes; many visitors already own headphones.', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c18aacbf-d7fb-4608-8b8e-55541ea335b8'::uuid, 'C', 'No; some guides would miss speaking to visitors.', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c18aacbf-d7fb-4608-8b8e-55541ea335b8'::uuid, 'D', 'No; an independent access test found that 27% of participants needing hearing, cognitive or navigation adjustments could not complete the automated route, whereas staff adapted the tour for every participant.', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('ff689f1d-812d-4d06-987b-157184c7b9a0'::uuid, 'Archive Record Relationships', 'venn_diagram'::dm_question_type, 'An archive sorts files using the four categories in the key. Some files are in both Digitised and Loaned, and each group also has files outside the other. Some files are in both Digitised and Restricted, and each group also has files outside the other. Which diagram could represent all these relationships?', NULL, NULL, NULL, 'B', 'Only diagram B satisfies every stated relationship: Some files are in both Digitised and Loaned, and each group also has files outside the other. Some files are in both Digitised and Restricted, and each group also has files outside the other.', v_base_order + 17, 'normal', FALSE, TRUE);
