INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('f340da05-44d9-45d7-a68f-9a58ca742e89'::uuid, 'Wetland Survey Methods', 'venn_diagram'::dm_question_type, 'A conservation programme has 37 survey teams in total. The diagram shows exclusive counts for teams using aerial or ground surveys. How many teams use neither method?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Aerial survey","shape":"pentagon","geometry":{"cx":399.56,"cy":345.74,"width":654.85,"height":265.38,"rotationDeg":73.8}},{"id":"set2","label":"Ground survey","shape":"left_arrow","geometry":{"cx":405.62,"cy":491.43,"width":652.15,"height":264.34,"rotationDeg":175.9}}],"regions":[{"id":"set1_only:0","value":4},{"id":"set1_only:1","value":7},{"id":"set2_only:0","value":2},{"id":"set2_only:1","value":5},{"id":"set1_set2_only:0","value":8}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, NULL, 'C', 'The union contains 4 + 7 + 2 + 5 + 8 = 26 teams. Therefore 37 - 26 = 11 teams use neither method.', v_base_order + 19, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('f340da05-44d9-45d7-a68f-9a58ca742e89'::uuid, 'A', '7 teams', NULL, NULL, 1);
