INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('c64be728-1d79-4d5f-bbe2-6b3fddda2da6'::uuid, 'Food Hub Certifications', 'venn_diagram'::dm_question_type, 'The diagram shows exclusive counts of suppliers with three certifications. Which certification applies to the greatest total number of suppliers?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Organic","shape":"octagon","geometry":{"cx":407.92,"cy":400.19,"width":755.72,"height":879.55,"rotationDeg":-88.13}},{"id":"set2","label":"Fairtrade","shape":"parallelogram","geometry":{"cx":390.69,"cy":325.89,"width":238.49,"height":194.35,"rotationDeg":172.79}},{"id":"set3","label":"Locally sourced","shape":"teardrop","geometry":{"cx":351.78,"cy":424.35,"width":298.51,"height":254.93,"rotationDeg":50.62}}],"regions":[{"id":"set1_only:0","value":5},{"id":"set1_set2_only:0","value":8},{"id":"set1_set3_only:0","value":3},{"id":"set1_set2_set3_only:0","value":6}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, NULL, 'A', 'Organic: 22; Fairtrade: 14; Locally sourced: 9. The greatest total is 22.', v_base_order + 20, 'normal', FALSE, TRUE);
