INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('613beb96-5442-4418-b861-5e2338909f3d'::uuid, 'Training Module Combinations', 'venn_diagram'::dm_question_type, 'The diagram shows exclusive trainee counts for four modules. How many trainees take Safety together with Equipment or Fieldwork (or both), regardless of whether they also take Data?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Safety","shape":"rectangle","geometry":{"cx":413.79,"cy":379.06,"width":303.68,"height":250.63,"rotationDeg":-117.5}},{"id":"set2","label":"Equipment","shape":"heart","geometry":{"cx":539.75,"cy":519.94,"width":263.61,"height":231.27,"rotationDeg":21.16}},{"id":"set3","label":"Fieldwork","shape":"pentagon","geometry":{"cx":440.37,"cy":166.21,"width":291.35,"height":277.08,"rotationDeg":-43.41}},{"id":"set4","label":"Data","shape":"right_arrow","geometry":{"cx":528.3,"cy":294.8,"width":186.76,"height":236.89,"rotationDeg":95.77}}],"regions":[{"id":"set1_only:0","value":6},{"id":"set2_only:0","value":9},{"id":"set1_set2_only:0","value":4},{"id":"set3_only:0","value":7},{"id":"set1_set3_only:0","value":2},{"id":"set4_only:0","value":5},{"id":"set1_set4_only:0","value":8},{"id":"set3_set4_only:0","value":3},{"id":"set1_set3_set4_only:0","value":6}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, NULL, 'C', 'The qualifying faces are inside Safety and also inside Equipment or Fieldwork. Their values are counted once each: 4 + 2 + 6 = 12.', v_base_order + 21, 'hard', FALSE, TRUE);
