INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('6ee93329-fe3f-4936-9c43-307155a23669'::uuid, 'Council Proposal Themes', 'venn_diagram'::dm_question_type, 'The diagram shows exclusive counts of proposals covering five themes. How many proposals cover Housing but do not cover Transport?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Climate","shape":"square","geometry":{"cx":373.63,"cy":610.66,"width":253.74,"height":253.74,"rotationDeg":96.67}},{"id":"set2","label":"Transport","shape":"ellipse","geometry":{"cx":191.31,"cy":205.11,"width":309.12,"height":222.64,"rotationDeg":-63.74}},{"id":"set3","label":"Housing","shape":"diamond","geometry":{"cx":678.68,"cy":274.97,"width":220.58,"height":203.13,"rotationDeg":-168.3}},{"id":"set4","label":"Health","shape":"star","geometry":{"cx":213.47,"cy":357.31,"width":288.74,"height":280.28,"rotationDeg":22.79}},{"id":"set5","label":"Education","shape":"trapezoid","geometry":{"cx":451.36,"cy":642.1,"width":276.66,"height":273.29,"rotationDeg":169.83}}],"regions":[{"id":"set1_only:0","value":7},{"id":"set2_only:0","value":2},{"id":"set3_only:0","value":5},{"id":"set4_only:0","value":8},{"id":"set2_set4_only:0","value":3},{"id":"set5_only:0","value":6},{"id":"set1_set5_only:0","value":9}],"labelStyle":{"minFontSize":22,"preferredFontSize":26,"padding":3}}'::jsonb, NULL, 'C', 'Include every face inside Housing that lies outside Transport. The qualifying values give 5 = 5.', v_base_order + 22, 'normal', FALSE, TRUE);
