INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('3e00d4d4-f29f-406f-8a9b-caf9b8575cae'::uuid, 'Workspace Permit Totals', 'venn_diagram'::dm_question_type, 'The diagram shows exclusive counts for four workspace permissions. What is the difference between the total number of Cycle-access permits and the total number of Late-access permits?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Cycle access","shape":"circle","geometry":{"cx":461.75,"cy":391.16,"width":260.28,"height":260.28,"rotationDeg":0}},{"id":"set2","label":"Late access","shape":"square","geometry":{"cx":335.3,"cy":307.48,"width":272.19,"height":272.19,"rotationDeg":70.87}},{"id":"set3","label":"Weekend access","shape":"ellipse","geometry":{"cx":473.23,"cy":211.51,"width":287.2,"height":234.45,"rotationDeg":-68.16}},{"id":"set4","label":"Equipment access","shape":"diamond","geometry":{"cx":353.38,"cy":131.9,"width":299.27,"height":310.77,"rotationDeg":-98.27}}],"regions":[{"id":"set1_only:0","value":8},{"id":"set2_only:0","value":3},{"id":"set1_set2_only:0","value":6},{"id":"set3_only:0","value":9},{"id":"set1_set3_only:0","value":4},{"id":"set2_set3_only:0","value":7},{"id":"set1_set2_set3_only:0","value":2},{"id":"set4_only:0","value":5},{"id":"set2_set4_only:0","value":8},{"id":"set3_set4_only:0","value":3},{"id":"set2_set3_set4_only:0","value":6}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, NULL, 'C', 'Cycle access totals 8 + 6 + 4 + 2 = 20; Late access totals 3 + 6 + 7 + 2 + 8 + 6 = 32. The difference is 12.', v_base_order + 23, 'normal', FALSE, TRUE);
