INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('0842c146-0dc6-46a6-a4a7-5f2dd32b6038'::uuid, 'Parcel Handling Labels', 'venn_diagram'::dm_question_type, 'The diagram shows exclusive parcel counts for three handling labels. Which statement is true?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Refrigerated","shape":"circle","geometry":{"cx":296.16,"cy":315.07,"width":314.02,"height":314.02,"rotationDeg":0}},{"id":"set2","label":"Urgent","shape":"hexagon","geometry":{"cx":399.58,"cy":517.5,"width":275.33,"height":391.61,"rotationDeg":38.17}},{"id":"set3","label":"Tracked","shape":"left_arrow","geometry":{"cx":479.98,"cy":352.69,"width":335,"height":292.65,"rotationDeg":109.9}}],"regions":[{"id":"set1_only:0","value":9},{"id":"set2_only:0","value":4},{"id":"set1_set2_only:0","value":7},{"id":"set3_only:0","value":2},{"id":"set1_set3_only:0","value":5},{"id":"set2_set3_only:0","value":8},{"id":"set1_set2_set3_only:0","value":3}],"labelStyle":{"minFontSize":20,"preferredFontSize":24,"padding":3}}'::jsonb, NULL, 'C', 'The complete Refrigerated set totals 9 + 7 + 5 + 3 = 24. Checking the corresponding totals shows that A, B and D are false.', v_base_order + 24, 'hard', FALSE, TRUE);
