INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('0842c146-0dc6-46a6-a4a7-5f2dd32b6038'::uuid, 'C', 'There are exactly 24 Refrigerated parcels.', NULL, NULL, 3);
