INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('0142bd31-4693-4403-a517-c3aed267e756'::uuid, 'Offline Charging Lockers', 'probabilistic'::dm_question_type, 'Twelve charging lockers are available, of which three are offline. Two different lockers are selected at random without replacement. What is the probability that exactly one selected locker is offline?', NULL, NULL, NULL, 'C', 'There are C(12,2) = 66 unordered pairs. An exactly-one-offline pair can be formed in 3 x 9 = 27 ways, so the probability is 27/66 = 9/22.', v_base_order + 25, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('0142bd31-4693-4403-a517-c3aed267e756'::uuid, 'A', '1/22', NULL, NULL, 1);
