INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('153c56ae-47a1-4c06-ac9f-14475072a649'::uuid, 'Independent Calibration Checks', 'probabilistic'::dm_question_type, 'Two independent calibration systems assess the same instrument. System A gives an accurate result with probability 0.90 and system B with probability 0.80. What is the probability that exactly one system gives an accurate result?', NULL, NULL, NULL, 'B', 'Exactly one is accurate in two disjoint ways: A accurate and B inaccurate gives 0.90 x 0.20 = 0.18; A inaccurate and B accurate gives 0.10 x 0.80 = 0.08. The total is 0.26.', v_base_order + 26, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('153c56ae-47a1-4c06-ac9f-14475072a649'::uuid, 'A', '0.18', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('153c56ae-47a1-4c06-ac9f-14475072a649'::uuid, 'B', '0.26', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('153c56ae-47a1-4c06-ac9f-14475072a649'::uuid, 'C', '0.72', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('153c56ae-47a1-4c06-ac9f-14475072a649'::uuid, 'D', '0.98', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('dfd41b40-6483-4f0a-8459-777010ea598c'::uuid, 'Priority Parcel Route', 'probabilistic'::dm_question_type, 'A depot processed 40 parcels. Twenty-two travelled by rail. Fourteen parcels were priority parcels, and eight of those priority parcels travelled by rail. One priority parcel is chosen at random. What is the probability that it travelled by rail?', NULL, NULL, NULL, 'B', 'The condition restricts the sample space to the 14 priority parcels. Eight of those used rail, so the probability is 8/14 = 4/7.', v_base_order + 27, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('dfd41b40-6483-4f0a-8459-777010ea598c'::uuid, 'A', '1/5', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('dfd41b40-6483-4f0a-8459-777010ea598c'::uuid, 'B', '4/7', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('dfd41b40-6483-4f0a-8459-777010ea598c'::uuid, 'C', '7/11', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('dfd41b40-6483-4f0a-8459-777010ea598c'::uuid, 'D', '8/11', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('2c2ae70a-20c9-4fd2-9555-0eab30574364'::uuid, 'Pop-up Equipment Return', 'probabilistic'::dm_question_type, 'A supplier earns a net £40 if rented equipment is returned on time, £10 if it is one day late, and loses £20 if it is more than one day late. The respective probabilities are 0.50, 0.30 and 0.20. What is the expected net amount per rental?', NULL, NULL, NULL, 'B', 'The expected amount is (0.50 x £40) + (0.30 x £10) + (0.20 x -£20) = £20 + £3 - £4 = £19.', v_base_order + 28, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2c2ae70a-20c9-4fd2-9555-0eab30574364'::uuid, 'A', '£14', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2c2ae70a-20c9-4fd2-9555-0eab30574364'::uuid, 'B', '£19', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2c2ae70a-20c9-4fd2-9555-0eab30574364'::uuid, 'C', '£22', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2c2ae70a-20c9-4fd2-9555-0eab30574364'::uuid, 'D', '£25', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('1d74ee87-18c2-4484-a845-86e50f1cf853'::uuid, 'Corrupted Design File', 'probabilistic'::dm_question_type, 'Sixty per cent of a studio''s design files use format X and 40% use format Y. Two per cent of X files and 5% of Y files are corrupted. A randomly selected file is known to be corrupted. What is the probability that it uses format Y?', NULL, NULL, NULL, 'C', 'The joint probabilities of corruption are 0.60 x 0.02 = 0.012 for X and 0.40 x 0.05 = 0.020 for Y. Conditional on corruption, the Y share is 0.020/(0.012 + 0.020) = 0.020/0.032 = 5/8.', v_base_order + 29, 'hard', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('1d74ee87-18c2-4484-a845-86e50f1cf853'::uuid, 'A', '2/5', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('1d74ee87-18c2-4484-a845-86e50f1cf853'::uuid, 'B', '1/2', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('1d74ee87-18c2-4484-a845-86e50f1cf853'::uuid, 'C', '5/8', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('1d74ee87-18c2-4484-a845-86e50f1cf853'::uuid, 'D', '3/4', NULL, NULL, 4);
INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('69ab3f89-eabb-4b5b-b9a0-1989f6d19bfe'::uuid, 'Independent Server Interruptions', 'probabilistic'::dm_question_type, 'Three independent servers complete an overnight task without interruption with probabilities 0.95, 0.90 and 0.80. What is the probability that at least one server is interrupted?', NULL, NULL, NULL, 'C', 'The probability that none is interrupted is 0.95 x 0.90 x 0.80 = 0.684. Therefore the probability of at least one interruption is 1 - 0.684 = 0.316.', v_base_order + 30, 'normal', FALSE, TRUE);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69ab3f89-eabb-4b5b-b9a0-1989f6d19bfe'::uuid, 'A', '0.116', NULL, NULL, 1);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69ab3f89-eabb-4b5b-b9a0-1989f6d19bfe'::uuid, 'B', '0.266', NULL, NULL, 2);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69ab3f89-eabb-4b5b-b9a0-1989f6d19bfe'::uuid, 'C', '0.316', NULL, NULL, 3);
INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('69ab3f89-eabb-4b5b-b9a0-1989f6d19bfe'::uuid, 'D', '0.684', NULL, NULL, 4);
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('c3d65128-63bc-473c-af12-a9716f3a9890'::uuid, '715ce681-9582-492d-8337-d0cd0fdec75f', 'Costume Dye Batch Log', '{"type":"table","context":"A theatre workshop records four fabric-dye batches. Mixture volume is concentrate plus water.","data":{"headers":["Dye","Fabric dyed (kg)","Concentrate (L)","Water (L)","Panels inspected","Defective panels"],"rows":[["Indigo","240","18","102","600","12"],["Saffron","180","12","78","450","9"],["Crimson","300","21","129","750","15"],["Jade","210","14","91","525","7"]]}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('3491313e-de2e-4e42-8ace-d576eb811dfd'::uuid, 'c3d65128-63bc-473c-af12-a9716f3a9890'::uuid, 'f936a914-fc72-485b-90ae-2ccdad5b15d4', 'What was the total dye-mixture volume used for the Crimson batch?', '[{"label":"A","text":"105 L"},{"label":"B","text":"129 L"},{"label":"C","text":"143 L"},{"label":"D","text":"150 L"},{"label":"E","text":"171 L"}]'::jsonb, 'D', 'Crimson used 21 L of concentrate and 129 L of water. Total mixture = 21 + 129 = 150 L. No rounding is needed. The answer is 150 L.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('d72a0f08-7461-46f8-b157-ea62e76a5b37'::uuid, 'c3d65128-63bc-473c-af12-a9716f3a9890'::uuid, '3d52c273-b537-4091-b315-79813c241512', 'What percentage of the Indigo dye mixture was concentrate?', '[{"label":"A","text":"12%"},{"label":"B","text":"15%"},{"label":"C","text":"17.6%"},{"label":"D","text":"18%"},{"label":"E","text":"20%"}]'::jsonb, 'B', 'Indigo mixture volume = 18 + 102 = 120 L. Concentrate percentage = 18 / 120 × 100 = 15%. The answer is 15%.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('66beef97-495f-4852-abbb-d0ab19792787'::uuid, 'c3d65128-63bc-473c-af12-a9716f3a9890'::uuid, 'f1958b04-865c-4f6d-a4e2-61039148c64e', 'How many kilograms of fabric were dyed per litre of concentrate in the Saffron batch?', '[{"label":"A","text":"10 kg/L"},{"label":"B","text":"12 kg/L"},{"label":"C","text":"15 kg/L"},{"label":"D","text":"18 kg/L"},{"label":"E","text":"21 kg/L"}]'::jsonb, 'C', 'The Saffron batch dyed 180 kg using 12 L of concentrate. Rate = 180 / 12 = 15 kg/L. The answer is 15 kg/L.', 2, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('01868a83-2c89-492a-98a4-e077a8a102e0'::uuid, 'c3d65128-63bc-473c-af12-a9716f3a9890'::uuid, '474d8c37-2a73-443f-8904-da4b2fcd3390', 'Across all four batches, another 175 panels are inspected and 2 are defective. What is the new overall defective percentage?', '[{"label":"A","text":"1.6%"},{"label":"B","text":"1.7%"},{"label":"C","text":"1.8%"},{"label":"D","text":"1.9%"},{"label":"E","text":"2.0%"}]'::jsonb, 'C', 'Existing defects = 12 + 9 + 15 + 7 = 43 and existing panels = 600 + 450 + 750 + 525 = 2,325. Including the new work gives 45 defects among 2,500 panels. Percentage = 45 / 2,500 × 100 = 1.8%. The answer is 1.8%.', 3, 'hard');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('48c2c64e-3321-43cd-b1ec-51f65c289187'::uuid, 'e8ce05bc-b74f-4ec6-9084-912ededd4219', 'Abyssal Drone Survey', '{"type":"table","context":"A marine research team records autonomous-drone surveys. Total dive time equals dives multiplied by minutes per dive.","data":{"headers":["Sector","Grid area (km²)","Dives","Minutes per dive","Usable images","Raw data (GB)"],"rows":[["Ridge","18","6","42","1680","96"],["Trench","24","8","55","2280","144"],["Vent","15","5","48","1425","90"],["Plain","30","10","36","2700","180"]]}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('20fade03-60ac-482c-b1d0-e7ebb7d94fb3'::uuid, '48c2c64e-3321-43cd-b1ec-51f65c289187'::uuid, '2dbf36fe-a1f7-4683-9613-0fccc0dcb500', 'How many minutes of dive time were spent surveying the Vent sector?', '[{"label":"A","text":"180 min"},{"label":"B","text":"210 min"},{"label":"C","text":"240 min"},{"label":"D","text":"250 min"},{"label":"E","text":"288 min"}]'::jsonb, 'C', 'Vent had 5 dives of 48 minutes. Total time = 5 × 48 = 240 minutes. The answer is 240 min.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('a80d3b59-ce82-4e6d-a3e4-13fb5831f1ee'::uuid, '48c2c64e-3321-43cd-b1ec-51f65c289187'::uuid, 'b25a58a4-ddcf-4a64-bccf-ca7d630d88a2', 'How many usable images per square kilometre were produced for the Ridge sector, to the nearest 0.1?', '[{"label":"A","text":"88.0"},{"label":"B","text":"90.0"},{"label":"C","text":"92.3"},{"label":"D","text":"93.3"},{"label":"E","text":"96.0"}]'::jsonb, 'D', 'Ridge produced 1,680 images across 18 km². Images per km² = 1,680 / 18 = 93.333..., which rounds to 93.3. The answer is 93.3.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('96472079-3248-40c5-8fc1-bec33a2d774b'::uuid, '48c2c64e-3321-43cd-b1ec-51f65c289187'::uuid, '63928e81-5685-48a4-92af-eb0678266bdc', 'Compressed Trench data occupies 35% of its raw size. What is the compressed size?', '[{"label":"A","text":"35.0 GB"},{"label":"B","text":"43.2 GB"},{"label":"C","text":"50.4 GB"},{"label":"D","text":"54.6 GB"},{"label":"E","text":"93.6 GB"}]'::jsonb, 'C', 'Trench raw data is 144 GB. Compressed size = 144 × 0.35 = 50.4 GB. The answer is 50.4 GB.', 2, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6edbf5ff-1b47-4db0-bc20-c65f02c8965e'::uuid, '48c2c64e-3321-43cd-b1ec-51f65c289187'::uuid, 'a8f59488-b59a-4d57-9a7f-c35d0a9cbccc', 'Which sector produced the greatest number of usable images per hour of dive time?', '[{"label":"A","text":"Ridge"},{"label":"B","text":"Trench"},{"label":"C","text":"Vent"},{"label":"D","text":"Plain"},{"label":"E","text":"Ridge and Plain equal"}]'::jsonb, 'D', 'Convert each total dive time to hours, then divide images by hours: Ridge = 1,680 / (252/60) = 400; Trench = 2,280 / (440/60) = 310.9; Vent = 1,425 / (240/60) = 356.25; Plain = 2,700 / (360/60) = 450 images/hour. Plain is greatest. The answer is Plain.', 3, 'hard');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('fdd3de33-2fc5-4e6b-9155-d7d5ffb19083'::uuid, 'ce65b5ce-2a0f-4c05-b6ec-eb3179a9ac46', 'Seed Bank Intake', '{"type":"bar_chart","context":"A seed bank tested four incoming collections. ''Viable'' seeds are the subset that passed germination testing.","data":{"title":"Seeds received and viable","labels":["Lotus","Fir","Sedge","Orchid"],"series":[{"name":"Received","values":[480,360,600,300]},{"name":"Viable","values":[408,306,510,255]}],"yAxisLabel":"Number of seeds","unit":"seeds"}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('98854fdb-429e-4988-9e03-fc6d02252d89'::uuid, 'fdd3de33-2fc5-4e6b-9155-d7d5ffb19083'::uuid, 'bc6b4a32-7acb-4e0e-9d6f-b73a74e2a35c', 'How many viable seeds were recorded in total?', '[{"label":"A","text":"1419"},{"label":"B","text":"1440"},{"label":"C","text":"1459"},{"label":"D","text":"1479"},{"label":"E","text":"1500"}]'::jsonb, 'D', 'Total viable seeds = 408 + 306 + 510 + 255 = 1,479 seeds. The answer is 1,479.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('da940bcd-93f3-42ec-91d4-fd6f020ad57b'::uuid, 'fdd3de33-2fc5-4e6b-9155-d7d5ffb19083'::uuid, 'aa2ef633-b741-482d-b7c5-fb3c8a4f1d95', 'What percentage of Orchid seeds were viable?', '[{"label":"A","text":"75%"},{"label":"B","text":"80%"},{"label":"C","text":"82%"},{"label":"D","text":"85%"},{"label":"E","text":"90%"}]'::jsonb, 'D', 'Orchid had 255 viable seeds from 300 received. Percentage = 255 / 300 × 100 = 85%. The answer is 85%.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('cc789d46-2efa-461b-8f11-5ac3c3c6cb04'::uuid, 'fdd3de33-2fc5-4e6b-9155-d7d5ffb19083'::uuid, '24b77545-6f75-4066-abb9-3533d84621ac', 'How many Sedge seeds failed the viability test?', '[{"label":"A","text":"75"},{"label":"B","text":"80"},{"label":"C","text":"85"},{"label":"D","text":"90"},{"label":"E","text":"95"}]'::jsonb, 'D', 'Failed Sedge seeds = received − viable = 600 − 510 = 90 seeds. The answer is 90.', 2, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6a5cf12d-feb9-4a09-99bc-48318eaa8288'::uuid, 'fdd3de33-2fc5-4e6b-9155-d7d5ffb19083'::uuid, 'be70c1bb-e846-49f7-b688-4cb952b9e718', 'Next year Lotus intake is projected to rise by 12%, with the same viability rate. Approximately how many viable Lotus seeds are expected?', '[{"label":"A","text":"449"},{"label":"B","text":"454"},{"label":"C","text":"457"},{"label":"D","text":"462"},{"label":"E","text":"480"}]'::jsonb, 'C', 'Current Lotus viability rate = 408 / 480 = 85%. Projected intake = 480 × 1.12 = 537.6. Expected viable = 537.6 × 0.85 = 456.96, which rounds to 457 seeds. The answer is 457.', 3, 'hard');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('ba2bcc07-1ccb-47d9-aa54-1dba8a36dc8c'::uuid, 'ea08232e-6151-4165-a9fb-7f75836fc992', 'Coastal Beacon Batteries', '{"type":"line_graph","context":"Engineers recorded the remaining charge in two solar beacon batteries during one cloudy day.","data":{"title":"Battery charge through the day","labels":["06:00","09:00","12:00","15:00","18:00"],"series":[{"name":"North Beacon","values":[96,88,79,67,52]},{"name":"South Beacon","values":[92,86,78,71,65]}],"yAxisLabel":"Charge remaining (%)","unit":"%"}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('d1ae02b1-b7fa-4939-8411-712ff8f5c1fe'::uuid, 'ba2bcc07-1ccb-47d9-aa54-1dba8a36dc8c'::uuid, '16c2a58c-7238-4774-8525-9c57b25130ba', 'By how many percentage points did the North Beacon charge fall from 06:00 to 18:00?', '[{"label":"A","text":"38"},{"label":"B","text":"40"},{"label":"C","text":"42"},{"label":"D","text":"44"},{"label":"E","text":"46"}]'::jsonb, 'D', 'North Beacon fell from 96% to 52%. Decrease = 96 − 52 = 44 percentage points. The answer is 44.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('537e0be1-4bbe-415b-9507-a793e0ca7ba5'::uuid, 'ba2bcc07-1ccb-47d9-aa54-1dba8a36dc8c'::uuid, 'a1701e6b-4089-4da5-8efa-e0539f4dae95', 'What was the mean South Beacon charge across the five readings?', '[{"label":"A","text":"76.4%"},{"label":"B","text":"77.4%"},{"label":"C","text":"78.0%"},{"label":"D","text":"78.4%"},{"label":"E","text":"79.2%"}]'::jsonb, 'D', 'Mean = (92 + 86 + 78 + 71 + 65) / 5 = 392 / 5 = 78.4%. The answer is 78.4%.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6be05ebe-0baa-4e27-990f-d635c8c542cc'::uuid, 'ba2bcc07-1ccb-47d9-aa54-1dba8a36dc8c'::uuid, 'f03aa6b2-a41a-42ae-bcb0-836fef9f5e75', 'If the North Beacon continued after 18:00 at its average hourly rate of charge loss from 12:00 to 18:00, what charge would remain at 21:00?', '[{"label":"A","text":"35.0%"},{"label":"B","text":"36.5%"},{"label":"C","text":"38.5%"},{"label":"D","text":"40.0%"},{"label":"E","text":"44.5%"}]'::jsonb, 'C', 'From 12:00 to 18:00, charge fell from 79% to 52%: 27 points in 6 hours, or 4.5 points/hour. In the next 3 hours it would lose 13.5 points. Remaining charge = 52 − 13.5 = 38.5%. The answer is 38.5%.', 2, 'hard');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('094d219c-e264-45ea-8ad0-569851c9d3f1'::uuid, '0581bbb0-7d36-47db-a882-0b1802419d6d', 'Planetarium Ticket Allocation', '{"type":"pie_chart","context":"A planetarium allocated 1,250 tickets for a science festival. The chart shows the initial allocation.","data":{"title":"Initial ticket allocation","segments":[{"label":"School groups","value":36},{"label":"Families","value":28},{"label":"Adults","value":22},{"label":"Concessions","value":14}],"unit":"%"}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('5f8067d6-bcae-4ee4-8cb1-1b1fc60bf776'::uuid, '094d219c-e264-45ea-8ad0-569851c9d3f1'::uuid, 'a042857f-e688-4f1e-a3da-fab3ad74438b', 'How many tickets were allocated to families?', '[{"label":"A","text":"300"},{"label":"B","text":"325"},{"label":"C","text":"350"},{"label":"D","text":"375"},{"label":"E","text":"400"}]'::jsonb, 'C', 'Family tickets = 28% of 1,250 = 0.28 × 1,250 = 350 tickets. The answer is 350.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('62cfe792-3b26-440a-9099-e2122244fac2'::uuid, '094d219c-e264-45ea-8ad0-569851c9d3f1'::uuid, '45d8b19c-5b77-450d-babc-9523f7c0571a', 'What is the ratio of school-group tickets to concession tickets in its simplest form?', '[{"label":"A","text":"7:18"},{"label":"B","text":"9:4"},{"label":"C","text":"18:7"},{"label":"D","text":"18:14"},{"label":"E","text":"36:7"}]'::jsonb, 'C', 'The allocation ratio is 36:14. Dividing both parts by 2 gives 18:7. The answer is 18:7.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('98516ca1-ad02-4e1e-a1d3-bb6e11879fca'::uuid, '094d219c-e264-45ea-8ad0-569851c9d3f1'::uuid, 'c70460bd-0eb6-428f-b09c-6181e3b691bc', 'Ten per cent of the school-group tickets are returned and all are reallocated to adults. What percentage of all 1,250 tickets is then allocated to adults?', '[{"label":"A","text":"24.4%"},{"label":"B","text":"25.0%"},{"label":"C","text":"25.6%"},{"label":"D","text":"26.0%"},{"label":"E","text":"32.0%"}]'::jsonb, 'C', 'School tickets = 36% of 1,250 = 450. Returned tickets = 10% of 450 = 45. Adult tickets originally = 22% of 1,250 = 275, so the new adult allocation is 320. Percentage = 320 / 1,250 × 100 = 25.6%. The answer is 25.6%.', 2, 'hard');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('24a36193-9d11-41eb-98ad-2d2f8b43090a'::uuid, '4600699f-4813-4c7e-9877-4107f159db8a', 'Ceramic Tile Firing Trial', '{"type":"scatter_plot","context":"A ceramics studio tested one tile sample at each kiln temperature. Flexural strength is measured in megapascals (MPa).","data":{"title":"Kiln temperature and tile strength","xAxisLabel":"Firing temperature (°C)","yAxisLabel":"Strength (MPa)","series":[{"name":"Tile samples","points":[{"x":780,"y":32,"label":"A"},{"x":820,"y":38,"label":"B"},{"x":860,"y":47,"label":"C"},{"x":900,"y":54,"label":"D"},{"x":940,"y":61,"label":"E"},{"x":980,"y":59,"label":"F"}]}]}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('ad375570-898d-4610-9368-15727eb9c182'::uuid, '24a36193-9d11-41eb-98ad-2d2f8b43090a'::uuid, '1b1f466b-fe9f-4ccf-9274-c1884a71500b', 'Between which consecutive temperatures was the greatest increase in strength recorded?', '[{"label":"A","text":"780–820°C"},{"label":"B","text":"820–860°C"},{"label":"C","text":"860–900°C"},{"label":"D","text":"900–940°C"},{"label":"E","text":"940–980°C"}]'::jsonb, 'B', 'Consecutive changes are +6, +9, +7, +7 and −2 MPa. The greatest increase is 9 MPa from 820°C to 860°C. The answer is 820–860°C.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('e39845f6-6e0e-4215-b756-8f9445dba56e'::uuid, '24a36193-9d11-41eb-98ad-2d2f8b43090a'::uuid, '966bb7e5-9bcb-4111-b270-0f7d1208a961', 'What was the percentage increase in strength from sample A to sample E, to the nearest 0.1%?', '[{"label":"A","text":"81.3%"},{"label":"B","text":"87.5%"},{"label":"C","text":"90.6%"},{"label":"D","text":"93.8%"},{"label":"E","text":"96.9%"}]'::jsonb, 'C', 'Strength increased from 32 MPa to 61 MPa, a rise of 29 MPa. Percentage increase = 29 / 32 × 100 = 90.625%, which rounds to 90.6%. The answer is 90.6%.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('8743a45d-38f4-4789-9cc1-db0dbeb88b9d'::uuid, '24a36193-9d11-41eb-98ad-2d2f8b43090a'::uuid, '71fc89c2-7ab4-489e-acb1-0613d8cf3ece', 'What is the median strength of the six samples?', '[{"label":"A","text":"47.0 MPa"},{"label":"B","text":"49.0 MPa"},{"label":"C","text":"50.5 MPa"},{"label":"D","text":"54.0 MPa"},{"label":"E","text":"56.5 MPa"}]'::jsonb, 'C', 'Order the strengths: 32, 38, 47, 54, 59, 61. With six values, the median is the mean of the third and fourth: (47 + 54) / 2 = 50.5 MPa. The answer is 50.5 MPa.', 2, 'normal');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('2d4df775-4e17-4dbc-a857-1aba3e7c4491'::uuid, '88f2fe67-cc93-4268-86fa-33b43cd0c03f', 'Archaeological Survey Paths', '{"type":"network_diagram","context":"Edge labels show walking distances between survey locations. Paths may be used in either direction.","data":{"title":"Survey-site walking network","nodes":[{"id":"camp","label":"Camp","x":0.12,"y":0.45},{"id":"ridge","label":"Ridge","x":0.34,"y":0.18},{"id":"wadi","label":"Wadi","x":0.35,"y":0.72},{"id":"tell","label":"Tell","x":0.58,"y":0.43},{"id":"oasis","label":"Oasis","x":0.62,"y":0.82},{"id":"vault","label":"Vault","x":0.86,"y":0.38}],"edges":[{"from":"camp","to":"ridge","label":"4.8 km"},{"from":"ridge","to":"tell","label":"3.6 km"},{"from":"camp","to":"wadi","label":"5.2 km"},{"from":"wadi","to":"tell","label":"2.9 km"},{"from":"tell","to":"vault","label":"4.1 km"},{"from":"ridge","to":"vault","label":"6.5 km"},{"from":"wadi","to":"oasis","label":"3.3 km"},{"from":"oasis","to":"vault","label":"5.0 km"}]}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('90deaa71-8bc1-463c-a7ec-dd60533fa7ad'::uuid, '2d4df775-4e17-4dbc-a857-1aba3e7c4491'::uuid, 'e97f3a47-2d95-41fb-b7cd-3c102bbd9a10', 'What is the distance of a round trip from Camp to Wadi using the direct path?', '[{"label":"A","text":"5.2 km"},{"label":"B","text":"8.1 km"},{"label":"C","text":"9.6 km"},{"label":"D","text":"10.4 km"},{"label":"E","text":"11.7 km"}]'::jsonb, 'D', 'The direct Camp–Wadi path is 5.2 km each way. Round trip = 2 × 5.2 = 10.4 km. The answer is 10.4 km.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('ef6f8743-f59a-42d7-96ca-8eb86f7d8e7b'::uuid, '2d4df775-4e17-4dbc-a857-1aba3e7c4491'::uuid, '2f30e598-145c-4250-83b6-9a7a19d44b30', 'Rockfall adds a detour equal to 25% of the Ridge–Tell path''s original distance. What is the revised distance for the route Camp–Ridge–Tell–Vault?', '[{"label":"A","text":"12.5 km"},{"label":"B","text":"12.9 km"},{"label":"C","text":"13.0 km"},{"label":"D","text":"13.4 km"},{"label":"E","text":"14.3 km"}]'::jsonb, 'D', 'The added detour is 25% of 3.6 km: 0.25 × 3.6 = 0.9 km, so Ridge–Tell becomes 4.5 km. Revised route distance = 4.8 + 4.5 + 4.1 = 13.4 km. No rounding is needed. The answer is 13.4 km.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('9317a2e8-1dff-497e-a88e-44b7be7a78a0'::uuid, '2d4df775-4e17-4dbc-a857-1aba3e7c4491'::uuid, '28df277b-aa1e-4fc8-b434-cb6f16b4da99', 'Team A walks Camp–Ridge–Vault at 4 km/h. Team B walks Camp–Wadi–Oasis–Vault at 5 km/h. By how many minutes does Team B complete its route sooner than Team A?', '[{"label":"A","text":"4.5 min"},{"label":"B","text":"6.0 min"},{"label":"C","text":"7.5 min"},{"label":"D","text":"9.0 min"},{"label":"E","text":"12.0 min"}]'::jsonb, 'C', 'Team A walks 4.8 + 6.5 = 11.3 km, taking 11.3 / 4 = 2.825 hours = 169.5 minutes. Team B walks 5.2 + 3.3 + 5.0 = 13.5 km, taking 13.5 / 5 = 2.7 hours = 162 minutes. Difference = 169.5 − 162 = 7.5 minutes, so Team B is 7.5 minutes sooner. The answer is 7.5 min.', 2, 'hard');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('12f0d469-4c64-48cd-ad0b-372de990619c'::uuid, '865d24bc-aa97-4156-adcc-426edfcda185', 'Acoustic Wall Panels', '{"type":"geometry_diagram","context":"An exhibition hall has a centrally notched acoustic wall. The outline is equivalent to a 12 m by 8 m rectangle with a 4 m by 3 m rectangular notch removed from the bottom centre.","data":{"title":"Acoustic wall outline","viewBox":{"width":320,"height":240},"shapes":[{"type":"polygon","points":[[30,30],[290,30],[290,200],[205,200],[205,136],[115,136],[115,200],[30,200]],"fill":"none","stroke":"#2d3748"}],"dimensions":[{"from":[30,18],"to":[290,18],"label":"12 m","side":"top"},{"from":[300,30],"to":[300,200],"label":"8 m","side":"right"},{"from":[115,126],"to":[205,126],"label":"4 m","side":"top"},{"from":[105,136],"to":[105,200],"label":"3 m","side":"left"}]}}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('cdab715d-d2c1-4c4d-8b65-b501758b795e'::uuid, '12f0d469-4c64-48cd-ad0b-372de990619c'::uuid, '86eff007-5ddd-4290-9304-5e342fc87bc4', 'What is the area of the acoustic wall?', '[{"label":"A","text":"72 m²"},{"label":"B","text":"80 m²"},{"label":"C","text":"84 m²"},{"label":"D","text":"88 m²"},{"label":"E","text":"96 m²"}]'::jsonb, 'C', 'Outer rectangle area = 12 × 8 = 96 m². Notch area = 4 × 3 = 12 m². Wall area = 96 − 12 = 84 m². The answer is 84 m².', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('8a57db19-b4f4-4106-b89c-1e2dee7285cd'::uuid, '12f0d469-4c64-48cd-ad0b-372de990619c'::uuid, 'a68a48d7-a9aa-4d40-8cdb-39a4e277d503', 'What is the perimeter of the wall outline?', '[{"label":"A","text":"40 m"},{"label":"B","text":"42 m"},{"label":"C","text":"44 m"},{"label":"D","text":"46 m"},{"label":"E","text":"48 m"}]'::jsonb, 'D', 'Trace the outline: 12 + 8 + 4 + 3 + 4 + 3 + 4 + 8 = 46 m. The inward notch replaces a 4 m bottom segment with 3 + 4 + 3 m. The answer is 46 m.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('cf2e5649-7326-4a6c-b57d-4e5f70728e80'::uuid, '12f0d469-4c64-48cd-ad0b-372de990619c'::uuid, '28006bac-05e2-48b1-b244-c500c5d89f42', 'Panels measure 1.2 m by 0.6 m. Material must cover 90% of the wall area, with an extra 5% of that covered area allowed for waste. What is the minimum whole number of panels required?', '[{"label":"A","text":"105"},{"label":"B","text":"106"},{"label":"C","text":"108"},{"label":"D","text":"110"},{"label":"E","text":"111"}]'::jsonb, 'E', 'Wall area = 84 m². Required material area = 84 × 0.90 × 1.05 = 79.38 m². Each panel covers 1.2 × 0.6 = 0.72 m². Panels = 79.38 / 0.72 = 110.25, so 111 whole panels are required. The answer is 111.', 2, 'hard');
INSERT INTO quantitative_reasoning_sets (id, set_ref, title, stimulus, is_free) VALUES ('d80f4258-ca13-4c2d-a0fd-860165fb030f'::uuid, '4ba0804d-0e2a-424c-8a47-82bf2292de7d', 'Aerial Mapping Quotes', '{"type":"multi","items":[{"type":"text","text":"Three firms quote for mapping a site. Total before VAT equals setup fee + (hectares × rate per hectare) + analysis fee. VAT is 20%."},{"type":"formula","text":"Total including VAT = total before VAT × 1.20"},{"type":"table","data":{"headers":["Package","Setup fee","Rate per hectare","Analysis fee"],"rows":[["Basic","£180","£6.40","£95"],["SurveyPro","£120","£7.20","£60"],["Rapid","£250","£5.80","£140"]]},"context":"The table lists the three package fees used in the quote formula; all charges shown are before VAT."}]}'::jsonb, TRUE);
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('9ab7485a-7deb-4a1a-b74d-eb31896ba9d0'::uuid, 'd80f4258-ca13-4c2d-a0fd-860165fb030f'::uuid, '1da1591f-011c-49fb-b466-03797d0b535c', 'What is the Basic package cost for a 50-hectare site before VAT?', '[{"label":"A","text":"£560"},{"label":"B","text":"£575"},{"label":"C","text":"£595"},{"label":"D","text":"£615"},{"label":"E","text":"£690"}]'::jsonb, 'C', 'Basic cost = £180 + (50 × £6.40) + £95 = £180 + £320 + £95 = £595. The answer is £595.', 0, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('612708aa-2ae6-4b75-af6f-501349202355'::uuid, 'd80f4258-ca13-4c2d-a0fd-860165fb030f'::uuid, '56068679-a2c7-4f83-95ab-db1881c797c9', 'What is the SurveyPro cost for an 80-hectare site including VAT?', '[{"label":"A","text":"£756.00"},{"label":"B","text":"£847.20"},{"label":"C","text":"£882.00"},{"label":"D","text":"£907.20"},{"label":"E","text":"£921.60"}]'::jsonb, 'D', 'Before VAT = £120 + (80 × £7.20) + £60 = £756. Including VAT = £756 × 1.20 = £907.20. The answer is £907.20.', 1, 'normal');
INSERT INTO quantitative_reasoning_questions (id, set_id, question_ref, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('2bd3e77f-2a01-46aa-8c45-329af7ac40bc'::uuid, 'd80f4258-ca13-4c2d-a0fd-860165fb030f'::uuid, 'ebc3a155-5704-459a-8ac7-09ced2e31ae9', 'For what minimum whole-number site area is Rapid cheaper than Basic before VAT?', '[{"label":"A","text":"190 ha"},{"label":"B","text":"191 ha"},{"label":"C","text":"192 ha"},{"label":"D","text":"193 ha"},{"label":"E","text":"195 ha"}]'::jsonb, 'C', 'Basic = £275 + £6.40h and Rapid = £390 + £5.80h. Rapid is cheaper when 390 + 5.80h < 275 + 6.40h, so 115 < 0.60h and h > 191.666.... The minimum whole area is 192 ha. The answer is 192 ha.', 2, 'hard');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('bff40713-4a83-4ec3-a838-ce399f9e609f'::uuid, 'Leila, a third-year medical student in a GP surgery, is observing an appointment with an autistic adult who requested a quieter place to wait and a written outline of what will happen during the consultation. The waiting room is unusually noisy and the appointment is running 20 minutes late. The receptionist says it would be unfair to treat one patient differently, but an unused side room is available and the GP can provide a short written outline without delaying other patients.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('238ac6d9-5d17-4697-9bc7-25aa6946b9af'::uuid, 'bff40713-4a83-4ec3-a838-ce399f9e609f'::uuid, 'Whether the noisy, uncertain environment may make it harder for this patient to participate effectively in the consultation.', 'Very important', 'This is very important because communication should be adapted to the individual''s needs. The noise and uncertainty may be a significant barrier to the patient''s participation, and Leila knows that practical adjustments are available without compromising anyone else''s care.', 0, 1, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('96f583ef-5674-43cb-b6dd-0b2411ab847d'::uuid, 'bff40713-4a83-4ec3-a838-ce399f9e609f'::uuid, 'That other patients in the waiting room have not been offered the same arrangements.', 'Of minor importance', 'This is of minor importance. Consistency and fairness matter, but fair care does not require identical arrangements when an individual faces a specific communication or sensory barrier. The adjustment is proportionate, available and does not delay other patients, so the absence of the same offer to everyone should not prevent Leila raising it.', 1, 1, 'hard');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('225b54d8-c93d-42e6-bf38-d888ea3572a3'::uuid, 'bff40713-4a83-4ec3-a838-ce399f9e609f'::uuid, 'Whether a side room and written outline can be provided without delaying care for other patients.', 'Very important', 'This is very important because it shows that the requested support is reasonable and readily achievable. Leila should raise the request so the GP can involve the patient more effectively while maintaining the service for others.', 2, 1, 'normal');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('612d9ed9-f572-4411-9126-73bda6cfd32d'::uuid, 'Dr Mensah, an F1 doctor, uses a trust-approved drafting tool to prepare a discharge letter from information already in a patient''s electronic record. Before the letter is sent, she notices that the draft has invented a follow-up appointment in two weeks; the actual plan is for the GP to arrange review within six weeks. The patient is still on the ward, and a senior doctor is available to review the corrected letter.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('6b87e264-c3b9-48ef-b7f8-89afab37b61e'::uuid, '612d9ed9-f572-4411-9126-73bda6cfd32d'::uuid, 'Dr Mensah checks the whole draft against the clinical record, corrects the follow-up plan, and asks the senior doctor to review it before it is sent.', 'A very appropriate thing to do', 'This is very appropriate because Dr Mensah remains accountable for the accuracy of the letter even though an approved tool produced the first draft. Checking the complete output, correcting the invented detail and obtaining timely senior review protects continuity of care and prevents misleading information reaching the patient or GP.', 0, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('acc4c2d4-5497-4066-a618-387cb802ce2d'::uuid, '612d9ed9-f572-4411-9126-73bda6cfd32d'::uuid, 'Dr Mensah sends the draft unchanged because the tool is trust-approved and assumes the GP will correct the follow-up timing if necessary.', 'A very inappropriate thing to do', 'This is very inappropriate because she has identified a material error before the letter is sent and has a clear opportunity to prevent harm. Approval of a tool does not transfer professional responsibility for checking clinical communications, and relying on the GP to detect the error risks delayed or confused follow-up.', 1, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('af97e892-e791-422f-9757-065940fbbb90'::uuid, '612d9ed9-f572-4411-9126-73bda6cfd32d'::uuid, 'Dr Mensah discards the draft, writes an accurate letter manually, but does not report the unexpected output because no incorrect information was sent.', 'Appropriate, but not ideal', 'This is appropriate but not ideal. Rewriting the letter prevents the immediate error and is within Dr Mensah''s scope, but failing to report a significant false output misses an opportunity for the organisation to assess whether the tool could create similar risks for other patients.', 2, 2, 'hard');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('29ef1c6f-15fc-4ac6-8f2a-0cd871c1132a'::uuid, 'During a dental teaching clinic, final-year student Mariam opens a sealed instrument pouch for the next patient and notices moisture inside and a tear along its heat-sealed edge. The instruments have not yet touched the patient. A colleague says they came through the steriliser this morning and suggests using them because the clinic is running late; an intact replacement pouch is available nearby.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('b7b64287-8862-49e8-8670-33f72ed51895'::uuid, '29ef1c6f-15fc-4ac6-8f2a-0cd871c1132a'::uuid, 'Mariam sets the damaged pouch aside, uses the intact replacement, and alerts the dental nurse so the packaging failure can be handled through the clinic''s decontamination process.', 'A very appropriate thing to do', 'This is very appropriate because damaged, wet packaging cannot provide reliable assurance that the instruments remained sterile. Mariam prevents exposure before it occurs, keeps care moving with the intact set and reports the problem so the affected instruments and process can be checked.', 0, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('217cd473-923a-452f-a736-fa137f55e93b'::uuid, '29ef1c6f-15fc-4ac6-8f2a-0cd871c1132a'::uuid, 'Mariam dries the outside of the pouch, checks that the instruments look clean, and uses them without mentioning the damaged seal.', 'A very inappropriate thing to do', 'This is very inappropriate because Mariam knowingly uses instruments from a wet, torn pouch whose sterile barrier is compromised, despite an intact replacement being immediately available. Drying the pouch and visually inspecting the instruments cannot restore sterility; concealing the defect and proceeding creates a direct, avoidable infection risk for the patient.', 1, 2, 'hard');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('df4ceb21-fc3a-4dd9-85c5-7160784d68cf'::uuid, '29ef1c6f-15fc-4ac6-8f2a-0cd871c1132a'::uuid, 'Mariam uses the instruments and plans to mention the damaged pouch after the session because the instruments were sterilised that morning.', 'A very inappropriate thing to do', 'This is very inappropriate because recent processing does not overcome a compromised sterile barrier, and an intact alternative is immediately available. Using the set creates an avoidable infection risk; raising the issue only after treatment is too late to protect this patient.', 2, 2, 'normal');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('4174a5d4-fea1-47e6-8209-848c60becdf1'::uuid, 'In a dental school teaching laboratory, Sora, a third-year dental student, is asked to use a plaster model of a patient''s teeth during a class demonstration. The model has a label showing the patient''s full name and date of birth. Students not involved in that patient''s care will attend the class. An anonymised identifier can be attached in a few minutes without affecting the demonstration.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('94b32efa-2aa1-41dd-82b6-281ac293bca1'::uuid, '4174a5d4-fea1-47e6-8209-848c60becdf1'::uuid, 'That a labelled dental model contains patient information even though it does not show the patient''s face.', 'Very important', 'This is very important because the full name and date of birth directly identify the patient. Dental records and models must be handled in a way that protects confidentiality, including when they are used for teaching.', 0, 1, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('23bd9b37-6f68-4b46-839b-9316a2361e8a'::uuid, '4174a5d4-fea1-47e6-8209-848c60becdf1'::uuid, 'That none of the students attending the class are likely to know the patient personally.', 'Of minor importance', 'This is of minor importance. Familiarity could increase the chance of recognition, but confidentiality does not depend on whether Sora expects a particular audience member to know the patient. The visible identifiers are unnecessary and should still be removed or covered.', 1, 1, 'hard');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('f6472560-488e-42cd-b5a2-f0c6f55f5d36'::uuid, '4174a5d4-fea1-47e6-8209-848c60becdf1'::uuid, 'Whether replacing the label with an anonymised identifier would preserve the educational value of the demonstration.', 'Very important', 'This is very important because it provides a proportionate way to meet the teaching aim without exposing identifiable information. Sora should use the anonymised label before the model is shown to the wider class.', 2, 1, 'normal');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('53124883-d517-43cf-a81b-ab17be3b63f1'::uuid, 'Before connecting an infusion pump to a patient, Dr Okeke, an F1 doctor, sees the pump restart when its power cable is moved slightly. No patient has received treatment from it. A nurse says the same pump gave an unexplained alarm on the previous shift, but nobody reported it. A working spare pump is available and the trust has an equipment incident process.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('07076d72-c491-4e16-afe9-264f83091949'::uuid, '53124883-d517-43cf-a81b-ab17be3b63f1'::uuid, 'That no patient appears to have been harmed by the pump so far.', 'Of minor importance', 'This is of minor importance. The absence of known harm is relevant to the immediate clinical response, but it does not make the recurrent fault safe or remove the need to prevent future use and report the near miss.', 0, 1, 'hard');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('74395bcd-744c-4173-85ce-b74e49f08e16'::uuid, '53124883-d517-43cf-a81b-ab17be3b63f1'::uuid, 'Whether the intermittent fault could recur while the pump is delivering treatment to a patient.', 'Very important', 'This is very important because an intermittent restart during treatment could interrupt or alter therapy. Dr Okeke should act on the observable risk rather than wait for a patient to be harmed.', 1, 1, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('af4883fb-9f28-48e6-8445-affb5beb61d7'::uuid, '53124883-d517-43cf-a81b-ab17be3b63f1'::uuid, 'Whether taking the pump out of service and reporting the fault could protect patients on later shifts.', 'Very important', 'This is very important because isolating and clearly labelling the pump prevents accidental reuse, while formal reporting allows technical review and organisational learning. The available spare means this can be done without delaying the current patient''s care.', 2, 1, 'normal');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('6d8e039f-3b48-4dcc-8392-6ca890414438'::uuid, 'Dr Rahim, an F1 doctor in an outpatient clinic, receives a call from the adult daughter of a patient who has capacity. The daughter asks for the patient''s online portal password to be reset to the daughter''s email address because her parent ''isn''t good with phones''. The patient has not authorised proxy access, the result on the portal is routine, and clinic staff can contact the patient directly to discuss supported access.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('da5dd412-0bed-4466-a111-ab07fa9a301c'::uuid, '6d8e039f-3b48-4dcc-8392-6ca890414438'::uuid, 'Dr Rahim explains that access cannot be changed without the patient''s involvement, and arranges for staff to contact the patient about support or formal proxy access if the patient wants it.', 'A very appropriate thing to do', 'This is very appropriate because it protects the patient''s control over confidential information while addressing the practical difficulty constructively. Direct contact lets the patient choose whether to receive support or authorise proxy access through the proper process.', 0, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('3c3fb9c7-db4e-47e9-b4db-9a72a9e53907'::uuid, '6d8e039f-3b48-4dcc-8392-6ca890414438'::uuid, 'Dr Rahim changes the portal email after the daughter correctly states the patient''s date of birth and address.', 'A very inappropriate thing to do', 'This is very inappropriate because confirming demographic details does not establish the patient''s consent for the daughter to access the portal. Changing the account could disclose results and correspondence and deprive a capacitous patient of control over their information.', 1, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('6340fb4f-4d37-41e7-bd66-d98456fde7e7'::uuid, '6d8e039f-3b48-4dcc-8392-6ca890414438'::uuid, 'Dr Rahim shares no information, asks the daughter to tell the patient to contact the clinic, and takes no further step to make direct contact.', 'Appropriate, but not ideal', 'This is appropriate but not ideal. Dr Rahim avoids an unauthorised disclosure and gives a legitimate route forward, but relying only on the daughter is less patient-centred than arranging direct contact, particularly when staff already know the patient may need help using the portal.', 2, 2, 'hard');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('523ee9de-60b8-431c-a16d-f7577d349004'::uuid, 'At evening handover, Dr Lowe, an F1 doctor, sees a colleague preparing to send identifiable patient details to the incoming doctor through a personal messaging account. The approved electronic handover system is expected to be unavailable for 20 minutes, but the patient is stable and an approved ward telephone can be used for a verbal handover.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('2ed05a96-600a-48b6-b204-4f80830eafa5'::uuid, '523ee9de-60b8-431c-a16d-f7577d349004'::uuid, 'Dr Lowe asks the colleague not to send the message, suggests a verbal handover on the approved ward telephone, and reports the system outage through the usual route.', 'A very appropriate thing to do', 'This is very appropriate because it preserves an effective handover without placing identifiable information on an unapproved personal account. Reporting the outage also helps the organisation restore the secure system and manage any wider continuity risk.', 0, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('2c557ee6-7674-4638-bd49-361cee3effd2'::uuid, '523ee9de-60b8-431c-a16d-f7577d349004'::uuid, 'Dr Lowe agrees that the personal account can be used because its messages are encrypted and the colleague promises to delete them after the shift.', 'A very inappropriate thing to do', 'This is very inappropriate because encryption and later deletion do not make an unapproved personal account an acceptable clinical record or communication route. A safe, authorised alternative is immediately available, so the confidentiality and governance risk is unnecessary.', 1, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('93c65df7-cb6d-491b-b961-f49bb368bb17'::uuid, '523ee9de-60b8-431c-a16d-f7577d349004'::uuid, 'Dr Lowe suggests sending only the patient''s initials and bed number by personal message, with a request that the incoming doctor look up the clinical details later.', 'Inappropriate, but not awful', 'This is inappropriate but not awful. Reducing the content limits some disclosure, but initials and location may still identify the patient, the personal channel remains unapproved, and deferring the clinical details risks an incomplete handover. The approved telephone offers a safer and more effective option.', 2, 2, 'hard');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('08e1847b-52ea-4aef-9509-9876a110fade'::uuid, 'During a GP appointment, a patient tells Dr Chen, an F1 doctor, that they have been buying weight-loss injections online. The patient asks Dr Chen not to put this in the clinical record because they wrongly believe their employer can routinely read their notes. The injections may affect future prescribing, and the patient''s regular GP will continue their care.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('4089c4c0-80e5-452e-9be3-ef4a646aeeba'::uuid, '08e1847b-52ea-4aef-9509-9876a110fade'::uuid, 'Whether an accurate record of the injections is needed for safe prescribing and continuity of care.', 'Very important', 'This is very important because the information may affect future treatment and needs to be available to clinicians responsible for the patient''s care. Dr Chen should explain why a relevant, factual entry is necessary rather than agreeing to create an incomplete record.', 0, 1, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('9c12d2b7-0a73-4447-a295-66114e6f49ca'::uuid, '08e1847b-52ea-4aef-9509-9876a110fade'::uuid, 'That the patient''s request is based on a fear that their employer can routinely access the clinical record.', 'Important', 'This is important because Dr Chen should take the concern seriously, correct the misunderstanding and explain how confidential records are protected. It does not outweigh the need for an accurate clinical record, but addressing it may help the patient understand and accept appropriate documentation.', 1, 1, 'hard');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('a3ef8844-6ae9-4474-8852-14e7f2d656bb'::uuid, '08e1847b-52ea-4aef-9509-9876a110fade'::uuid, 'That respecting patient autonomy requires clinicians to omit any information a patient asks them not to record.', 'Not important at all', 'This is not important at all because autonomy does not give a patient an absolute right to require a misleading or clinically unsafe record. Dr Chen should listen, explain confidentiality and document relevant information accurately and proportionately.', 2, 1, 'normal');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('48854b09-9e20-4f6e-98f0-335d49b84934'::uuid, 'During a remote review, Dr Patel, an F1 doctor, notices that an adult patient''s father is recording the consultation on the father''s phone. The patient has capacity, wants the father present and says the recording will help them remember advice. The discussion is about a sensitive diagnosis, and nobody has discussed who will store or hear the recording.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('163f14ff-e516-479a-bcdf-e731de026fae'::uuid, '48854b09-9e20-4f6e-98f0-335d49b84934'::uuid, 'Dr Patel pauses to confirm the patient''s wishes, clarifies who will keep and hear the recording, and offers a written summary as an alternative before continuing.', 'A very appropriate thing to do', 'This is very appropriate because it respects the patient''s wish to retain information while addressing the additional privacy risk created by using another person''s device for a sensitive discussion. Clarifying control and alternatives supports an informed, proportionate decision without shaming the patient or father.', 0, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('0081f063-b44c-462a-9c62-b5aea6759990'::uuid, '48854b09-9e20-4f6e-98f0-335d49b84934'::uuid, 'Dr Patel continues once the patient confirms they want the recording, without asking how the father''s phone or recording will be used afterwards.', 'Appropriate, but not ideal', 'This is appropriate but not ideal. The capacitous patient''s clear wish carries substantial weight, so continuing is not inherently wrong. However, because the recording is on a relative''s device and concerns sensitive information, a brief discussion about storage, access and sharing would better protect the patient''s confidentiality.', 1, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('93f910aa-5afd-463a-a01d-0a0c7aff25fe'::uuid, '48854b09-9e20-4f6e-98f0-335d49b84934'::uuid, 'Dr Patel tells the father that recording is forbidden and threatens to end the consultation unless it is deleted immediately, despite the patient''s stated wish.', 'A very inappropriate thing to do', 'This is very inappropriate because it is coercive, disregards the patient''s expressed preference and risks withdrawing needed care without first exploring the privacy concern or reasonable alternatives. Dr Patel should discuss the situation calmly and keep the patient''s interests central.', 2, 2, 'normal');
INSERT INTO situational_judgement_scenarios (id, body, is_free) VALUES ('4109ee1b-4fce-4834-b3d3-87e6e572b9dd'::uuid, 'Dr Evans, an F2 doctor, is due to conduct a routine video review but is still in a busy railway cafe. Other customers are seated close enough to overhear. A private clinic room will be free in 15 minutes, and a colleague can tell the patient about the short delay. The patient''s condition is stable and the review is not urgent.
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('038ccf43-acb2-42b8-9b2d-b4cf10627ce4'::uuid, '4109ee1b-4fce-4834-b3d3-87e6e572b9dd'::uuid, 'Dr Evans asks the colleague to explain the short delay and conducts the review from the private clinic room when it becomes available.', 'A very appropriate thing to do', 'This is very appropriate because the brief, communicated delay causes little clinical risk and allows the consultation to take place in a setting that protects privacy and supports open discussion.', 0, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('84d6062b-2873-48f3-a5ad-122d25cd39c2'::uuid, '4109ee1b-4fce-4834-b3d3-87e6e572b9dd'::uuid, 'Dr Evans starts the review in the cafe using headphones and speaks quietly without saying the patient''s name.', 'A very inappropriate thing to do', 'This is very inappropriate because Dr Evans deliberately begins a non-urgent confidential consultation where nearby customers can foreseeably overhear. Headphones protect only incoming audio, and speaking quietly without using the patient''s name does not prevent sensitive clinical details from identifying the patient. The breach is avoidable because a private room is available after a short, safe delay.', 1, 2, 'normal');
INSERT INTO situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('65d8f885-1e48-40f8-a68c-4c3e2bd4794e'::uuid, '4109ee1b-4fce-4834-b3d3-87e6e572b9dd'::uuid, 'Dr Evans asks the patient to consent to continuing while he is in the cafe, reasoning that consent removes the confidentiality concern.', 'A very inappropriate thing to do', 'This is very inappropriate because a patient''s agreement does not remove Dr Evans''s responsibility to choose a suitably private environment, especially when the patient may feel pressure not to delay the appointment. There is no urgency and a safe alternative is available within minutes.', 2, 2, 'normal');
INSERT INTO timed_verbal_reasoning_tests (id, title, time_minutes) VALUES (5, 'VR Timed Test 5', 22);
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('8261574a-672e-42fa-a481-89678d76d754'::uuid, 5, 'Recycling Roman Glass', 'Roman glassworkers did not necessarily begin with sand and other raw ingredients. Workshops could reshape glass that had already been produced, while broken glass, called cullet, could be gathered and remelted. This material economy leaves a difficult question: how much surviving glass had already passed through a furnace more than once?
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('990a82b0-7908-442c-b941-2abafcc5d1a2'::uuid, '8261574a-672e-42fa-a481-89678d76d754'::uuid, 'Why can an efficient recycling system be archaeologically inconspicuous?', ARRAY['It may leave little discarded cullet for archaeologists to recover', 'It prevents glassworking waste from surviving underground', 'It always produces glass with a completely uniform composition', 'It requires workshops to operate close to primary furnaces'], 'It may leave little discarded cullet for archaeologists to recover', 'The passage says efficient recycling may leave little discarded cullet, so the first option is correct. It does not say waste cannot survive, that recycling always creates uniform glass, or that secondary workshops must be near primary furnaces.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('0bcc0e1e-02f3-4957-b486-b7e09b144833'::uuid, '8261574a-672e-42fa-a481-89678d76d754'::uuid, 'What does a glass fragment bearing both antimony- and manganese-associated signatures most directly suggest?', ARRAY['The vessel was made in a primary furnace beside a raw-material source', 'The glassworker deliberately coloured the vessel with both metals', 'The fragment must have come from the Iulia Felix wreck', 'Two previously distinct colourless glass groups may have been remelted together'], 'Two previously distinct colourless glass groups may have been remelted together', 'The passage presents the combined signatures as indirect evidence that separate groups were mixed. It does not locate the furnace, equate decolourising signatures with deliberate colouring, or link every such fragment to one wreck.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6bd86b0a-a290-4fa5-b352-1431aeda6627'::uuid, '8261574a-672e-42fa-a481-89678d76d754'::uuid, 'Which finding would most weaken the claim that chemically uniform Roman glass was necessarily made only from fresh material?', ARRAY['Primary glass was transported in large slabs', 'Some workshops produced drips and failed vessels', 'Glass of similar composition can be recycled without an obvious mixed signature', 'Colourless glass could be decolourised with antimony'], 'Glass of similar composition can be recycled without an obvious mixed signature', 'Recycling like with like can leave glass chemically uniform, directly weakening the claim. Transport in slabs and workshop waste do not address uniformity; antimony use explains one signature but not why fresh material is unnecessary.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('f7ed7259-cb63-4830-bc1f-7cd8179fb310'::uuid, '8261574a-672e-42fa-a481-89678d76d754'::uuid, 'What is the main purpose of the Iulia Felix example?', ARRAY['To show that raw glass was never traded by sea', 'To demonstrate direct evidence for commerce in sorted broken glass', 'To prove that all Roman vessels were recycled several times', 'To explain how antimony and manganese decolourised glass'], 'To demonstrate direct evidence for commerce in sorted broken glass', 'The wreck carried cullet separated by colour and type, so it evidences trade in broken glass. The passage does not deny trade in raw glass, prove universal repeated recycling, or use the wreck to explain decolourisers.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('2cb44fa8-2629-4e1f-b38f-62a11e73bc7b'::uuid, 5, 'Weaving Ainu Attus', 'Attus is a woven bark-fibre cloth associated with the Ainu, the Indigenous people of northern Japan. Although the finished material is sometimes grouped broadly with barkcloth, it is not made by simply beating bark into a sheet. Makers extract fibres from the inner bark of trees such as the Japanese elm, soften them by soaking the bark in water, separate and split the fibres, join them into long thread, and weave that thread on a loom. The sequence converts bark into a textile through repeated preparation rather than preserving the bark as a continuous layer.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('5a9774a6-0642-4b31-bf9a-d460d8617c1e'::uuid, '2cb44fa8-2629-4e1f-b38f-62a11e73bc7b'::uuid, 'Attus is made by beating a continuous sheet of bark until it becomes soft enough to wear.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'The passage explicitly contrasts attus with beaten barkcloth: inner-bark fibres are separated, made into thread and woven. The statement is therefore contradicted.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('f9b6257f-3c75-4589-814f-5cf1d77cdf28'::uuid, '2cb44fa8-2629-4e1f-b38f-62a11e73bc7b'::uuid, 'Every historical Ainu community assigned bark collection exclusively to men.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'The passage says some accounts record men collecting bark, while others describe women doing so, and warns against making a universal rule. The exclusive claim is contradicted.', 1, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6e679390-882e-43c6-af3c-94a2ffaf3eea'::uuid, '2cb44fa8-2629-4e1f-b38f-62a11e73bc7b'::uuid, 'Attus was used for both ordinary and ceremonial clothing.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'The passage directly states that attus supplied everyday and ceremonial clothing, so the statement is entailed.', 2, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('2dd2435a-9a52-44a0-9641-f03b35420da8'::uuid, '2cb44fa8-2629-4e1f-b38f-62a11e73bc7b'::uuid, 'Modern attus wallets are more durable than historical attus robes.', ARRAY['True', 'False', 'Can''t tell'], 'Can''t tell', 'The passage says attus is durable and is now used for wallets, but it gives no comparison between the durability of modern wallets and historical robes. The claim is neither confirmed nor contradicted.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('ae26e452-56d4-4a70-9d3b-13a6bb54b93b'::uuid, 5, 'Ice Stupas of Ladakh', 'Farming villages in Ladakh, a high-altitude desert in northern India, can face a timing problem rather than an absolute absence of water. Streams may run through the cold winter when fields need little irrigation, then remain meagre during spring planting before stronger summer glacier melt arrives. Artificial ice reservoirs store part of the winter flow in frozen form so that melting supplies water closer to the planting season.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('0d94d84c-0d0e-4aba-8dce-0ff94bad8e41'::uuid, 'ae26e452-56d4-4a70-9d3b-13a6bb54b93b'::uuid, 'What problem are ice stupas primarily designed to address?', ARRAY['Winter streams contain too much salt for crops', 'Summer glacier melt arrives before fields can absorb it', 'Villages cannot move water downhill without electric pumps', 'Water is available in winter but scarce during the spring planting period'], 'Water is available in winter but scarce during the spring planting period', 'The passage identifies a seasonal mismatch between unused winter flow and spring planting needs. It mentions neither salt nor premature summer melt, and gravity-driven pressure specifically reduces the need for a pump.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('aa59b44a-6e24-4425-9b89-219d7ebc8906'::uuid, 'ae26e452-56d4-4a70-9d3b-13a6bb54b93b'::uuid, 'Why can water spray upward at the lower end of the pipe?', ARRAY['The height difference from the source creates water pressure', 'Freezing droplets expand inside the pipe', 'A solar-powered motor forces the water upward', 'Warm air beneath the cone pushes against the stream'], 'The height difference from the source creates water pressure', 'The passage explicitly attributes the spray to pressure created by the source being above the village. It does not invoke freezing expansion, a motor, or warm air.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('55cadb16-a079-4310-adf4-fda2855cb6be'::uuid, 'ae26e452-56d4-4a70-9d3b-13a6bb54b93b'::uuid, 'Which new finding would most challenge the passage''s explanation for the cone''s seasonal advantage?', ARRAY['Some villages decorate ice stupas with local symbols', 'A cone and a shallow sheet of equal ice volume expose the same effective area to melting conditions', 'The feeder stream runs fastest during winter nights', 'Horizontal reservoirs can also supply irrigation water'], 'A cone and a shallow sheet of equal ice volume expose the same effective area to melting conditions', 'The proposed advantage rests on lower exposed area for a given volume, so equal effective exposure would directly challenge it. Decoration is irrelevant, faster winter flow concerns construction, and the passage already accepts that horizontal reservoirs can work.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('a9cb5fd8-2729-4bd9-a4b4-1d4d66678835'::uuid, 'ae26e452-56d4-4a70-9d3b-13a6bb54b93b'::uuid, 'Which statement best captures the author''s view of ice stupas?', ARRAY['They provide a weather-proof substitute for natural glaciers', 'They are chiefly monuments whose irrigation role is incidental', 'They shift existing water across seasons but remain dependent on local conditions', 'They eliminate the need for a continuing feeder stream'], 'They shift existing water across seasons but remain dependent on local conditions', 'The final paragraph explicitly frames them as seasonal storage whose results depend on weather, supply and construction. The other options overstate reliability, reverse their purpose, or deny their dependence on a feeder stream.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('e39171df-e223-478f-93b3-ecfa86186923'::uuid, 5, 'Pykrete and Project Habbakuk', 'During the Second World War, Allied planners worried about the mid-Atlantic gap, where land-based aircraft could not easily protect convoys from German submarines. Geoffrey Pyke promoted an extraordinary response: a vast floating airfield built largely from ice. Ordinary ice, however, cracks readily and melts too quickly. Research directed through Canada''s National Research Council examined ice reinforced with wood pulp, later called pykrete. The fibres hindered crack growth, made the frozen composite tougher than plain ice and slowed melting.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('e8ceec88-f7bc-4616-b67f-9d91c858f79c'::uuid, 'e39171df-e223-478f-93b3-ecfa86186923'::uuid, 'What problem did adding wood pulp to ice address?', ARRAY['It allowed the composite to generate its own refrigeration', 'It made the material lighter than air', 'It removed the need for insulation and machinery', 'It reduced cracking and slowed melting compared with ordinary ice'], 'It reduced cracking and slowed melting compared with ordinary ice', 'The first paragraph says fibres hindered cracks, increased toughness and slowed melting. The composite did not refrigerate itself, float in air, or eliminate the vessel''s supporting systems.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('1884d563-fdc7-42f1-a6a4-c9079917c852'::uuid, 'e39171df-e223-478f-93b3-ecfa86186923'::uuid, 'Why does the author resist describing the Patricia Lake prototype as a miniature warship?', ARRAY['It was constructed after the war had ended', 'It contained no ice or wood pulp', 'It was a block-like experimental structure rather than a scaled operational vessel', 'It was designed solely to test radar equipment'], 'It was a block-like experimental structure rather than a scaled operational vessel', 'The passage explicitly characterises the prototype as a test structure, so the third option is correct. It was wartime work involving frozen material, and radar testing is not stated.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('e3bb6b36-7352-4af9-87e5-53390c86f390'::uuid, 'e39171df-e223-478f-93b3-ecfa86186923'::uuid, 'Which conclusion is best supported about Habbakuk''s cancellation?', ARRAY['Pykrete failed every material test conducted in Canada', 'The project''s purpose weakened as alternatives improved and system costs became clearer', 'The Allies decided submarine attacks posed no danger to shipping', 'The prototype proved that large ice structures could not be kept frozen'], 'The project''s purpose weakened as alternatives improved and system costs became clearer', 'The final paragraph combines changing strategy with rising cost and complexity. It explicitly denies that cancellation proved material failure; it does not say submarines ceased to matter or that the prototype could not stay frozen.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('3c11ee7f-9237-49ef-b3f4-1394a7ae23ec'::uuid, 'e39171df-e223-478f-93b3-ecfa86186923'::uuid, 'What broader distinction does the author use Habbakuk to illustrate?', ARRAY['The difference between military and civilian science', 'The difference between a promising material and a worthwhile complete system', 'The difference between aircraft and submarines', 'The difference between Canadian and British engineering methods'], 'The difference between a promising material and a worthwhile complete system', 'The closing sentence contrasts impressive material performance with an unnecessary or uneconomical machine. The other distinctions appear incidentally or not at all and are not the stated lesson.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('960f2165-2e9a-4a6c-8f01-5dd1292982b1'::uuid, 5, 'Lakes That Do Not Fully Mix', 'In many temperate lakes, cooling surface water becomes dense enough in spring or autumn to sink, helping wind mix oxygen and dissolved substances through the water column. A meromictic lake differs because some deep water remains isolated across seasonal cycles. Limnologists call the regularly mixed upper layer the mixolimnion and the persistent lower layer the monimolimnion. Between them lies a steep chemical or density transition, the chemocline.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('7aa5db75-fe09-424b-9a01-da246ff73296'::uuid, '960f2165-2e9a-4a6c-8f01-5dd1292982b1'::uuid, 'A meromictic lake must be motionless from its surface to its bed.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'The passage says the mixolimnion may circulate vigorously while only the deepest water remains isolated. The statement is directly contradicted.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('69f0407d-48e3-4e56-b09b-f940bdfa3b27'::uuid, '960f2165-2e9a-4a6c-8f01-5dd1292982b1'::uuid, 'A density difference caused by dissolved salts can help prevent complete lake mixing.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'The passage explicitly gives dense salty deep water beneath fresher surface water as one condition preserving separation, so the statement is entailed.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('cf874c40-ae0b-49bb-9bf2-4b9ce64c8b51'::uuid, '960f2165-2e9a-4a6c-8f01-5dd1292982b1'::uuid, 'The chemocline of every meromictic lake occurs at the same depth.', ARRAY['True', 'False', 'Can''t tell'], 'Can''t tell', 'The passage identifies the chemocline as the transition between the upper and lower layers, but gives no common depth for that boundary across different lakes. The statement is neither confirmed nor contradicted.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('be71d1d6-19e5-4bf3-9238-55ea0cf9979f'::uuid, '960f2165-2e9a-4a6c-8f01-5dd1292982b1'::uuid, 'Limited oxygen replacement can contribute to an anoxic monimolimnion.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'The passage states that atmospheric oxygen is not regularly carried downward and decomposition can consume what remains, leaving the lower layer anoxic. The statement is entailed.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('9c3c6fb4-a905-4607-89f9-4eb22609e8de'::uuid, 5, 'The Argonaut''s Eggcase', 'The paper nautilus is not a nautilus but an argonaut, a pelagic octopus living in the open ocean. Its most conspicuous structure is also misleadingly called a shell. Only the female produces this paper-thin, coiled eggcase. Unlike a molluscan shell secreted by mantle tissue, the argonaut''s case is formed by specialised webs on a pair of dorsal arms. The female occupies it and attaches strings of eggs to its inner surface; the much smaller male produces no comparable case.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('1c86ee2b-2b65-4601-84fa-fccc0f108b17'::uuid, '9c3c6fb4-a905-4607-89f9-4eb22609e8de'::uuid, 'Which feature most clearly distinguishes the argonaut eggcase from a typical molluscan shell?', ARRAY['It is made by specialised arm webs rather than mantle tissue', 'It contains calcium-based material', 'It has a coiled external form', 'It can shelter developing eggs'], 'It is made by specialised arm webs rather than mantle tissue', 'The passage explicitly makes origin in arm webs the contrast with a typical mantle-secreted shell. The other features do not establish that developmental distinction.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('d9971596-0831-4fc5-ae8c-bda37d46d9f7'::uuid, '9c3c6fb4-a905-4607-89f9-4eb22609e8de'::uuid, 'What happens after a female argonaut captures and seals air at the surface?', ARRAY['She releases the eggcase and swims beneath it', 'She divides the gas among sealed internal chambers', 'She waits for the male to alter the eggcase''s pressure', 'She jets downward until compressed gas can balance her weight'], 'She jets downward until compressed gas can balance her weight', 'The second paragraph gives this sequence directly. The female does not release the case, it has no internal chambers, and no male action is involved.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('c774a4e4-e7db-4d70-94d3-094dcc8522e3'::uuid, '9c3c6fb4-a905-4607-89f9-4eb22609e8de'::uuid, 'Why might a shallow-tank observation underestimate the effectiveness of the buoyancy system?', ARRAY['The animal may not reach the depth at which pressure compresses the gas sufficiently', 'Tank water prevents the female from sealing air with her arms', 'The eggcase dissolves rapidly in confined water', 'Neutral buoyancy occurs only in fresh water'], 'The animal may not reach the depth at which pressure compresses the gas sufficiently', 'The passage says shallow tanks may return an air-filled animal to the surface before its balance depth. It does not mention failed sealing, dissolution, or any freshwater requirement.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('d922e5c2-35a0-46cc-a523-805d6dbd5412'::uuid, '9c3c6fb4-a905-4607-89f9-4eb22609e8de'::uuid, 'Which description best summarises the eggcase''s functions?', ARRAY['Camouflage and food storage', 'Protection from males and propulsion', 'Egg brooding and behavioural control of buoyancy', 'Sound production and temperature regulation'], 'Egg brooding and behavioural control of buoyancy', 'The eggcase bears eggs and holds air that the female actively manages, so the third option captures both stated jobs. The remaining pairs are not supported by the passage.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('16c7f4b8-7f9d-4027-80b0-adbde51ae4da'::uuid, 5, 'Reading Andean Khipus', 'The Inka administered a vast Andean empire without relying on an alphabetic script. Their principal recording device was the khipu: a main cord bearing pendant and subsidiary cords, made chiefly from cotton or camelid fibre. Knots tied at different positions encoded numbers in a decimal place-value system. In a typical numerical cord, knots nearer the free end represented units, with tens, hundreds and higher places arranged progressively towards the main cord. The absence of a knot could mark a zero position.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('5b13105f-5506-4273-8674-23d2167044ca'::uuid, '16c7f4b8-7f9d-4027-80b0-adbde51ae4da'::uuid, 'On a typical numerical khipu cord, unit knots were positioned closer to the free end than hundred knots.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'The passage places units near the free end and progressively higher decimal places towards the main cord. The statement is entailed.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('7f09560c-0114-48d1-a9df-bb4d9bacc579'::uuid, '16c7f4b8-7f9d-4027-80b0-adbde51ae4da'::uuid, 'The material and construction of a cord could contribute information beyond the number of its knots.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'The passage says colour, fibre, spin or attachment direction, and branching could classify information. The statement is directly supported.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('c706479b-13e3-4a24-8503-dc9324cd09f8'::uuid, '16c7f4b8-7f9d-4027-80b0-adbde51ae4da'::uuid, 'Researchers can now translate every surviving khipu into complete spoken sentences.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'The passage states that no secure bilingual key maps a khipu to complete spoken text and warns against claiming ordinary sentence-level reading. The statement is contradicted.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6a0f67af-919f-4e8c-a343-d3e0a3c07e8f'::uuid, '16c7f4b8-7f9d-4027-80b0-adbde51ae4da'::uuid, 'Every surviving khipu was originally used to record tribute.', ARRAY['True', 'False', 'Can''t tell'], 'Can''t tell', 'Tribute is one stated administrative use, but the passage also lists other uses and does not identify the original purpose of every survivor. The universal claim is not established or specifically contradicted for each object.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('a0a09e36-4094-4266-bce0-aba5c94787fd'::uuid, 5, 'Why Foehn Winds Warm', 'A foehn is a warm, dry downslope wind on the lee side of a mountain range. The familiar textbook account begins when moist air is forced up the windward slope. Falling pressure makes the rising air expand and cool. Once it is cool enough, water vapour condenses into cloud and may fall as rain or snow. Condensation releases latent heat, and precipitation removes some moisture from the air. The drier air then descends the lee slope, where increasing pressure compresses and warms it.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('a73c7f28-9d12-4291-8764-92bf536bf359'::uuid, 'a0a09e36-4094-4266-bce0-aba5c94787fd'::uuid, 'In the textbook sequence, what directly warms descending lee-side air?', ARRAY['Compression as atmospheric pressure increases', 'Evaporation caused by falling pressure', 'Contact with snow on the mountain', 'Expansion as the air approaches the valley'], 'Compression as atmospheric pressure increases', 'The passage states that increasing pressure compresses and warms descending air. Falling-pressure expansion cools rising air, while snow contact and valleyward expansion are not given as causes.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('0880cac8-183a-42e9-966f-f0ca6c01e353'::uuid, 'a0a09e36-4094-4266-bce0-aba5c94787fd'::uuid, 'Why does precipitation strengthen the classic explanation of a warm, dry lee wind?', ARRAY['It adds moisture that later freezes on the lee slope', 'It removes moisture after condensation has released heat', 'It prevents air from descending the mountain', 'It makes atmospheric pressure fall in the valley'], 'It removes moisture after condensation has released heat', 'The first paragraph links latent-heat release and moisture removal to the later warm, dry descent. The other choices reverse or invent parts of the described process.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6bece50e-9523-43a5-9261-e4c5d412f89a'::uuid, 'a0a09e36-4094-4266-bce0-aba5c94787fd'::uuid, 'A dry foehn occurs with no precipitation. Which inference best follows from the passage?', ARRAY['The wind cannot have crossed mountainous terrain', 'The event must have been misclassified', 'Mechanisms such as higher-level draw-down or turbulent mixing may have contributed', 'Compression cannot have warmed the descending air'], 'Mechanisms such as higher-level draw-down or turbulent mixing may have contributed', 'The passage explicitly offers those mechanisms for dry foehn events. It does not reject the classification or mountain crossing, and it retains descent and compression as central.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('46693777-8e3b-495f-ad26-0a797abf6cc4'::uuid, 'a0a09e36-4094-4266-bce0-aba5c94787fd'::uuid, 'Which statement best expresses the passage''s main qualification?', ARRAY['Foehn winds are always colder than windward air', 'Rainfall is irrelevant to every foehn event', 'No single mechanism has any role in more than one mountain range', 'The standard rain-and-descent account is useful but does not explain every foehn'], 'The standard rain-and-descent account is useful but does not explain every foehn', 'The passage preserves the classic account while adding dry-foehn mechanisms, so the fourth option captures its qualification. The other options contradict or overstate the text.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('f7c2e006-a538-4768-a708-fecb9b3288f7'::uuid, 5, 'Booming Sand Dunes', 'At a limited number of desert sites, an avalanche down a dune''s slip face produces a sustained low note that may be heard far away. The sound is called booming or singing, although it differs from the brief squeak some beach sand makes when walked upon. A booming dune does not sing merely because wind blows across it: the sound is associated with a moving layer of dry grains, triggered naturally by a slump or artificially by pushing sand downslope.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('15414c34-2a63-4d60-bae0-7c0f29fb9244'::uuid, 'f7c2e006-a538-4768-a708-fecb9b3288f7'::uuid, 'Which condition is directly associated with producing a dune''s booming sound?', ARRAY['A moving layer of dry sand grains', 'A stationary wet surface exposed to wind', 'Any beach sand compressed underfoot', 'A dune composed of grains of many unrelated sizes'], 'A moving layer of dry sand grains', 'The passage links booming to avalanching dry grains. It rejects wind alone, distinguishes beach squeaks, and associates characteristic tones with sorted rather than arbitrarily mixed sand.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('fcaecdde-6865-4b54-b3a4-d4bf72df5547'::uuid, 'f7c2e006-a538-4768-a708-fecb9b3288f7'::uuid, 'Why are random grain collisions alone an incomplete explanation?', ARRAY['They would be silent at all frequencies', 'They occur only in wet sand', 'They cannot happen during an avalanche', 'They would be expected to produce a broad hiss rather than a strong narrow tone'], 'They would be expected to produce a broad hiss rather than a strong narrow tone', 'The passage contrasts random collisions'' many-frequency hiss with the observed coherent note. It does not call collisions silent, moisture-dependent, or absent from avalanches.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('e8b906c8-bf62-4101-9b07-388b2297e1ff'::uuid, 'f7c2e006-a538-4768-a708-fecb9b3288f7'::uuid, 'What is the strongest implication of singing produced in a shallow laboratory sand bed?', ARRAY['Natural dunes contain no subsurface layers', 'Wind is the only possible trigger of booming', 'An entire deep dune is not always required for sound generation', 'Grain synchronisation cannot contribute to the tone'], 'An entire deep dune is not always required for sound generation', 'The laboratory result directly challenges the necessity of a deep resonant body for generation. It does not erase natural layering, privilege wind, or disprove synchronisation.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('298e480c-c9b0-4ba3-aee7-3bb70d39a94c'::uuid, 'f7c2e006-a538-4768-a708-fecb9b3288f7'::uuid, 'How does the passage reconcile competing explanations?', ARRAY['It declares both explanations entirely false', 'It suggests grain-scale generation and dune-scale amplification may be distinct', 'It claims grain size has no relationship to pitch', 'It treats beach squeaking and dune booming as identical'], 'It suggests grain-scale generation and dune-scale amplification may be distinct', 'The final paragraph separates production of the sound from its loud natural amplification. The passage accepts partial insights from the theories and explicitly distinguishes pitch effects and beach squeaks.', 3, 'normal');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('22601e12-32ab-4dd1-897a-8c131df04f33'::uuid, 5, 'Pictures Hidden on a Book''s Edge', 'A book has three exposed edges opposite and beside its spine. The edge opposite the spine is the fore edge. It can carry a picture visible while the book is closed, but a disappearing fore-edge painting works differently: the image appears only when the leaves are fanned. With the book held in that sloping position, an artist applies watercolour to the tiny exposed surfaces just inside each page edge. When the leaves return to their normal alignment, the painted fragments move out of the viewer''s direct line of sight.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6dd4bc07-7c64-42ba-9f10-53f523fc5fb9'::uuid, '22601e12-32ab-4dd1-897a-8c131df04f33'::uuid, 'In a disappearing fore-edge painting, the image is applied while the pages are fanned.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'The passage explicitly says the artist applies watercolour while the book is held in a sloping, fanned position. The statement is entailed.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('7d6a700f-e60d-4d3e-a08a-c7a62a029ce7'::uuid, '22601e12-32ab-4dd1-897a-8c131df04f33'::uuid, 'Gilding can help hide the painted scene when the book is closed.', ARRAY['True', 'False', 'Can''t tell'], 'True', 'The passage states that gilding or marbling helps conceal traces of the image, so the statement is directly supported.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('4d6829e6-6825-4992-a55f-0872c4f8ff5c'::uuid, '22601e12-32ab-4dd1-897a-8c131df04f33'::uuid, 'A double fore-edge painting shows the same image regardless of the direction in which the leaves are fanned.', ARRAY['True', 'False', 'Can''t tell'], 'False', 'The passage defines a double fore-edge painting as showing one image in one direction and another image in the opposite direction. The statement is contradicted.', 2, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('6e3bffd2-f026-4f53-a649-f114eb1092cb'::uuid, '22601e12-32ab-4dd1-897a-8c131df04f33'::uuid, 'A fore-edge scene on a book dated 1820 was painted by the person who bound the book.', ARRAY['True', 'False', 'Can''t tell'], 'Can''t tell', 'The passage says the painting may have been added later and that many makers are unidentified, but it does not establish whether the binder or someone else painted this particular scene. The claim is neither confirmed nor contradicted.', 3, 'hard');
INSERT INTO timed_verbal_reasoning_passages (id, test_id, title, body, order_index) VALUES ('4bf9f3e6-f096-4dc0-a5ef-12305730dbc0'::uuid, 5, 'Images in a Dark Chamber', 'Camera obscura means ''dark chamber''. In its simplest form, it is a darkened room or box with a small opening in one side. Light from the bright scene outside passes through the opening and forms an image on the opposite surface. The image is inverted because light travels approximately in straight lines: rays from the top of an object pass through the aperture and reach the lower part of the screen, while rays from the object''s bottom reach the upper part. Left and right cross in the same way.
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('572d6c80-4d86-4f77-b76e-68af549663bc'::uuid, '4bf9f3e6-f096-4dc0-a5ef-12305730dbc0'::uuid, 'Why does the projected image appear upside down?', ARRAY['The aperture bends every ray through a curved path', 'Straight-travelling rays from opposite parts of the object cross at the opening', 'The dark wall absorbs the upper half of the scene', 'Diffraction rotates the image after it reaches the screen'], 'Straight-travelling rays from opposite parts of the object cross at the opening', 'The first paragraph explains inversion through straight-line paths crossing at the aperture. It does not involve curved bending, selective absorption, or rotation after arrival.', 0, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('5d2a629d-c0cd-473b-a5ca-a7473481dbc0'::uuid, '4bf9f3e6-f096-4dc0-a5ef-12305730dbc0'::uuid, 'What trade-off results from reducing the aperture size?', ARRAY['The image may become geometrically sharper but dimmer', 'The image becomes brighter but always more blurred', 'The image is preserved for longer but loses colour', 'The projection becomes upright but laterally reversed'], 'The image may become geometrically sharper but dimmer', 'A smaller hole restricts ray bundles and can reduce blur, but admits less light. The other options confuse brightness, permanence, colour and orientation with aperture size.', 1, 'normal');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('13c68c4f-81e6-400e-b28f-e415430ade59'::uuid, '4bf9f3e6-f096-4dc0-a5ef-12305730dbc0'::uuid, 'Which discovery would most undermine the passage''s explanation of pinhole image formation?', ARRAY['Artists used portable camera obscuras before photography', 'Lenses can increase image brightness', 'Light from each object point routinely travels around the aperture in arbitrary curved paths', 'Mirrors can alter a projected image''s orientation'], 'Light from each object point routinely travels around the aperture in arbitrary curved paths', 'The explanation depends on approximately straight-line propagation and selective ray paths, so arbitrary curving would undermine it. The other findings are already compatible with the passage.', 2, 'hard');
INSERT INTO timed_verbal_reasoning_questions (id, passage_id, question_text, options, correct_answer, answer_reason, order_index, difficulty) VALUES ('d2b8dba4-9dd6-41c2-b2cc-30524d6f1c03'::uuid, '4bf9f3e6-f096-4dc0-a5ef-12305730dbc0'::uuid, 'What additional feature was required to turn the temporary projection into photography?', ARRAY['A second pinhole to restore the scene''s orientation', 'A larger room to prevent diffraction', 'A mirror capable of generating its own light', 'A light-sensitive surface and a way to fix the image'], 'A light-sensitive surface and a way to fix the image', 'The final paragraph states this requirement directly. A second pinhole, larger room and self-lighting mirror are neither stated nor relevant to preserving the projection.', 3, 'normal');
INSERT INTO timed_decision_making_tests (id, title, time_minutes) VALUES (5, 'DM Practice Test 5', 37);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('cabedf8f-b975-46c0-ab61-53db6872d42d'::uuid, 5, 'Concert Programme Classification', 'syllogism'::dm_question_type, 'For a fictional concert programme: some oboe pieces are nocturnes; no nocturne is accompanied; every encore is accompanied; some encores are modern pieces; and no modern piece is an oboe piece. For each conclusion, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, 1, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cabedf8f-b975-46c0-ab61-53db6872d42d'::uuid, 'Some oboe pieces are not accompanied.', 'Yes', 'The stated oboe nocturnes cannot be accompanied because no nocturne is accompanied.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cabedf8f-b975-46c0-ab61-53db6872d42d'::uuid, 'No encore is a nocturne.', 'Yes', 'Every encore is accompanied, whereas no nocturne is accompanied, so the two categories cannot overlap.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cabedf8f-b975-46c0-ab61-53db6872d42d'::uuid, 'Some modern pieces are accompanied.', 'Yes', 'Some encores are modern pieces and every encore is accompanied.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cabedf8f-b975-46c0-ab61-53db6872d42d'::uuid, 'Some nocturnes are modern pieces.', 'No', 'The premises establish a modern encore and an oboe nocturne, but do not require any modern piece to be a nocturne.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cabedf8f-b975-46c0-ab61-53db6872d42d'::uuid, 'No oboe piece is an encore.', 'No', 'Only the stated oboe nocturnes are known to be unaccompanied; other oboe pieces could be accompanied encores, provided they are not modern.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('1e93e6ab-fa69-497f-b660-6fa681d29ada'::uuid, 5, 'Beacon Power Classification', 'syllogism'::dm_question_type, 'In a fictional signalling yard: every amber beacon emits pulses; a beacon emits pulses only if it is powered; no portable beacon is powered; some amber beacons have serial tags; and no serial-tagged beacon is portable. Decide whether each conclusion follows.', NULL, NULL, NULL, NULL, 2, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('1e93e6ab-fa69-497f-b660-6fa681d29ada'::uuid, 'Every amber beacon is powered.', 'Yes', 'Amber beacons emit pulses, and pulse-emitting beacons must be powered.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('1e93e6ab-fa69-497f-b660-6fa681d29ada'::uuid, 'No amber beacon is portable.', 'Yes', 'Amber beacons are powered, while no portable beacon is powered.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('1e93e6ab-fa69-497f-b660-6fa681d29ada'::uuid, 'Some serial-tagged beacons are powered.', 'Yes', 'Some amber beacons have serial tags, and every amber beacon is powered.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('1e93e6ab-fa69-497f-b660-6fa681d29ada'::uuid, 'Some amber beacons are portable.', 'No', 'No amber beacon can be portable because amber beacons are powered.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('1e93e6ab-fa69-497f-b660-6fa681d29ada'::uuid, 'Some pulse-emitting beacons have serial tags.', 'Yes', 'The serial-tagged amber beacon emits pulses.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('51ef6a2c-72a2-4f94-92f4-0d3be2552dc3'::uuid, 5, 'Harbour Marker Classification', 'syllogism'::dm_question_type, 'In a fictional marker system: every silver marker is either reflective or numbered, but not both. Every reflective marker is calibrated. No calibrated marker is wooden. Every harbour marker is wooden. Some ridge markers are both silver and numbered. Some harbour markers are silver. Decide whether each conclusion follows.', NULL, NULL, NULL, NULL, 3, 'hard');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('51ef6a2c-72a2-4f94-92f4-0d3be2552dc3'::uuid, 'Some ridge markers are not reflective.', 'Yes', 'The stated ridge markers are silver and numbered; a silver marker cannot be both numbered and reflective.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('51ef6a2c-72a2-4f94-92f4-0d3be2552dc3'::uuid, 'No reflective marker is a harbour marker.', 'Yes', 'Reflective markers are calibrated and therefore not wooden, whereas every harbour marker is wooden.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('51ef6a2c-72a2-4f94-92f4-0d3be2552dc3'::uuid, 'Some silver markers are wooden.', 'Yes', 'Some harbour markers are silver, and every harbour marker is wooden.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('51ef6a2c-72a2-4f94-92f4-0d3be2552dc3'::uuid, 'Every numbered marker is silver.', 'No', 'Silver markers must be reflective or numbered, but nothing says that all numbered markers are silver.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('51ef6a2c-72a2-4f94-92f4-0d3be2552dc3'::uuid, 'Some harbour markers are numbered.', 'Yes', 'The silver harbour markers are wooden, so they cannot be reflective; the exclusive silver rule therefore makes them numbered.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('74a98d3e-61f3-471e-b226-a85b9dbaf580'::uuid, 5, 'Workshop Badge Logic', 'syllogism'::dm_question_type, 'At a fictional workshop: all mentor badges are green; some green badges are magnetic; no magnetic badge is paper; every visitor badge is paper; and no mentor badge is temporary. For each conclusion, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, 4, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('74a98d3e-61f3-471e-b226-a85b9dbaf580'::uuid, 'Some green badges are not paper.', 'Yes', 'Some green badges are magnetic, and magnetic badges are not paper.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('74a98d3e-61f3-471e-b226-a85b9dbaf580'::uuid, 'No visitor badge is magnetic.', 'Yes', 'All visitor badges are paper and no magnetic badge is paper.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('74a98d3e-61f3-471e-b226-a85b9dbaf580'::uuid, 'Some mentor badges are magnetic.', 'No', 'Mentor badges are green, but the magnetic green badges need not be mentor badges.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('74a98d3e-61f3-471e-b226-a85b9dbaf580'::uuid, 'No temporary badge is a mentor badge.', 'Yes', 'No mentor badge is temporary, which is the same disjoint relation.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('74a98d3e-61f3-471e-b226-a85b9dbaf580'::uuid, 'Every paper badge is a visitor badge.', 'No', 'All visitor badges are paper does not imply that all paper badges are visitor badges.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('f672b0f8-6694-4727-af6e-b20c2c632e30'::uuid, 5, 'Container Status Classification', 'syllogism'::dm_question_type, 'In a fictional depot: every tracked container is either labelled or sealed, but not both. Every insulated container is sealed. No collapsible container is sealed. Some tracked containers are insulated. Every labelled container is recyclable. Some collapsible containers are labelled. Decide whether each conclusion follows.', NULL, NULL, NULL, NULL, 5, 'hard');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f672b0f8-6694-4727-af6e-b20c2c632e30'::uuid, 'Some tracked containers are not labelled.', 'Yes', 'The tracked insulated containers are sealed, and a tracked container cannot be both sealed and labelled.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f672b0f8-6694-4727-af6e-b20c2c632e30'::uuid, 'No insulated container is collapsible.', 'Yes', 'Every insulated container is sealed, while no collapsible container is sealed.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f672b0f8-6694-4727-af6e-b20c2c632e30'::uuid, 'Some recyclable containers are collapsible.', 'Yes', 'The stated collapsible labelled containers exist, and every labelled container is recyclable.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f672b0f8-6694-4727-af6e-b20c2c632e30'::uuid, 'Every recyclable container is tracked.', 'No', 'Only labelled containers are guaranteed recyclable; recyclability does not imply tracking.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f672b0f8-6694-4727-af6e-b20c2c632e30'::uuid, 'Some tracked containers are recyclable.', 'No', 'The tracked insulated witnesses are sealed and therefore not labelled; no premise guarantees that any tracked container is recyclable.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('b9daef8f-d433-4d21-9cbb-0c8870a7bde4'::uuid, 5, 'Sample Bench Allocation', 'logic_puzzle'::dm_question_type, 'Four samples J, K, L and M are divided between Red and Blue benches, with exactly two samples at each bench. J and K must be at the same bench. L is at the Blue bench. Which sample other than L must also be at the Blue bench?', NULL, NULL, 'C', 'J and K must stay together. They cannot both be at Blue because L is already there and Blue holds exactly two samples. Therefore J and K are at Red, leaving M with L at Blue.', 6, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b9daef8f-d433-4d21-9cbb-0c8870a7bde4'::uuid, 'A', 'J', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b9daef8f-d433-4d21-9cbb-0c8870a7bde4'::uuid, 'B', 'K', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b9daef8f-d433-4d21-9cbb-0c8870a7bde4'::uuid, 'C', 'M', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b9daef8f-d433-4d21-9cbb-0c8870a7bde4'::uuid, 'D', 'Cannot be determined', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('98801569-48c0-450f-9bf5-029476a11c31'::uuid, 5, 'Delivery Team Districts', 'logic_puzzle'::dm_question_type, 'Three delivery teams--Harbour, Juniper and Kestrel--are assigned different districts (North, East and West) and different shifts (morning, afternoon and evening). Harbour is not assigned North and works later than Juniper. The team assigned East works in the afternoon. Kestrel works in the morning. Juniper is not assigned West. Which district is assigned to Harbour?', NULL, NULL, 'C', 'Kestrel works in the morning, so Kestrel cannot be the East team, which works in the afternoon. The remaining shifts for Harbour and Juniper are afternoon and evening; because Harbour works later, Juniper is afternoon and therefore East. Juniper is not West, Harbour is not North, so Harbour must be West.', 7, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('98801569-48c0-450f-9bf5-029476a11c31'::uuid, 'A', 'North', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('98801569-48c0-450f-9bf5-029476a11c31'::uuid, 'B', 'East', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('98801569-48c0-450f-9bf5-029476a11c31'::uuid, 'C', 'West', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('98801569-48c0-450f-9bf5-029476a11c31'::uuid, 'D', 'Cannot be determined', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('c43380e1-28e0-474b-bced-703e8319ec76'::uuid, 5, 'Archive Review Days', 'logic_puzzle'::dm_question_type, 'Four files--Amber, Birch, Cedar and Dune--are reviewed on Monday, Tuesday, Wednesday and Thursday, one per day. Amber is reviewed before Cedar. Birch is reviewed on Thursday. Dune is reviewed immediately before Cedar. On which day is Amber reviewed?', NULL, NULL, 'A', 'Birch occupies Thursday. The consecutive pair Dune,Cedar can only be Tuesday,Wednesday because Amber must be earlier than Cedar. Therefore Amber is Monday.', 8, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c43380e1-28e0-474b-bced-703e8319ec76'::uuid, 'A', 'Monday', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c43380e1-28e0-474b-bced-703e8319ec76'::uuid, 'B', 'Tuesday', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c43380e1-28e0-474b-bced-703e8319ec76'::uuid, 'C', 'Wednesday', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c43380e1-28e0-474b-bced-703e8319ec76'::uuid, 'D', 'Thursday', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('baf8e627-683f-428a-b860-9d9e4f5275f1'::uuid, 5, 'Six-Relay Control Panel', 'logic_puzzle'::dm_question_type, 'A control panel has six relays P, Q, R, S, T and U. Exactly three relays are on. P and Q always have the same state. R and S cannot both be on. T is on if and only if exactly one of R and S is on. U can be on only when P is off. At least one of P and R is on. Which three relays are on?', NULL, NULL, 'C', 'If P and Q were on, they would use two of the three on positions. R and S cannot both be on; switching either one on would also switch T on, producing at least four on relays, while switching both off leaves no valid third relay because U requires P off. Therefore P and Q are off. At least one of P and R is on, so R is on and S is off. The biconditional makes T on, and U supplies the third on relay. The on relays are R, T and U.', 9, 'hard');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('baf8e627-683f-428a-b860-9d9e4f5275f1'::uuid, 'A', 'P, Q and R', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('baf8e627-683f-428a-b860-9d9e4f5275f1'::uuid, 'B', 'P, Q and T', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('baf8e627-683f-428a-b860-9d9e4f5275f1'::uuid, 'C', 'R, T and U', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('baf8e627-683f-428a-b860-9d9e4f5275f1'::uuid, 'D', 'S, T and U', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('1ab4696b-fa82-4917-86c4-df8f3dcdc960'::uuid, 5, 'Festival Rank Order', 'logic_puzzle'::dm_question_type, 'Five exhibits--Fern, Glass, Loom, Mural and Stone--receive distinct ranks from first to fifth. Loom ranks immediately ahead of Mural. Fern ranks first. Stone ranks fifth. Glass ranks ahead of Loom. Which exhibit ranks third?', NULL, NULL, 'C', 'Fern is first and Stone fifth. Glass must be ahead of the adjacent Loom,Mural pair, so Glass is second, Loom third and Mural fourth.', 10, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('1ab4696b-fa82-4917-86c4-df8f3dcdc960'::uuid, 'A', 'Fern', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('1ab4696b-fa82-4917-86c4-df8f3dcdc960'::uuid, 'B', 'Glass', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('1ab4696b-fa82-4917-86c4-df8f3dcdc960'::uuid, 'C', 'Loom', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('1ab4696b-fa82-4917-86c4-df8f3dcdc960'::uuid, 'D', 'Mural', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('28da56d9-e1ee-44be-a830-36bff05d2aca'::uuid, 5, 'Research Team Inference', 'logic_puzzle'::dm_question_type, 'Exactly three of Asha, Ben, Cora, Dina, Ewan and Farid are selected for a research team. Asha and Ben cannot both be selected. Exactly one of Cora and Dina is selected. Ewan is selected if and only if Ben is selected. If Dina is selected, Farid is selected. At least one of Asha and Ewan is selected. Which statement must be true?', NULL, NULL, 'A', 'Because Ewan is selected exactly when Ben is selected, the rule requiring at least one of Asha and Ewan means at least one of Asha and Ben is selected. The first rule prevents both, so exactly one of Asha and Ben must be selected. The other statements fail in valid teams such as Ben-Cora-Ewan, Asha-Cora-Farid and Asha-Dina-Farid.', 11, 'hard');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('28da56d9-e1ee-44be-a830-36bff05d2aca'::uuid, 'A', 'Exactly one of Asha and Ben is selected.', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('28da56d9-e1ee-44be-a830-36bff05d2aca'::uuid, 'B', 'Cora and Farid are always selected together.', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('28da56d9-e1ee-44be-a830-36bff05d2aca'::uuid, 'C', 'Ewan is selected whenever Cora is selected.', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('28da56d9-e1ee-44be-a830-36bff05d2aca'::uuid, 'D', 'Dina can be selected without Farid.', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('f6480fca-ee61-49e4-82ce-87b928de1d37'::uuid, 5, 'Prototype Output Table', 'interpreting_info'::dm_question_type, 'A fictional studio recorded completed prototypes and those requiring rework. Use only the table. Each prototype belongs to exactly one row.', '{"headers":["Line","Completed","Required rework"],"rows":[["Clay","28","7"],["Metal","24","5"],["Resin","21","6"],["Wood","16","3"]]}'::jsonb, NULL, NULL, NULL, 12, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f6480fca-ee61-49e4-82ce-87b928de1d37'::uuid, 'More than 20% of all completed prototypes required rework.', 'Yes', 'There were 21 reworks out of 89 completed prototypes, about 23.6%.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f6480fca-ee61-49e4-82ce-87b928de1d37'::uuid, 'The clay line completed exactly twice as many prototypes as the wood line.', 'No', 'Clay completed 28 and wood completed 16; twice 16 is 32.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f6480fca-ee61-49e4-82ce-87b928de1d37'::uuid, 'The metal line had the lowest rework rate.', 'No', 'The rates are clay 7/28, metal 5/24, resin 6/21 and wood 3/16; 3/16 is actually lowest, so this statement is No.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f6480fca-ee61-49e4-82ce-87b928de1d37'::uuid, 'Clay and resin together accounted for more than half of all reworks.', 'Yes', 'Clay and resin had 13 of 21 reworks, which is more than half.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f6480fca-ee61-49e4-82ce-87b928de1d37'::uuid, 'If one completed prototype is chosen, it is more likely to be metal than resin.', 'Yes', 'There are 24 metal prototypes and 21 resin prototypes.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('abd51db1-355a-433c-b5c7-3e0aa4adf1b1'::uuid, 5, 'Canal Cargo Table', 'interpreting_info'::dm_question_type, 'A fictional canal recorded cargo moved through three locks. Use only the table. Tonnages are exact and consignments do not overlap.', '{"headers":["Lock","Timber (t)","Grain (t)"],"rows":[["Alpha","36","24"],["Beta","34","28"],["Gamma","27","31"]]}'::jsonb, NULL, NULL, NULL, 13, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('abd51db1-355a-433c-b5c7-3e0aa4adf1b1'::uuid, 'Lock Beta moved the greatest total tonnage.', 'Yes', 'Beta moved 34+28=62 tonnes, compared with Alpha 60 and Gamma 58.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('abd51db1-355a-433c-b5c7-3e0aa4adf1b1'::uuid, 'Across all locks, more timber than grain was moved.', 'Yes', 'Timber totals 97 tonnes and grain totals 83 tonnes.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('abd51db1-355a-433c-b5c7-3e0aa4adf1b1'::uuid, 'At Alpha, timber represented exactly 60% of the recorded tonnage.', 'Yes', 'Alpha moved 36 of 60 tonnes as timber, which is 60%.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('abd51db1-355a-433c-b5c7-3e0aa4adf1b1'::uuid, 'Gamma moved 10 tonnes less grain than Beta.', 'No', 'Gamma moved 31 tonnes of grain and Beta 28, so Gamma moved 3 more.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('abd51db1-355a-433c-b5c7-3e0aa4adf1b1'::uuid, 'The combined tonnage was 180 tonnes.', 'Yes', 'The lock totals are 60, 62 and 58, summing to 180.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('231a87ae-a1c7-4ab5-98fa-af0ce51a2b8c'::uuid, 5, 'Museum Entry Table', 'interpreting_info'::dm_question_type, 'A fictional museum counted adult and child entries in three galleries. Use only the table; each entry is counted once per gallery visit.', '{"headers":["Gallery","Adult entries","Child entries"],"rows":[["A","70","55"],["B","80","50"],["C","75","65"]]}'::jsonb, NULL, NULL, NULL, 14, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('231a87ae-a1c7-4ab5-98fa-af0ce51a2b8c'::uuid, 'Gallery C had the largest total number of entries.', 'Yes', 'Totals are A 125, B 130 and C 140.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('231a87ae-a1c7-4ab5-98fa-af0ce51a2b8c'::uuid, 'Exactly 45% of Gallery B entries were child entries.', 'No', 'Gallery B had 50 child entries out of 130, about 38.5%.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('231a87ae-a1c7-4ab5-98fa-af0ce51a2b8c'::uuid, 'Adult entries exceeded child entries in every gallery.', 'Yes', 'The adult counts 70, 80 and 75 exceed the corresponding child counts 55, 50 and 65.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('231a87ae-a1c7-4ab5-98fa-af0ce51a2b8c'::uuid, 'Across all galleries, there were 95 more adult than child entries.', 'No', 'Adults total 225 and children 170, a difference of 55.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('231a87ae-a1c7-4ab5-98fa-af0ce51a2b8c'::uuid, 'Gallery A and Gallery C together recorded 265 entries.', 'Yes', 'Gallery A recorded 125 and Gallery C 140, totalling 265.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('9fa1774f-3b63-43fb-9e59-dc91105fff5e'::uuid, 5, 'Magazine Delivery Survey', 'interpreting_info'::dm_question_type, 'A fictional magazine surveyed 200 subscribers. Exactly 120 receive the print edition, 95 receive the digital edition, and 45 receive both. Of those who receive neither edition, 18 also attend subscriber events. No other information about event attendance was collected. For each statement, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, 15, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9fa1774f-3b63-43fb-9e59-dc91105fff5e'::uuid, 'Exactly 170 subscribers receive at least one edition.', 'Yes', 'By inclusion-exclusion, 120+95-45=170.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9fa1774f-3b63-43fb-9e59-dc91105fff5e'::uuid, 'Exactly 30 subscribers receive neither edition.', 'Yes', 'There are 200-170=30 subscribers who receive neither.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9fa1774f-3b63-43fb-9e59-dc91105fff5e'::uuid, 'More subscribers receive print only than digital only.', 'Yes', 'Print only is 120-45=75; digital only is 95-45=50.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9fa1774f-3b63-43fb-9e59-dc91105fff5e'::uuid, 'Every event attendee receives neither edition.', 'No', 'Only event attendance among the neither group is described; attendees in other groups are unknown.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('9fa1774f-3b63-43fb-9e59-dc91105fff5e'::uuid, 'Exactly 12 subscribers receive neither edition and do not attend events.', 'Yes', 'Of 30 receiving neither edition, 18 attend events, leaving 12 who do not.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('b8a95b50-b12b-4249-873e-330ef2363f26'::uuid, 5, 'Habitat Parcel Review', 'interpreting_info'::dm_question_type, 'A fictional habitat review covers 150 parcels. Sixty contain scrub, 72 contain wetland and 54 contain meadow. Twenty contain both scrub and wetland, 18 contain both wetland and meadow, and 15 contain both scrub and meadow. Eight contain all three habitats. Pair totals include parcels in all three. For each statement, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, 16, 'hard');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('b8a95b50-b12b-4249-873e-330ef2363f26'::uuid, 'Exactly 41 parcels contain only scrub.', 'No', 'Scrub only is 60-(20-8)-(15-8)-8=33, so this statement is No.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('b8a95b50-b12b-4249-873e-330ef2363f26'::uuid, 'Exactly 103 parcels contain at least one of the three habitats.', 'No', 'Inclusion-exclusion gives 60+72+54-20-18-15+8=141, not 103.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('b8a95b50-b12b-4249-873e-330ef2363f26'::uuid, 'Exactly 9 parcels contain wetland and meadow but not scrub.', 'No', 'Wetland-and-meadow only is 18-8=10.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('b8a95b50-b12b-4249-873e-330ef2363f26'::uuid, 'More parcels contain exactly two habitats than all three.', 'Yes', 'Exactly two totals (20-8)+(18-8)+(15-8)=29, exceeding 8.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('b8a95b50-b12b-4249-873e-330ef2363f26'::uuid, 'Fewer than 10 parcels contain none of the habitats.', 'Yes', 'The union is 141, so 150-141=9 contain none; 9 is fewer than 10, making this Yes.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('7ea355f4-e7ab-4e99-9fe8-22e2156f5e78'::uuid, 5, 'Instrument Inspection Record', 'interpreting_info'::dm_question_type, 'A fictional laboratory inspected 90 instruments. Forty passed calibration on the first attempt. Of the remaining 50, 32 passed after adjustment and 18 were withdrawn. Among the 72 instruments that eventually passed, 27 were optical instruments. Ten of the withdrawn instruments were optical. For each statement, answer Yes if it follows and No if it does not.', NULL, NULL, NULL, NULL, 17, 'normal');
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7ea355f4-e7ab-4e99-9fe8-22e2156f5e78'::uuid, 'Exactly 80% of inspected instruments eventually passed.', 'Yes', 'Seventy-two of 90 passed, which is 80%.', 1);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7ea355f4-e7ab-4e99-9fe8-22e2156f5e78'::uuid, 'More instruments passed after adjustment than passed first time.', 'No', 'Thirty-two passed after adjustment, fewer than the 40 first-time passes.', 2);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7ea355f4-e7ab-4e99-9fe8-22e2156f5e78'::uuid, 'Exactly 37 inspected instruments were optical.', 'Yes', 'There were 27 optical instruments among passes and 10 among withdrawals.', 3);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7ea355f4-e7ab-4e99-9fe8-22e2156f5e78'::uuid, 'Every non-optical instrument eventually passed.', 'No', 'Eight withdrawn instruments were non-optical, because 18 were withdrawn and 10 were optical.', 4);
INSERT INTO timed_decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7ea355f4-e7ab-4e99-9fe8-22e2156f5e78'::uuid, 'An optical instrument was more likely to pass than a non-optical instrument.', 'No', 'Optical pass rate is 27/37, while non-optical pass rate is 45/53; 27/37 is lower.', 5);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('7555bf10-b697-4545-879b-6dd33a740044'::uuid, 5, 'Wayfinding Sign Proposal', 'recognising_assumptions'::dm_question_type, 'A town is deciding whether to replace faded pedestrian wayfinding signs. Which option gives the strongest argument?', NULL, NULL, 'A', 'Option A is strongest because it uses local, task-specific evidence and directly measures failure at the required reading distance. B measures aesthetic preference rather than successful navigation. C establishes a cheaper process without showing that repainting restores legibility or durability. D quantifies a temporary inconvenience rather than the continuing navigation problem.', 18, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('7555bf10-b697-4545-879b-6dd33a740044'::uuid, 'A', 'Yes, because a local audit found 38% of sampled signs unreadable at the required distance, directly measuring the failure replacement is intended to solve.', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('7555bf10-b697-4545-879b-6dd33a740044'::uuid, 'B', 'Yes, because 620 visitors rated the proposed colour scheme highly after viewing mock-ups, with similar preferences reported across every surveyed age group.', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('7555bf10-b697-4545-879b-6dd33a740044'::uuid, 'C', 'No, because a contractor estimated repainting would cost 32% less than replacement and could be completed two weeks sooner than installing new signs.', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('7555bf10-b697-4545-879b-6dd33a740044'::uuid, 'D', 'No, because replacement would close two footpaths for one weekday each and create temporary detours averaging 180 metres for affected pedestrians.', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('4a98e878-3ad1-4229-b71e-4420660ed1e1'::uuid, 5, 'Theatre Captioning Trial', 'recognising_assumptions'::dm_question_type, 'A community theatre is deciding whether to trial captioned performances on two evenings. Which option gives the strongest argument?', NULL, NULL, 'B', 'Option B is strongest because local records evidence unmet access demand and a limited two-evening trial directly measures uptake while containing cost and commitment. A relies on a different audience and programme. C quantifies a modest operational cost but not whether benefits outweigh it. D observes only people who booked under the existing inaccessible arrangement.', 19, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4a98e878-3ad1-4229-b71e-4420660ed1e1'::uuid, 'A', 'Yes, because captioned performances at a theatre in another region sold 18% more tickets than its other shows and attracted many first-time visitors.', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4a98e878-3ad1-4229-b71e-4420660ed1e1'::uuid, 'B', 'Yes, because local booking records show repeated access requests, and a two-evening trial would measure actual uptake before any permanent programming commitment.', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4a98e878-3ad1-4229-b71e-4420660ed1e1'::uuid, 'C', 'No, because technicians estimate that each captioned performance requires 15 additional setup minutes and GBP 90 of extra staffing across the trial.', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4a98e878-3ad1-4229-b71e-4420660ed1e1'::uuid, 'D', 'No, because every captionless performance last season sold out, with waiting lists recorded for three shows under the theatre''s existing booking arrangements.', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('b68e44f5-0396-47b7-9ec8-706a6632ca49'::uuid, 5, 'Canal Gate Sensors', 'recognising_assumptions'::dm_question_type, 'A canal authority is deciding whether to install remote water-level sensors at two gates that currently require manual checks. Which option gives the strongest argument?', NULL, NULL, 'C', 'Option C is strongest because documented outages at both actual sites directly prevent the proposed system performing its core function, and no backup link is planned. A concerns sites without the decisive connectivity constraint. B tests sensor accuracy rather than communications reliability. D compares a limited routine cost measure and does not establish operational failure.', 20, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b68e44f5-0396-47b7-9ec8-706a6632ca49'::uuid, 'A', 'Yes, because a neighbouring canal with year-round cellular coverage recorded 31% fewer inspection callouts during the two years after installing remote sensors.', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b68e44f5-0396-47b7-9ec8-706a6632ca49'::uuid, 'B', 'Yes, because vendor bench tests across the expected temperature range kept water-level readings within two centimetres of calibrated manual measurements.', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b68e44f5-0396-47b7-9ec8-706a6632ca49'::uuid, 'C', 'No, because documented winter network outages affect both proposed gates, and the installation plan provides no backup link for transmitting readings during those failures.', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('b68e44f5-0396-47b7-9ec8-706a6632ca49'::uuid, 'D', 'No, because forecast routine sensor maintenance is 5% more expensive than scheduled manual checks under the authority''s current annual staffing budget.', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('23eadbde-62f2-48af-ad4b-34dc103308fc'::uuid, 5, 'Shared Workshop Induction', 'recognising_assumptions'::dm_question_type, 'A shared workshop is deciding whether all new members should complete a short machine-safety induction before booking powered equipment. Which option gives the strongest argument?', NULL, NULL, 'A', 'Option A is strongest because workshop-specific incident records connect the proposed induction to the affected group and the precise hazard. B is general manufacturer guidance without local outcome evidence. C reports outcomes for experienced members rather than new users. D quantifies a capacity cost but does not outweigh the directly evidenced safety problem.', 21, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('23eadbde-62f2-48af-ad4b-34dc103308fc'::uuid, 'A', 'Yes, because local incident records show that 14 of the last 18 machine near-misses involved new members who had not received the current safety briefing.', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('23eadbde-62f2-48af-ad4b-34dc103308fc'::uuid, 'B', 'Yes, because the equipment manufacturer recommends induction before using comparable powered machines at shared facilities with a broadly similar range of tools.', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('23eadbde-62f2-48af-ad4b-34dc103308fc'::uuid, 'C', 'No, because experienced members completed 2,300 powered-equipment bookings last year without a recorded injury under the workshop''s existing voluntary training system.', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('23eadbde-62f2-48af-ad4b-34dc103308fc'::uuid, 'D', 'No, because a weekly induction would remove one bookable machine hour, and the affected period currently operates at 62% average capacity.', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('4c0c4f8b-9ed7-473f-8af8-da6bc039a8d8'::uuid, 5, 'Garden Irrigation Upgrade', 'recognising_assumptions'::dm_question_type, 'A community garden wants to reduce irrigation water use without lowering crop yield. Its funding rule requires the controls to repay their full costs within three years. Which option gives the strongest argument about replacing fixed timers across all plots?', NULL, NULL, 'A', 'Option A is strongest overall because it is local, controls crop and soil differences, directly measures both stated outcomes, and tests the mandatory payback rule under a deliberately adverse maintenance assumption. B is a substantial rival but remains vulnerable to self-selection and simultaneous mulching despite its larger, longer dataset. C reports contained faults without outcome harm. D relies on a model that excludes major whole-life variables.', 22, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4c0c4f8b-9ed7-473f-8af8-da6bc039a8d8'::uuid, 'A', 'Yes, because a local matched trial found 21% lower water use with unchanged yield and a 30-month payback under doubled maintenance costs; it covered both soil types for one season.', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4c0c4f8b-9ed7-473f-8af8-da6bc039a8d8'::uuid, 'B', 'Yes, because a two-season survey of 140 gardens found 19% lower adjusted water use with unchanged yield and 26-month median payback; participants self-selected and 72% also introduced mulching.', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4c0c4f8b-9ed7-473f-8af8-da6bc039a8d8'::uuid, 'C', 'No, because four of 48 pilot sensors required recalibration during scheduled checks, adding 11 staff hours; none caused a missed moisture target or measurable reduction in yield.', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('4c0c4f8b-9ed7-473f-8af8-da6bc039a8d8'::uuid, 'D', 'No, because fixed timers cost GBP 4,800 less to purchase and install; a five-year budget model excluding water use and service life still favoured timers by GBP 900.', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('f5b5e55a-a6fe-41ff-b90d-b08548dde90a'::uuid, 5, 'Record Status Diagram', 'venn_diagram'::dm_question_type, 'A register contains 34 records. Twenty have been reviewed, 15 have been archived, six have both statuses, and five have neither status. Which diagram represents the register? Each number is an exclusive-region count.', NULL, NULL, 'A', 'Reviewed only is 20-6=14 and Archived only is 15-6=9. Option A also shows six with both statuses and five with neither.', 23, 'normal');
