INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('57a6d42b-09fd-4eb6-bd18-6ab009488896'::uuid, 5, 'Trail Route Categories', 'venn_diagram'::dm_question_type, 'A guide lists 28 trails. Eight are express but not scenic, seven are scenic but not express, four are both express and scenic, and nine are closed routes in a separate category. Which diagram represents these data? Each number is an exclusive-region count.', NULL, NULL, 'A', 'Option A shows the four stated exclusive counts: 8 express only, 7 scenic only, 4 in both, and 9 in the separate closed category.', 24, 'normal');
