INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('359239f8-3271-467a-8150-95f1f3db7e09'::uuid, 5, 'Market Stall Tags', 'venn_diagram'::dm_question_type, 'The diagram classifies fictional market stalls by four tags. Each number is an exclusive-region count. How many stalls have exactly two of the four tags?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Ceramic","shape":"parallelogram","geometry":{"cx":388.52,"cy":390.08,"width":208.23,"height":212.35,"rotationDeg":78.84}},{"id":"set2","label":"Outdoor","shape":"rounded_rectangle","geometry":{"cx":313.31,"cy":373.96,"width":282.04,"height":228.96,"rotationDeg":123.9}},{"id":"set3","label":"Local","shape":"ellipse","geometry":{"cx":185.53,"cy":345.22,"width":308.37,"height":272.27,"rotationDeg":172.37}},{"id":"set4","label":"New","shape":"pentagon","geometry":{"cx":66.34,"cy":306.59,"width":255.17,"height":260.39,"rotationDeg":69.77}}],"regions":[{"id":"set1_only:0","value":8},{"id":"set2_only:0","value":6},{"id":"set2_only:1","value":4},{"id":"set1_set2_only:0","value":7},{"id":"set3_only:0","value":5},{"id":"set2_set3_only:0","value":3},{"id":"set1_set2_set3_only:0","value":2},{"id":"set4_only:0","value":9},{"id":"set3_set4_only:0","value":1}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, 'B', 'The exactly-two faces contain 7 (Ceramic and Outdoor), 3 (Outdoor and Local), and 1 (Local and New). Their sum is 11.', 25, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('359239f8-3271-467a-8150-95f1f3db7e09'::uuid, 'A', '9', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('359239f8-3271-467a-8150-95f1f3db7e09'::uuid, 'B', '11', NULL, 2);
