INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('359239f8-3271-467a-8150-95f1f3db7e09'::uuid, 'D', '15', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('cbafbe28-de5f-40df-909d-e59f2b41190d'::uuid, 5, 'Survey Route Flags', 'venn_diagram'::dm_question_type, 'The diagram classifies survey routes by five flags, and every shown number is an exclusive-region count. The Priority-only count is hidden by ?. Two Historic-only routes are upgraded so that they also carry the Priority flag, and four new Priority-only routes are added. After these changes, three-quarters of all routes carrying Priority or Historic carry Priority. What was the original Priority-only count?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Priority","shape":"rounded_rectangle","geometry":{"cx":289.34,"cy":506.06,"width":258.97,"height":341.71,"rotationDeg":8.56}},{"id":"set2","label":"Remote","shape":"right_arrow","geometry":{"cx":596.57,"cy":382.87,"width":265.4,"height":250.11,"rotationDeg":-125.53}},{"id":"set3","label":"Historic","shape":"pentagon","geometry":{"cx":462.36,"cy":682.81,"width":235.57,"height":274.9,"rotationDeg":161.06}},{"id":"set4","label":"Night","shape":"octagon","geometry":{"cx":767.87,"cy":606.78,"width":191.75,"height":259.79,"rotationDeg":119.95}},{"id":"set5","label":"Freight","shape":"trapezoid","geometry":{"cx":645.97,"cy":886.67,"width":260.43,"height":370.34,"rotationDeg":-105.71}}],"regions":[{"id":"set1_only:0","value":"?"},{"id":"set2_only:0","value":9},{"id":"set3_only:0","value":11},{"id":"set1_set3_only:0","value":6},{"id":"set4_only:0","value":8},{"id":"set5_only:0","value":7}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, 'C', 'Originally the Priority-or-Historic union contains ? + 6 + 11 = ? + 17 routes. Moving two Historic-only routes into the overlap does not change that union, while four new Priority-only routes increase it to ? + 21. The changed Priority total is ? + 6 + 2 + 4 = ? + 12. Therefore (? + 12)/(? + 21) = 3/4, so 4? + 48 = 3? + 63 and ? = 15.', 26, 'hard');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('cbafbe28-de5f-40df-909d-e59f2b41190d'::uuid, 'A', '9', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('cbafbe28-de5f-40df-909d-e59f2b41190d'::uuid, 'B', '14', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('cbafbe28-de5f-40df-909d-e59f2b41190d'::uuid, 'C', '15', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('cbafbe28-de5f-40df-909d-e59f2b41190d'::uuid, 'D', '21', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('a42edc2a-8e72-4622-9ef0-3e8c102753c7'::uuid, 5, 'Information Format Requests', 'venn_diagram'::dm_question_type, 'The diagram classifies fictional requests by six information formats. Each number is an exclusive-region count. How many requests specify at least two formats?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Audio","shape":"right_arrow","geometry":{"cx":338.04,"cy":577.04,"width":301.85,"height":225.42,"rotationDeg":-43.14}},{"id":"set2","label":"Braille","shape":"hexagon","geometry":{"cx":252.61,"cy":446.74,"width":270.96,"height":247.66,"rotationDeg":-103.04}},{"id":"set3","label":"Large print","shape":"ellipse","geometry":{"cx":309.3,"cy":274.4,"width":338.13,"height":311.62,"rotationDeg":-152.44}},{"id":"set4","label":"Easy read","shape":"rectangle","geometry":{"cx":463.79,"cy":249.05,"width":248.7,"height":205.95,"rotationDeg":152.94}},{"id":"set5","label":"Translation","shape":"octagon","geometry":{"cx":564.36,"cy":378.99,"width":259.97,"height":191.85,"rotationDeg":-97.4}},{"id":"set6","label":"Video","shape":"circle","geometry":{"cx":523.28,"cy":514.49,"width":289.01,"height":289.01,"rotationDeg":0}}],"regions":[{"id":"set1_only:0","value":5},{"id":"set2_only:0","value":7},{"id":"set1_set2_only:0","value":4},{"id":"set3_only:0","value":6},{"id":"set2_set3_only:0","value":3},{"id":"set4_only:0","value":8},{"id":"set3_set4_only:0","value":2},{"id":"set5_only:0","value":9},{"id":"set4_set5_only:0","value":1},{"id":"set6_only:0","value":10},{"id":"set1_set6_only:0","value":11},{"id":"set5_set6_only:0","value":12}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, 'C', 'The multi-format faces contain 4, 3, 2, 1, 11 and 12 requests. Adding them once each gives 33.', 27, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('a42edc2a-8e72-4622-9ef0-3e8c102753c7'::uuid, 'A', '27', NULL, 1);
