INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('c06727c2-dd21-4e0a-8b17-32fb86155132'::uuid, 5, 'Energy Project Regions', 'venn_diagram'::dm_question_type, 'The diagram classifies fictional projects by Solar, Wind and Storage. Each letter marks one connected exclusive face. Which letter marks projects that use Wind and Storage but not Solar?', NULL, '{"schemaVersion":2,"sets":[{"id":"set1","label":"Solar","shape":"triangle","geometry":{"cx":447.68,"cy":323.15,"width":381.77,"height":654.28,"rotationDeg":18.47}},{"id":"set2","label":"Wind","shape":"hexagon","geometry":{"cx":318.88,"cy":327.38,"width":296.33,"height":722.81,"rotationDeg":-51.53}},{"id":"set3","label":"Storage","shape":"circle","geometry":{"cx":307.92,"cy":449.26,"width":411.31,"height":411.31,"rotationDeg":0}}],"regions":[{"id":"set1_only:0","value":"A"},{"id":"set1_only:1","value":"B"},{"id":"set2_only:0","value":"C"},{"id":"set2_only:1","value":"D"},{"id":"set1_set2_only:0","value":"E"},{"id":"set3_only:0","value":"F"},{"id":"set1_set3_only:0","value":"G"},{"id":"set2_set3_only:0","value":"H"},{"id":"set1_set2_set3_only:0","value":"J"}],"labelStyle":{"minFontSize":14,"preferredFontSize":18,"padding":3}}'::jsonb, 'C', 'The Wind-and-Storage-only face is labelled H. J is inside all three sets, while D and F represent different memberships.', 28, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c06727c2-dd21-4e0a-8b17-32fb86155132'::uuid, 'A', 'D', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c06727c2-dd21-4e0a-8b17-32fb86155132'::uuid, 'B', 'F', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c06727c2-dd21-4e0a-8b17-32fb86155132'::uuid, 'C', 'H', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c06727c2-dd21-4e0a-8b17-32fb86155132'::uuid, 'D', 'J', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('d08e2685-8683-4865-9b77-e126836a7dfa'::uuid, 5, 'Inspection Review Panel', 'probabilistic'::dm_question_type, 'A four-person review panel is selected at random from five field inspectors, four laboratory analysts and three project coordinators. Given that the selected panel contains at least one person from each of the three groups, what is the probability that it contains exactly two field inspectors?', NULL, NULL, 'B', 'With all three groups represented in a four-person panel, the group-count patterns are (2,1,1), (1,2,1) and (1,1,2). Their counts are C(5,2) x C(4,1) x C(3,1) = 120; C(5,1) x C(4,2) x C(3,1) = 90; and C(5,1) x C(4,1) x C(3,2) = 60. There are 270 eligible panels, of which 120 have two field inspectors, so the probability is 120/270 = 4/9.', 29, 'hard');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('d08e2685-8683-4865-9b77-e126836a7dfa'::uuid, 'A', '1/3', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('d08e2685-8683-4865-9b77-e126836a7dfa'::uuid, 'B', '4/9', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('d08e2685-8683-4865-9b77-e126836a7dfa'::uuid, 'C', '1/2', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('d08e2685-8683-4865-9b77-e126836a7dfa'::uuid, 'D', '5/9', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('ad98d086-e667-48f4-afd5-bf50069d3fbf'::uuid, 5, 'First Successful Upload', 'probabilistic'::dm_question_type, 'Each upload attempt succeeds with probability 1/4, independently of earlier attempts. What is the probability that the first successful upload occurs on the third attempt?', NULL, NULL, 'B', 'The first two attempts must fail and the third must succeed: (3/4) x (3/4) x (1/4)=9/64.', 30, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('ad98d086-e667-48f4-afd5-bf50069d3fbf'::uuid, 'A', '3/64', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('ad98d086-e667-48f4-afd5-bf50069d3fbf'::uuid, 'B', '9/64', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('ad98d086-e667-48f4-afd5-bf50069d3fbf'::uuid, 'C', '9/16', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('ad98d086-e667-48f4-afd5-bf50069d3fbf'::uuid, 'D', '27/64', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('a71c68fc-5ad2-4173-b0bf-0d85a83a173f'::uuid, 5, 'Number Divisibility Draw', 'probabilistic'::dm_question_type, 'One integer is selected uniformly at random from 1 to 60 inclusive. What is the probability that it is divisible by 4 or by 9?', NULL, NULL, 'C', 'There are 15 multiples of 4 and 6 multiples of 9. One number, 36, is counted in both lists, so the union has 15+6-1=20 numbers. The probability is 20/60=1/3.', 31, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('a71c68fc-5ad2-4173-b0bf-0d85a83a173f'::uuid, 'A', '1/4', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('a71c68fc-5ad2-4173-b0bf-0d85a83a173f'::uuid, 'B', '3/10', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('a71c68fc-5ad2-4173-b0bf-0d85a83a173f'::uuid, 'C', '1/3', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('a71c68fc-5ad2-4173-b0bf-0d85a83a173f'::uuid, 'D', '7/20', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('e3793415-80aa-45be-8216-70b8efa74405'::uuid, 5, 'Proposal Relative Order', 'probabilistic'::dm_question_type, 'Seven distinct proposals, including J, K and L, are placed in a uniformly random presentation order. What is the probability that J appears before K and K appears before L?', NULL, NULL, 'B', 'The other four proposals do not affect the relative order of J, K and L. Those three proposals have 3! = 6 equally likely relative orders, and only J-K-L satisfies both conditions. The probability is 1/6.', 32, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('e3793415-80aa-45be-8216-70b8efa74405'::uuid, 'A', '1/7', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('e3793415-80aa-45be-8216-70b8efa74405'::uuid, 'B', '1/6', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('e3793415-80aa-45be-8216-70b8efa74405'::uuid, 'C', '1/3', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('e3793415-80aa-45be-8216-70b8efa74405'::uuid, 'D', '1/2', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('691e68af-dd79-4681-868c-69263b07abd1'::uuid, 5, 'Access Code Digits', 'probabilistic'::dm_question_type, 'A four-digit access code is formed by choosing each digit independently from 0 to 9, with repetition allowed. What is the probability that the code contains exactly one zero?', NULL, NULL, 'A', 'Choose the zero position in 4 ways and choose each other digit from 9 non-zero digits: 4 x 9^3 outcomes out of 10^4. This is 2916/10000=729/2500.', 33, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('691e68af-dd79-4681-868c-69263b07abd1'::uuid, 'A', '729/2500', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('691e68af-dd79-4681-868c-69263b07abd1'::uuid, 'B', '9/25', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('691e68af-dd79-4681-868c-69263b07abd1'::uuid, 'C', '81/250', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('691e68af-dd79-4681-868c-69263b07abd1'::uuid, 'D', '1/10', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('c23714a5-b0a9-4bc1-a724-c66855af25ed'::uuid, 5, 'Prototype Module Pairing', 'probabilistic'::dm_question_type, 'Six distinct prototype modules are paired uniformly at random into three unordered pairs. What is the probability that two specified modules, K and L, are paired together?', NULL, NULL, 'C', 'Once module K is fixed, its partner is equally likely to be any of the other five modules. Exactly one possible partner is L, so the probability is 1/5.', 34, 'normal');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c23714a5-b0a9-4bc1-a724-c66855af25ed'::uuid, 'A', '1/15', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c23714a5-b0a9-4bc1-a724-c66855af25ed'::uuid, 'B', '1/6', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c23714a5-b0a9-4bc1-a724-c66855af25ed'::uuid, 'C', '1/5', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('c23714a5-b0a9-4bc1-a724-c66855af25ed'::uuid, 'D', '1/3', NULL, 4);
INSERT INTO timed_decision_making_questions (id, test_id, title, type, stem, table_data, stimulus_diagram, correct_answer, answer_reason, order_index, difficulty) VALUES ('468cccb3-eb88-4712-992c-52272be6e58e'::uuid, 5, 'Museum Display Arrangement', 'probabilistic'::dm_question_type, 'A museum store contains four distinct bronze objects, three distinct glass objects and two distinct stone objects. Three objects are selected without replacement and placed at random in left, centre and right positions. Given that at least one selected object is stone, what is the probability that the centre object is stone and the two outer objects are one bronze and one glass?', NULL, NULL, 'B', 'There are 9×8×7 = 504 ordered displays. Those with no stone number 7×6×5 = 210, so the condition leaves 294 displays. Favourable displays choose the centre stone in 2 ways, one bronze in 4 ways, one glass in 3 ways, and arrange bronze/glass in the two outer positions in 2 ways: 2×4×3×2 = 48. The conditional probability is 48/294 = 8/49.', 35, 'hard');
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('468cccb3-eb88-4712-992c-52272be6e58e'::uuid, 'A', '4/49', NULL, 1);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('468cccb3-eb88-4712-992c-52272be6e58e'::uuid, 'B', '8/49', NULL, 2);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('468cccb3-eb88-4712-992c-52272be6e58e'::uuid, 'C', '16/49', NULL, 3);
INSERT INTO timed_decision_making_question_options (question_id, label, option_text, option_data, order_index) VALUES ('468cccb3-eb88-4712-992c-52272be6e58e'::uuid, 'D', '8/21', NULL, 4);
INSERT INTO timed_quantitative_reasoning_tests (id, title, time_minutes) VALUES (5, 'QR Timed Test 5', 26);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('3e43934f-148c-4fe6-b648-4cf94e5d075c'::uuid, 5, '3e43934f-148c-4fe6-b648-4cf94e5d075c', 'Film Archive Restoration', '{"type":"table","context":"A film archive inspected reels from five collections. Two technicians share the restoration work; each is scheduled for 6 hours per day and spends 80% of that time actively restoring reels.","data":{"headers":["Collection","Reels received","Usable reels","Minutes per usable reel"],"rows":[["Documentary","240","204","16"],["Drama","180","162","22"],["Science","150","114","18"],["Animation","120","108","25"],["Newsreel","210","189","12"]]}}'::jsonb, 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('0cd6da0f-423c-488b-a882-5fcdc4c1033d'::uuid, '3e43934f-148c-4fe6-b648-4cf94e5d075c'::uuid, '0cd6da0f-423c-488b-a882-5fcdc4c1033d', 'What percentage of the Documentary reels were usable?', '[{"label":"A","text":"80%"},{"label":"B","text":"82%"},{"label":"C","text":"85%"},{"label":"D","text":"88%"},{"label":"E","text":"90%"}]'::jsonb, 'C', 'Usable percentage = 204 ÷ 240 × 100 = 85%. No rounding is required. The answer is 85%.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('263a9971-401b-4675-92f4-ad2e008c38db'::uuid, '3e43934f-148c-4fe6-b648-4cf94e5d075c'::uuid, '263a9971-401b-4675-92f4-ad2e008c38db', 'How many hours of restoration work are required for all usable Drama reels?', '[{"label":"A","text":"54.0 hours"},{"label":"B","text":"56.7 hours"},{"label":"C","text":"59.4 hours"},{"label":"D","text":"60.0 hours"},{"label":"E","text":"66.0 hours"}]'::jsonb, 'C', 'The Drama collection has 162 usable reels. Work time = 162 × 22 = 3,564 minutes. Converting to hours gives 3,564 ÷ 60 = 59.4 hours. The answer is 59.4 hours.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('d7526cd4-0479-4885-86f5-2ce32c219278'::uuid, '3e43934f-148c-4fe6-b648-4cf94e5d075c'::uuid, 'd7526cd4-0479-4885-86f5-2ce32c219278', 'What is the minimum number of whole working days the two technicians need to restore all usable Science reels?', '[{"label":"A","text":"2 days"},{"label":"B","text":"3 days"},{"label":"C","text":"4 days"},{"label":"D","text":"5 days"},{"label":"E","text":"6 days"}]'::jsonb, 'C', 'Science restoration requires 114 × 18 = 2,052 minutes. The two technicians provide 2 × 6 × 60 × 0.80 = 576 active minutes per day. The work takes 2,052 ÷ 576 = 3.5625 days, so a fourth whole day is required. The answer is 4 days.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('0e8ceeef-93aa-4b26-9daf-f90249e2d064'::uuid, 5, '0e8ceeef-93aa-4b26-9daf-f90249e2d064', 'Coastal Water Sample Processing', '{"type":"table","context":"A coastal laboratory processed water readings from four monitoring stations. Each positive reading requires a £6 confirmation test. The project also has a fixed setup cost of £450.","data":{"headers":["Station","Readings scheduled","Valid readings","Positive readings","Cost per valid reading"],"rows":[["North","160","148","37","£2.40"],["East","200","184","46","£2.10"],["South","180","153","51","£2.60"],["West","140","126","21","£2.30"]]}}'::jsonb, 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('5118442f-ab22-42aa-982e-eec1b1c8bd8c'::uuid, '0e8ceeef-93aa-4b26-9daf-f90249e2d064'::uuid, '5118442f-ab22-42aa-982e-eec1b1c8bd8c', 'What percentage of the scheduled readings at East station were valid?', '[{"label":"A","text":"84%"},{"label":"B","text":"88%"},{"label":"C","text":"90%"},{"label":"D","text":"92%"},{"label":"E","text":"96%"}]'::jsonb, 'D', 'Valid percentage = 184 ÷ 200 × 100 = 92%. The answer is 92%.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('1ed62118-86b2-4eb4-a14f-616614cdd1b9'::uuid, '0e8ceeef-93aa-4b26-9daf-f90249e2d064'::uuid, '1ed62118-86b2-4eb4-a14f-616614cdd1b9', 'Across all four stations, what percentage of valid readings were positive, to the nearest 0.1%?', '[{"label":"A","text":"22.8%"},{"label":"B","text":"24.1%"},{"label":"C","text":"25.4%"},{"label":"D","text":"26.7%"},{"label":"E","text":"28.0%"}]'::jsonb, 'C', 'Total positives = 37 + 46 + 51 + 21 = 155. Total valid readings = 148 + 184 + 153 + 126 = 611. The percentage is 155 ÷ 611 × 100 = 25.368...%, which rounds to 25.4%. The answer is 25.4%.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('9627c16b-0f4f-4b84-8a9b-b52fd238b890'::uuid, '0e8ceeef-93aa-4b26-9daf-f90249e2d064'::uuid, '9627c16b-0f4f-4b84-8a9b-b52fd238b890', 'What was the total project cost, including processing, all confirmation tests and the fixed setup cost?', '[{"label":"A","text":"£2,359.20"},{"label":"B","text":"£2,739.20"},{"label":"C","text":"£2,809.20"},{"label":"D","text":"£2,905.20"},{"label":"E","text":"£3,289.20"}]'::jsonb, 'C', 'Processing costs are 148 × £2.40 + 184 × £2.10 + 153 × £2.60 + 126 × £2.30 = £1,429.20. Confirmation tests cost 155 × £6 = £930. Adding the £450 setup cost gives £1,429.20 + £930 + £450 = £2,809.20. The answer is £2,809.20.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('53642c29-aacc-44c0-90ae-571ecbbdc107'::uuid, 5, '53642c29-aacc-44c0-90ae-571ecbbdc107', 'Archaeological Trench Finds', '{"type":"bar_chart","context":"An archaeological survey classified finds from five trenches as organic material or ceramic material. The bars show the number of finds in each category.","data":{"title":"Finds by Trench and Material","labels":["Trench A","Trench B","Trench C","Trench D","Trench E"],"series":[{"name":"Organic","values":[48,60,36,72,40]},{"name":"Ceramic","values":[32,45,54,24,50]}],"yAxisLabel":"Number of finds","unit":"finds"}}'::jsonb, 2);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('69e312cd-df44-4ce7-8158-073659b3cd3b'::uuid, '53642c29-aacc-44c0-90ae-571ecbbdc107'::uuid, '69e312cd-df44-4ce7-8158-073659b3cd3b', 'How many finds were recorded in Trench C altogether?', '[{"label":"A","text":"72"},{"label":"B","text":"84"},{"label":"C","text":"90"},{"label":"D","text":"96"},{"label":"E","text":"108"}]'::jsonb, 'C', 'Trench C contains 36 organic finds and 54 ceramic finds. Total = 36 + 54 = 90 finds. The answer is 90.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('2112a8ed-4a6a-4a39-ace4-0bd3adc3790c'::uuid, '53642c29-aacc-44c0-90ae-571ecbbdc107'::uuid, '2112a8ed-4a6a-4a39-ace4-0bd3adc3790c', 'What percentage of the finds in Trench B were ceramic, to the nearest 0.1%?', '[{"label":"A","text":"37.5%"},{"label":"B","text":"40.0%"},{"label":"C","text":"42.9%"},{"label":"D","text":"45.0%"},{"label":"E","text":"57.1%"}]'::jsonb, 'C', 'Trench B has 60 + 45 = 105 finds. The ceramic share is 45 ÷ 105 × 100 = 42.857...%, which rounds to 42.9%. The answer is 42.9%.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('e8715e88-7145-4fe0-8afb-a66846b88127'::uuid, '53642c29-aacc-44c0-90ae-571ecbbdc107'::uuid, 'e8715e88-7145-4fe0-8afb-a66846b88127', 'Across all five trenches, 15% of organic finds and 20% of ceramic finds are expected to need conservation. What is the estimated total number needing conservation, to the nearest whole find?', '[{"label":"A","text":"70"},{"label":"B","text":"75"},{"label":"C","text":"79"},{"label":"D","text":"80"},{"label":"E","text":"82"}]'::jsonb, 'C', 'There are 48 + 60 + 36 + 72 + 40 = 256 organic finds and 32 + 45 + 54 + 24 + 50 = 205 ceramic finds. Expected conservation work = 0.15 × 256 + 0.20 × 205 = 38.4 + 41 = 79.4 finds. Rounding the final total to the nearest whole find gives 79. The answer is 79.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('189f0537-9ec8-4eea-a36d-53d57b28a8d5'::uuid, 5, '189f0537-9ec8-4eea-a36d-53d57b28a8d5', 'Laser Sensor Calibration', '{"type":"line_graph","context":"Two laser sensors were tested over six calibration cycles. The graph shows each sensor''s absolute measurement deviation in micrometres (µm).","data":{"title":"Absolute Deviation by Calibration Cycle","labels":["Cycle 1","Cycle 2","Cycle 3","Cycle 4","Cycle 5","Cycle 6"],"series":[{"name":"Sensor A","values":[2,3,5,4,6,8]},{"name":"Sensor B","values":[7,6,6,5,4,3]}],"yAxisLabel":"Absolute deviation (µm)","unit":"µm"}}'::jsonb, 3);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('62436299-2d20-49e1-91a6-9cae566c1098'::uuid, '189f0537-9ec8-4eea-a36d-53d57b28a8d5'::uuid, '62436299-2d20-49e1-91a6-9cae566c1098', 'What was the difference between the two sensor deviations in Cycle 1?', '[{"label":"A","text":"2 µm"},{"label":"B","text":"3 µm"},{"label":"C","text":"4 µm"},{"label":"D","text":"5 µm"},{"label":"E","text":"7 µm"}]'::jsonb, 'D', 'In Cycle 1, Sensor A deviated by 2 µm and Sensor B by 7 µm. The difference is 7 − 2 = 5 µm. The answer is 5 µm.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('e32c7164-6cb1-4040-9c34-10e146201973'::uuid, '189f0537-9ec8-4eea-a36d-53d57b28a8d5'::uuid, 'e32c7164-6cb1-4040-9c34-10e146201973', 'What was Sensor A''s mean deviation across the six cycles, to the nearest 0.1 µm?', '[{"label":"A","text":"4.2 µm"},{"label":"B","text":"4.5 µm"},{"label":"C","text":"4.7 µm"},{"label":"D","text":"5.0 µm"},{"label":"E","text":"5.3 µm"}]'::jsonb, 'C', 'Sensor A''s deviations sum to 2 + 3 + 5 + 4 + 6 + 8 = 28 µm. Mean = 28 ÷ 6 = 4.666... µm, which rounds to 4.7 µm. The answer is 4.7 µm.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('027a10d2-8511-4d7f-bdc0-9ff67fbbc391'::uuid, '189f0537-9ec8-4eea-a36d-53d57b28a8d5'::uuid, '027a10d2-8511-4d7f-bdc0-9ff67fbbc391', 'A technician spends 12 minutes correcting each micrometre by which a reading exceeds 4 µm. How much correction time is needed for all readings from both sensors?', '[{"label":"A","text":"2 hours 12 minutes"},{"label":"B","text":"2 hours 36 minutes"},{"label":"C","text":"3 hours"},{"label":"D","text":"3 hours 24 minutes"},{"label":"E","text":"4 hours"}]'::jsonb, 'C', 'Sensor A exceeds 4 µm by 1 + 2 + 4 = 7 µm in total. Sensor B exceeds 4 µm by 3 + 2 + 2 + 1 = 8 µm. Total excess = 15 µm, so correction time = 15 × 12 = 180 minutes = 3 hours. The answer is 3 hours.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('723b2310-87fe-427a-9262-5902eeed8c02'::uuid, 5, '723b2310-87fe-427a-9262-5902eeed8c02', 'Recovered Pottery Glazes', '{"type":"pie_chart","context":"A conservation store contains 2,400 pottery fragments. The pie chart shows the number in each glaze category.","data":{"title":"Pottery Fragments by Glaze Category","segments":[{"label":"Blue glaze","value":720},{"label":"Green glaze","value":528},{"label":"Brown glaze","value":432},{"label":"White glaze","value":360},{"label":"Unglazed","value":360}],"unit":"fragments","total":2400}}'::jsonb, 4);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('c46d548c-8868-4673-8cc3-2c7d669fc9a5'::uuid, '723b2310-87fe-427a-9262-5902eeed8c02'::uuid, 'c46d548c-8868-4673-8cc3-2c7d669fc9a5', 'How many fragments have green glaze?', '[{"label":"A","text":"432"},{"label":"B","text":"480"},{"label":"C","text":"528"},{"label":"D","text":"600"},{"label":"E","text":"720"}]'::jsonb, 'C', 'Green glaze accounts for 22% of 2,400. The number is 0.22 × 2,400 = 528 fragments. The answer is 528.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('8f5eadef-fc1e-4790-b2c2-cb577f11aec3'::uuid, '723b2310-87fe-427a-9262-5902eeed8c02'::uuid, '8f5eadef-fc1e-4790-b2c2-cb577f11aec3', 'How many more fragments have blue glaze than white glaze?', '[{"label":"A","text":"240"},{"label":"B","text":"300"},{"label":"C","text":"360"},{"label":"D","text":"420"},{"label":"E","text":"480"}]'::jsonb, 'C', 'The percentage-point difference is 30% − 15% = 15%. The number difference is 0.15 × 2,400 = 360 fragments. The answer is 360.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('cab4e67f-5a37-4a73-b8d6-8ef9b52a09e4'::uuid, '723b2310-87fe-427a-9262-5902eeed8c02'::uuid, 'cab4e67f-5a37-4a73-b8d6-8ef9b52a09e4', 'A further 120 unglazed fragments are added to the store. What percentage of the new total is unglazed, to the nearest 0.1%?', '[{"label":"A","text":"17.1%"},{"label":"B","text":"18.0%"},{"label":"C","text":"19.0%"},{"label":"D","text":"20.0%"},{"label":"E","text":"21.4%"}]'::jsonb, 'C', 'Initially, 15% of 2,400 = 360 fragments are unglazed. After adding 120, there are 480 unglazed out of 2,520 total. The percentage is 480 ÷ 2,520 × 100 = 19.0476...%, which rounds to 19.0%. The answer is 19.0%.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('7424c66c-e1d1-4b05-b67f-f2722fce1409'::uuid, 5, '7424c66c-e1d1-4b05-b67f-f2722fce1409', 'Telescope Exposure Trials', '{"type":"scatter_plot","context":"An observatory tested eight image exposures. Each labelled point shows exposure time and the number of faint objects detected in that image.","data":{"title":"Exposure Time and Faint Objects Detected","xAxisLabel":"Exposure time (minutes)","yAxisLabel":"Objects detected","series":[{"name":"Exposure trials","points":[{"x":10,"y":18,"label":"A"},{"x":15,"y":24,"label":"B"},{"x":20,"y":29,"label":"C"},{"x":25,"y":35,"label":"D"},{"x":30,"y":38,"label":"E"},{"x":35,"y":46,"label":"F"},{"x":40,"y":44,"label":"G"},{"x":45,"y":55,"label":"H"}]}]}}'::jsonb, 5);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('6dab5ff7-12fb-4f44-81bc-b06bc7a422ca'::uuid, '7424c66c-e1d1-4b05-b67f-f2722fce1409'::uuid, '6dab5ff7-12fb-4f44-81bc-b06bc7a422ca', 'How many objects were detected in the 35-minute exposure?', '[{"label":"A","text":"35"},{"label":"B","text":"38"},{"label":"C","text":"44"},{"label":"D","text":"46"},{"label":"E","text":"55"}]'::jsonb, 'D', 'The point with an exposure time of 35 minutes is F, whose y-value is 46 objects. The answer is 46.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('48529b87-35de-45b0-b778-62bd80e4d2f2'::uuid, '7424c66c-e1d1-4b05-b67f-f2722fce1409'::uuid, '48529b87-35de-45b0-b778-62bd80e4d2f2', 'Which labelled exposure detected the greatest number of objects per minute?', '[{"label":"A","text":"A"},{"label":"B","text":"B"},{"label":"C","text":"D"},{"label":"D","text":"F"},{"label":"E","text":"H"}]'::jsonb, 'A', 'Objects per minute are A: 18 ÷ 10 = 1.8; B: 24 ÷ 15 = 1.6; D: 35 ÷ 25 = 1.4; F: 46 ÷ 35 = 1.31; H: 55 ÷ 45 = 1.22. The greatest rate is 1.8 objects per minute at A. The answer is A.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('92a5a40e-179d-426e-a85a-a1ec243c1b4c'::uuid, '7424c66c-e1d1-4b05-b67f-f2722fce1409'::uuid, '92a5a40e-179d-426e-a85a-a1ec243c1b4c', 'Among exposures lasting at least 25 minutes, which also detected at least 1.3 objects per minute? What is the total number of objects detected by those qualifying exposures?', '[{"label":"A","text":"73"},{"label":"B","text":"79"},{"label":"C","text":"81"},{"label":"D","text":"90"},{"label":"E","text":"136"}]'::jsonb, 'C', 'For exposures of at least 25 minutes, the rates are D: 35 ÷ 25 = 1.40, E: 38 ÷ 30 = 1.27, F: 46 ÷ 35 = 1.31, G: 44 ÷ 40 = 1.10 and H: 55 ÷ 45 = 1.22 objects per minute. Only D and F meet at least 1.3, giving 35 + 46 = 81 objects. The answer is 81.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('71bff59d-3a6f-47cf-80b5-0cc6f26d1cae'::uuid, 5, '71bff59d-3a6f-47cf-80b5-0cc6f26d1cae', 'Marine Inspection Drone Routes', '{"type":"network_diagram","context":"An inspection drone can travel along the links shown. Edge labels give one-way flight times in minutes, and links can be used in either direction.","data":{"title":"Drone Flight Times Between Inspection Points","nodes":[{"id":"base","label":"Base","x":0.1,"y":0.45},{"id":"reef","label":"Reef","x":0.32,"y":0.18},{"id":"buoy","label":"Buoy","x":0.34,"y":0.72},{"id":"tower","label":"Tower","x":0.58,"y":0.3},{"id":"cove","label":"Cove","x":0.62,"y":0.78},{"id":"rig","label":"Rig","x":0.88,"y":0.52}],"edges":[{"from":"base","to":"reef","label":"14 min"},{"from":"base","to":"buoy","label":"20 min"},{"from":"reef","to":"tower","label":"16 min"},{"from":"buoy","to":"tower","label":"8 min"},{"from":"buoy","to":"cove","label":"12 min"},{"from":"tower","to":"rig","label":"18 min"},{"from":"cove","to":"rig","label":"11 min"},{"from":"reef","to":"cove","label":"25 min"}]}}'::jsonb, 6);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('a8cbb443-7e21-45d6-b058-7ae2ba1331fa'::uuid, '71bff59d-3a6f-47cf-80b5-0cc6f26d1cae'::uuid, 'a8cbb443-7e21-45d6-b058-7ae2ba1331fa', 'How long is the direct flight from Buoy to Tower?', '[{"label":"A","text":"8 minutes"},{"label":"B","text":"11 minutes"},{"label":"C","text":"12 minutes"},{"label":"D","text":"16 minutes"},{"label":"E","text":"20 minutes"}]'::jsonb, 'A', 'The direct edge between Buoy and Tower is labelled 8 minutes. The answer is 8 minutes.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('2c2e03db-e253-4e17-8a36-8b8099a1c02c'::uuid, '71bff59d-3a6f-47cf-80b5-0cc6f26d1cae'::uuid, '2c2e03db-e253-4e17-8a36-8b8099a1c02c', 'What is the shortest flight time from Base to Tower?', '[{"label":"A","text":"22 minutes"},{"label":"B","text":"28 minutes"},{"label":"C","text":"30 minutes"},{"label":"D","text":"34 minutes"},{"label":"E","text":"38 minutes"}]'::jsonb, 'B', 'Via Buoy, the time is 20 + 8 = 28 minutes. Via Reef, it is 14 + 16 = 30 minutes, and other routes are longer. The shortest flight time is 28 minutes.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('4887b62d-6932-40d5-a6d1-14e245662abf'::uuid, '71bff59d-3a6f-47cf-80b5-0cc6f26d1cae'::uuid, '4887b62d-6932-40d5-a6d1-14e245662abf', 'The drone flies from Base to Rig by the quickest route, performs an inspection using 8 kWh, and returns to Base along the same route. Flying uses 0.6 kWh per minute. How much energy does the complete mission use?', '[{"label":"A","text":"51.6 kWh"},{"label":"B","text":"55.8 kWh"},{"label":"C","text":"59.6 kWh"},{"label":"D","text":"63.2 kWh"},{"label":"E","text":"67.6 kWh"}]'::jsonb, 'C', 'The quickest Base-to-Rig route is Base–Buoy–Cove–Rig: 20 + 12 + 11 = 43 minutes. A return along the same route makes 86 flight minutes. Flight energy = 86 × 0.6 = 51.6 kWh; adding 8 kWh for inspection gives 59.6 kWh. The answer is 59.6 kWh.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('9a400fc4-1ab9-4083-a336-b0cbb2a48b20'::uuid, 5, '9a400fc4-1ab9-4083-a336-b0cbb2a48b20', 'Trapezoidal Solar Test Panel', '{"type":"geometry_diagram","context":"The panel is a trapezium. Its parallel sides are 8 m and 12 m, its perpendicular height is 5 m, and each sloping side is 5.4 m.","data":{"title":"Solar Test Panel (not to scale)","viewBox":{"width":300,"height":210},"shapes":[{"type":"polygon","points":[[70,45],[230,45],[270,155],[30,155]],"fill":"none","stroke":"#2d3748"}],"dimensions":[{"from":[70,28],"to":[230,28],"label":"8 m","side":"top"},{"from":[30,178],"to":[270,178],"label":"12 m","side":"bottom"},{"from":[150,45],"to":[150,155],"label":"5 m","side":"right"},{"from":[30,155],"to":[70,45],"label":"5.4 m","side":"left"},{"from":[230,45],"to":[270,155],"label":"5.4 m","side":"right"}]}}'::jsonb, 7);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('9c8ab0cf-c9b3-4706-ba7a-b5666c678806'::uuid, '9a400fc4-1ab9-4083-a336-b0cbb2a48b20'::uuid, '9c8ab0cf-c9b3-4706-ba7a-b5666c678806', 'What is the area of the panel?', '[{"label":"A","text":"40 m²"},{"label":"B","text":"45 m²"},{"label":"C","text":"50 m²"},{"label":"D","text":"60 m²"},{"label":"E","text":"100 m²"}]'::jsonb, 'C', 'Area of a trapezium = ½ × (sum of parallel sides) × perpendicular height. Therefore, area = ½ × (8 + 12) × 5 = 50 m². The answer is 50 m².', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('3679d80c-68ce-49de-855e-807eb87d25cf'::uuid, '9a400fc4-1ab9-4083-a336-b0cbb2a48b20'::uuid, '3679d80c-68ce-49de-855e-807eb87d25cf', 'What is the perimeter of the panel?', '[{"label":"A","text":"25.4 m"},{"label":"B","text":"28.0 m"},{"label":"C","text":"30.8 m"},{"label":"D","text":"33.4 m"},{"label":"E","text":"35.8 m"}]'::jsonb, 'C', 'Perimeter = 8 + 12 + 5.4 + 5.4 = 30.8 m. The answer is 30.8 m.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('ef456bbd-f649-4973-8582-d9b0701545e7'::uuid, '9a400fc4-1ab9-4083-a336-b0cbb2a48b20'::uuid, 'ef456bbd-f649-4973-8582-d9b0701545e7', 'A scale model uses a length scale of 1:25. What is the area of the model panel in cm²?', '[{"label":"A","text":"80 cm²"},{"label":"B","text":"200 cm²"},{"label":"C","text":"500 cm²"},{"label":"D","text":"800 cm²"},{"label":"E","text":"2,000 cm²"}]'::jsonb, 'D', 'The real area is 50 m² = 500,000 cm². A 1:25 length scale gives an area scale of 1:25² = 1:625. Model area = 500,000 ÷ 625 = 800 cm². The answer is 800 cm².', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('013e9928-a525-422a-befa-a400615c4545'::uuid, 5, '013e9928-a525-422a-befa-a400615c4545', 'Orchard Imaging Mission', '{"type":"text","text":"A mapping drone must image a 54-hectare orchard. One battery covers 9 hectares during a 24-minute flight. Changing a battery takes 6 minutes between flights. Imaging produces 1.8 GB per hectare before compression; compression reduces the data to 40% of its original size. The upload connection transfers 12 GB per hour."}'::jsonb, 8);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('91e58952-653a-48d8-9e63-19c58953a54f'::uuid, '013e9928-a525-422a-befa-a400615c4545'::uuid, '91e58952-653a-48d8-9e63-19c58953a54f', 'How many battery flights are required to image the whole orchard?', '[{"label":"A","text":"4"},{"label":"B","text":"5"},{"label":"C","text":"6"},{"label":"D","text":"7"},{"label":"E","text":"8"}]'::jsonb, 'C', 'Flights required = 54 hectares ÷ 9 hectares per flight = 6 flights. The answer is 6.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('d36f4cbd-2c13-452f-a257-07d396f3b31d'::uuid, '013e9928-a525-422a-befa-a400615c4545'::uuid, 'd36f4cbd-2c13-452f-a257-07d396f3b31d', 'How long will the six flights and the battery changes between them take in total?', '[{"label":"A","text":"2 hours 24 minutes"},{"label":"B","text":"2 hours 42 minutes"},{"label":"C","text":"2 hours 54 minutes"},{"label":"D","text":"3 hours"},{"label":"E","text":"3 hours 6 minutes"}]'::jsonb, 'C', 'Six flights take 6 × 24 = 144 minutes. There are five changes between six flights, taking 5 × 6 = 30 minutes. Total = 174 minutes = 2 hours 54 minutes. The answer is 2 hours 54 minutes.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('44bc31be-a226-4121-aa51-9534c1113c6a'::uuid, '013e9928-a525-422a-befa-a400615c4545'::uuid, '44bc31be-a226-4121-aa51-9534c1113c6a', 'How long will the compressed data take to upload, to the nearest minute?', '[{"label":"A","text":"2 hours 42 minutes"},{"label":"B","text":"3 hours"},{"label":"C","text":"3 hours 14 minutes"},{"label":"D","text":"3 hours 24 minutes"},{"label":"E","text":"8 hours 6 minutes"}]'::jsonb, 'C', 'Original data = 54 × 1.8 = 97.2 GB. Compressed data = 97.2 × 0.40 = 38.88 GB. Upload time = 38.88 ÷ 12 = 3.24 hours = 3 hours 14.4 minutes, which rounds to 3 hours 14 minutes. The answer is 3 hours 14 minutes.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('ee53384c-cf78-4cff-94eb-25fe2996044c'::uuid, 5, 'ee53384c-cf78-4cff-94eb-25fe2996044c', 'Pottery Glaze Batch', '{"type":"text","text":"A pottery studio makes a dry glaze mixture using 5 parts silica, 3 parts clay and 2 parts pigment by mass. A batch contains 36 kg of dry mixture. During preparation, 8% of the mixture is wasted. Each finished piece uses 0.69 kg of the remaining mixture. Silica costs £1.20 per kg, clay £0.80 per kg and pigment £3.50 per kg."}'::jsonb, 9);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('02eca746-b90e-4995-9f39-682d4c8718bc'::uuid, 'ee53384c-cf78-4cff-94eb-25fe2996044c'::uuid, '02eca746-b90e-4995-9f39-682d4c8718bc', 'How much pigment is in the 36 kg dry batch?', '[{"label":"A","text":"3.6 kg"},{"label":"B","text":"5.4 kg"},{"label":"C","text":"7.2 kg"},{"label":"D","text":"9.0 kg"},{"label":"E","text":"10.8 kg"}]'::jsonb, 'C', 'There are 5 + 3 + 2 = 10 total parts, of which 2 are pigment. Pigment mass = 36 × 2 ÷ 10 = 7.2 kg. The answer is 7.2 kg.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('7b2de1ca-4e19-4c3c-9067-4c17ff6edbc3'::uuid, 'ee53384c-cf78-4cff-94eb-25fe2996044c'::uuid, '7b2de1ca-4e19-4c3c-9067-4c17ff6edbc3', 'What is the maximum number of finished pieces that can be glazed after the 8% preparation waste?', '[{"label":"A","text":"44"},{"label":"B","text":"46"},{"label":"C","text":"48"},{"label":"D","text":"50"},{"label":"E","text":"52"}]'::jsonb, 'C', 'Remaining mixture = 36 × 0.92 = 33.12 kg. Number of pieces = 33.12 ÷ 0.69 = 48 exactly. The answer is 48 pieces.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('6dcaa8bd-9b63-42b2-a39f-038dd05c77fb'::uuid, 'ee53384c-cf78-4cff-94eb-25fe2996044c'::uuid, '6dcaa8bd-9b63-42b2-a39f-038dd05c77fb', 'What is the ingredient cost of the full 36 kg dry batch?', '[{"label":"A","text":"£47.52"},{"label":"B","text":"£52.20"},{"label":"C","text":"£55.44"},{"label":"D","text":"£58.68"},{"label":"E","text":"£63.00"}]'::jsonb, 'C', 'The batch contains 18 kg silica, 10.8 kg clay and 7.2 kg pigment. Cost = 18 × £1.20 + 10.8 × £0.80 + 7.2 × £3.50 = £21.60 + £8.64 + £25.20 = £55.44. The answer is £55.44.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('30a0e16c-14af-4559-9738-b0185fee7eea'::uuid, 5, '30a0e16c-14af-4559-9738-b0185fee7eea', 'Cold-Chain Crate Freight', '{"type":"multi","items":[{"type":"text","text":"A carrier charges freight using the greater of each crate''s actual mass and volumetric mass. The shipment also has one £42 handling fee."},{"type":"formula","text":"Volumetric mass (kg) = length (cm) × width (cm) × height (cm) ÷ 5,000"},{"type":"table","context":"Crate sizes, actual masses and quantities are shown below.","data":{"headers":["Crate type","Dimensions (cm)","Actual mass per crate","Number of crates"],"rows":[["Culture kit","40 × 30 × 25","7.2 kg","12"],["Reagent pack","50 × 40 × 30","9.5 kg","8"],["Sensor case","60 × 35 × 25","11.0 kg","10"]]}}]}'::jsonb, 10);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('d6acab21-fec3-44d5-9ddc-112d30949b75'::uuid, '30a0e16c-14af-4559-9738-b0185fee7eea'::uuid, 'd6acab21-fec3-44d5-9ddc-112d30949b75', 'What billable mass is used for one Reagent pack crate?', '[{"label":"A","text":"9.5 kg"},{"label":"B","text":"10.0 kg"},{"label":"C","text":"11.0 kg"},{"label":"D","text":"12.0 kg"},{"label":"E","text":"15.0 kg"}]'::jsonb, 'D', 'The volumetric mass is 50 × 40 × 30 ÷ 5,000 = 12 kg. This is greater than the 9.5 kg actual mass, so the billable mass is 12.0 kg. The answer is 12.0 kg.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('54371b97-73d1-476f-8568-fdfdbe1fb064'::uuid, '30a0e16c-14af-4559-9738-b0185fee7eea'::uuid, '54371b97-73d1-476f-8568-fdfdbe1fb064', 'What is the total billable mass of all 30 crates?', '[{"label":"A","text":"273.4 kg"},{"label":"B","text":"282.0 kg"},{"label":"C","text":"292.4 kg"},{"label":"D","text":"302.0 kg"},{"label":"E","text":"316.4 kg"}]'::jsonb, 'C', 'Culture kits have volumetric mass 6 kg, so use actual mass: 12 × 7.2 = 86.4 kg. Reagent packs use volumetric mass: 8 × 12 = 96 kg. Sensor cases have volumetric mass 10.5 kg, so use actual mass: 10 × 11 = 110 kg. Total = 86.4 + 96 + 110 = 292.4 kg. The answer is 292.4 kg.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('a72bc8e6-5710-4a59-95bf-b438a9f7d6c9'::uuid, '30a0e16c-14af-4559-9738-b0185fee7eea'::uuid, 'a72bc8e6-5710-4a59-95bf-b438a9f7d6c9', 'Freight costs £1.85 per billable kilogram. What is the total charge including the handling fee?', '[{"label":"A","text":"£540.94"},{"label":"B","text":"£562.94"},{"label":"C","text":"£582.94"},{"label":"D","text":"£598.40"},{"label":"E","text":"£625.94"}]'::jsonb, 'C', 'The total billable mass is 292.4 kg. Freight costs 292.4 × £1.85 = £540.94. Adding the £42 handling fee gives £582.94. The answer is £582.94.', 2);
INSERT INTO timed_quantitative_reasoning_sets (id, test_id, set_ref, title, stimulus, order_index) VALUES ('77aa1d04-6f9c-48be-99b8-a4578f48cda8'::uuid, 5, '77aa1d04-6f9c-48be-99b8-a4578f48cda8', 'Radio Telescope Project Schedule', '{"type":"multi","items":[{"type":"text","text":"A radio telescope records data only during completed observing hours. An identical backup copy of all recorded data is required. Storage may be pooled across all purchased drives; original files and their backup copies do not need to occupy disjoint drives. Use 1 TB = 1,000 GB."},{"type":"formula","text":"Completed hours = requested hours × completion percentage"},{"type":"table","context":"The table summarises four fictional observing projects.","data":{"headers":["Project","Requested hours","Completion","Data per completed hour"],"rows":[["Aurora","48","75%","18 GB"],["Pulsar","60","80%","15 GB"],["Quasar","40","90%","24 GB"],["Galaxy","72","62.5%","12 GB"]]}}]}'::jsonb, 11);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('b68666e4-9ab4-48f2-9868-3558f5241c8c'::uuid, '77aa1d04-6f9c-48be-99b8-a4578f48cda8'::uuid, 'b68666e4-9ab4-48f2-9868-3558f5241c8c', 'How many observing hours were completed for the Quasar project?', '[{"label":"A","text":"30 hours"},{"label":"B","text":"32 hours"},{"label":"C","text":"36 hours"},{"label":"D","text":"38 hours"},{"label":"E","text":"40 hours"}]'::jsonb, 'C', 'Completed Quasar hours = 40 × 0.90 = 36 hours. The answer is 36 hours.', 0);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('ef51a260-d7c9-41cc-b91a-b409b5cba3d8'::uuid, '77aa1d04-6f9c-48be-99b8-a4578f48cda8'::uuid, 'ef51a260-d7c9-41cc-b91a-b409b5cba3d8', 'How many observing hours were completed across all four projects?', '[{"label":"A","text":"153 hours"},{"label":"B","text":"159 hours"},{"label":"C","text":"165 hours"},{"label":"D","text":"171 hours"},{"label":"E","text":"180 hours"}]'::jsonb, 'C', 'Completed hours are Aurora 48 × 75% = 36, Pulsar 60 × 80% = 48, Quasar 40 × 90% = 36, and Galaxy 72 × 62.5% = 45. Total = 36 + 48 + 36 + 45 = 165 hours. The answer is 165 hours.', 1);
INSERT INTO timed_quantitative_reasoning_questions (id, set_id, question_ref, stem, options, correct_answer, answer_reason, order_index) VALUES ('4be57c0b-d6b4-4835-93a2-64aa7091ae55'::uuid, '77aa1d04-6f9c-48be-99b8-a4578f48cda8'::uuid, '4be57c0b-d6b4-4835-93a2-64aa7091ae55', 'Assuming files may be distributed across all purchased drives and only their combined storage capacity matters, how many 2 TB drives are needed to hold all recorded data and one additional copy?', '[{"label":"A","text":"1 drive"},{"label":"B","text":"2 drives"},{"label":"C","text":"3 drives"},{"label":"D","text":"4 drives"},{"label":"E","text":"5 drives"}]'::jsonb, 'C', 'Recorded data are Aurora 36 × 18 = 648 GB, Pulsar 48 × 15 = 720 GB, Quasar 36 × 24 = 864 GB, and Galaxy 45 × 12 = 540 GB. Total = 2,772 GB. Including an identical backup requires 5,544 GB. Each drive holds 2,000 GB, so 5,544 ÷ 2,000 = 2.772 and 3 whole drives are required. The answer is 3 drives.', 2);
INSERT INTO timed_situational_judgement_tests (id, title, time_minutes) VALUES (5, 'SJ Timed Test 1', 26);
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('8b31b320-9b27-4fa4-b9c0-4a7ec87d38d0'::uuid, 5, 'A patient has been diagnosed with a sexually transmitted infection (STI) but is reluctant to tell their sexual partner. The patient is worried about the impact this may have on their relationship.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('7c526483-1ff4-4713-adef-4ba5870cb706'::uuid, '8b31b320-9b27-4fa4-b9c0-4a7ec87d38d0'::uuid, 'How important is it to address the patient''s reluctance to disclose their STI diagnosis to their partner?', 'Very important', 'This is very important because the doctor should explore the patient''s concerns, encourage honest disclosure, and consider the risk of harm to others rather than ignoring the issue.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('d5eb8968-b4ef-483e-a853-7ad5600b4b0f'::uuid, '8b31b320-9b27-4fa4-b9c0-4a7ec87d38d0'::uuid, 'How important is it to protect the patient''s privacy and confidentiality while discussing this situation?', 'Very important', 'This is very important because confidentiality remains a core duty, although it should be balanced carefully against any risk of serious harm to others and the need to support safe, honest decision-making.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('735d7639-aa83-41d9-8ca9-f90b85094b4c'::uuid, '8b31b320-9b27-4fa4-b9c0-4a7ec87d38d0'::uuid, 'The doctor tells the patient that, to avoid stress on the relationship, they can lie to their partner and conceal the STI diagnosis.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it encourages dishonesty, risks the partner''s health, and fails to support responsible and ethical behaviour.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('c5907142-718a-4192-836c-de8cd00f0691'::uuid, 5, 'You are discussing a patient''s poor prognosis with two colleagues in a hospital cafe when you notice that a relative of the patient is sitting nearby and may be able to hear the conversation.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('687f349b-a6e3-4604-acc1-1a7a18088bf5'::uuid, 'c5907142-718a-4192-836c-de8cd00f0691'::uuid, 'How important is it to address the fact that the patient''s confidential information may be overheard?', 'Very important', 'This is very important because patient information should only be discussed in appropriate settings where confidentiality can be maintained.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('bd517ba8-7930-454c-bc0f-24f91d5cf590'::uuid, 'c5907142-718a-4192-836c-de8cd00f0691'::uuid, 'You stop the conversation, suggest moving somewhere private, and later remind your colleagues to be more careful about discussing confidential information in public areas.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it protects confidentiality immediately and addresses the behaviour proportionately without escalating further than necessary.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('9e852db5-b8eb-41e0-88fc-ba667356b169'::uuid, 'c5907142-718a-4192-836c-de8cd00f0691'::uuid, 'You ignore the relative''s presence and continue discussing the patient with your colleagues.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it risks a serious breach of confidentiality and shows poor professional judgement.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('36b553a2-fd0a-40db-b311-43bb9ca3f5cf'::uuid, 5, 'Dr. Katherine Johnson is consulting with Mr. Michael Smith, who has been advised to start a recommended treatment. Mr. Smith is worried about side effects and is unsure whether he wants to go ahead.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('02833eb9-2fcb-4736-b3a9-479c95e9f5fa'::uuid, '36b553a2-fd0a-40db-b311-43bb9ca3f5cf'::uuid, 'How important is it to discuss Mr. Smith''s worries and concerns about the proposed treatment?', 'Very important', 'This is very important because good decision-making depends on understanding the patient''s concerns and responding to them respectfully.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('6e5775b5-1901-4b83-a512-c5288c1dab18'::uuid, '36b553a2-fd0a-40db-b311-43bb9ca3f5cf'::uuid, 'How important is it to inform Mr. Smith about the potential benefits, risks, and consequences of refusing the recommended treatment?', 'Very important', 'This is very important because patients need clear and balanced information in order to make an informed decision about their care.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('41cec6a3-649d-4bc8-87ef-b36ad9c5d940'::uuid, '36b553a2-fd0a-40db-b311-43bb9ca3f5cf'::uuid, 'You tell Mr. Smith that he must take the medication regardless of his concerns.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it is coercive, dismisses the patient''s autonomy, and does not support informed consent.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('30a3a434-404b-4ffe-a1d8-58d531de9987'::uuid, 5, 'Dr. Olivia Davis is part of a team caring for an elderly patient, Mr. Robert Wilson. The team believes that further treatment is unlikely to help and may cause harm, but Mr. Wilson strongly wishes to explore all reasonable options.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('b40b27c9-2024-4924-8a5e-9e756fb6b2d9'::uuid, '30a3a434-404b-4ffe-a1d8-58d531de9987'::uuid, 'How important is it to have an open and honest discussion with Mr. Wilson about the likely benefits and burdens of further treatment?', 'Very important', 'This is very important because the patient should be given honest information and involved properly in decisions about their care.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('37ff71dc-43b7-4e1e-af1d-6cf6000bcd20'::uuid, '30a3a434-404b-4ffe-a1d8-58d531de9987'::uuid, 'How important is it to consider seeking a second opinion or senior review if uncertainty or disagreement remains after discussion?', 'Important', 'This is important because a second opinion can be helpful when there is uncertainty or disagreement, but it is not automatically the first or only priority in every case.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('0f35d7b1-9ab5-4b16-abf5-f16452be4345'::uuid, '30a3a434-404b-4ffe-a1d8-58d531de9987'::uuid, 'Dr. Olivia Davis dismisses Mr. Wilson''s wish for further treatment without discussing his concerns or explaining the reasoning.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it is dismissive, undermines shared decision-making, and fails to respect the patient''s perspective.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('b57e9b31-5d20-4d78-88de-9897c3095c3a'::uuid, 5, 'A medical student, Alex Mitchell, is observing Dr. Olivia Turner on a ward round. Alex notices from the notes that the patient, Mr. Smith, has a documented penicillin allergy just as Dr. Turner begins prescribing antibiotics.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('5ab8c3bb-a95e-42f0-81f0-385cb2ee1585'::uuid, 'b57e9b31-5d20-4d78-88de-9897c3095c3a'::uuid, 'How important is it to make sure Mr. Smith''s penicillin allergy is raised before the prescription is completed?', 'Very important', 'This is very important because preventing avoidable patient harm must be a priority.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('ba165101-f4fe-47b5-aeb0-205e602a12b8'::uuid, 'b57e9b31-5d20-4d78-88de-9897c3095c3a'::uuid, 'How important is it to tell Dr. Turner promptly and, if possible, do so in a professional way that does not cause unnecessary embarrassment?', 'Very important', 'This is very important because the concern should be raised immediately, while still aiming to communicate respectfully and effectively.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('57533cb3-4686-41b7-9298-acf53a905d20'::uuid, 'b57e9b31-5d20-4d78-88de-9897c3095c3a'::uuid, 'Alex ignores the allergy information and says nothing because Dr. Turner is the senior doctor.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because hierarchy should not prevent someone from raising a clear patient safety concern.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('3043f5d2-5776-46dc-affc-fd3890188fa7'::uuid, 5, 'Dr. Olivia Williams is at a social gathering with friends, including Dr. Ethan Turner. During the evening, Dr. Turner makes an offensive joke about a colleague from a minority background.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('92250f76-8d2e-423e-a889-a64a1aa332b0'::uuid, '3043f5d2-5776-46dc-affc-fd3890188fa7'::uuid, 'How important is it to address Dr. Turner''s offensive joke rather than simply letting it pass?', 'Very important', 'This is very important because discriminatory behaviour should be challenged rather than normalised, and addressing it in the moment — even if briefly or imperfectly — sets a clear boundary and signals that such remarks are unacceptable. GMC Good Medical Practice requires doctors to treat colleagues with respect and to challenge behaviour that falls below this standard. Failing to respond at all risks endorsing the behaviour by omission.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('d0b9f6e3-9041-4e20-83f4-2dcd9ee7dc25'::uuid, '3043f5d2-5776-46dc-affc-fd3890188fa7'::uuid, 'How important is it to speak with Dr. Turner privately afterwards if addressing it in the moment is not the best option?', 'Very important', 'This is very important because a private follow-up is often an effective and proportionate way to challenge unacceptable behaviour.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('18618192-0094-46bc-9dbf-2a0b283c09bb'::uuid, '3043f5d2-5776-46dc-affc-fd3890188fa7'::uuid, 'You respond to Dr. Turner''s offensive joke with laughter or by making similar remarks.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it endorses the behaviour and contributes to an unprofessional and disrespectful culture.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('fcbc2988-af49-43b0-a1e9-ed9ed24d533e'::uuid, 5, 'Dr. Katherine Davis is a junior doctor in a very busy emergency department. A patient with severe breathing difficulty has just been moved into a resuscitation bay, and the senior doctor asks Dr. Davis to help while the senior leads the immediate treatment.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('0e2bac73-6113-4081-af46-f48a5fe45f1a'::uuid, 'fcbc2988-af49-43b0-a1e9-ed9ed24d533e'::uuid, 'How important is it for Dr. Davis to help within her level of competence, for example by gathering notes, equipment, or observations rather than attempting tasks she is not trained to do?', 'Very important', 'This is very important because junior staff should contribute in emergencies, but always within the limits of their competence so that patient safety is protected.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('35c22ced-fd2c-4c6b-a73a-931ba5ae7cdc'::uuid, 'fcbc2988-af49-43b0-a1e9-ed9ed24d533e'::uuid, 'How important is it to communicate any relevant history, allergies, or recent observations to the senior doctor promptly?', 'Very important', 'This is very important because clear communication of key information can directly affect safe decision-making in an emergency.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('93a05c79-521f-4849-a682-a234b02c3db6'::uuid, 'fcbc2988-af49-43b0-a1e9-ed9ed24d533e'::uuid, 'How important is it to take part in a brief debrief afterwards to reflect on what went well and what could be improved?', 'Important', 'This is important because debriefing supports learning and safer teamwork, although it is not as immediately urgent as the patient''s care during the emergency itself.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('32c08c89-a57a-44f2-8bc8-be12a9c729fb'::uuid, 5, 'A medical student, John Mitchell, is on placement in the internal medicine department when he hears Dr. Turner say that he does not want to treat a particular patient because he finds them difficult and annoying.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('0531e214-beb4-43e0-8591-8d67aa493b66'::uuid, '32c08c89-a57a-44f2-8bc8-be12a9c729fb'::uuid, 'How important is it to address Dr. Turner''s statement and ensure the patient is not denied appropriate care?', 'Very important', 'This is very important because patients must not be disadvantaged because of a clinician''s personal feelings.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('40dae127-2db3-4f29-98f2-a31a6c72398b'::uuid, '32c08c89-a57a-44f2-8bc8-be12a9c729fb'::uuid, 'How important is it to report the statement to a supervisor or another appropriate senior if the patient may be put at risk?', 'Very important', 'This is very important because a refusal to provide care for improper reasons is a serious professionalism and patient safety concern.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('eef158b7-269c-464a-bac4-2b6c34d56ad9'::uuid, '32c08c89-a57a-44f2-8bc8-be12a9c729fb'::uuid, 'John ignores the statement and does not raise it with anyone.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it fails to act on a potentially serious concern about patient care.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('ef3a5f71-bde3-46cd-8afc-41ae2ff5d1a5'::uuid, 5, 'You are working on a busy ward and notice that Dr. Davis has been on shift for a prolonged period, appears exhausted, and is starting to forget details and lose concentration.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('20f0ee4c-13ee-4171-aa6a-40e47b832aee'::uuid, 'ef3a5f71-bde3-46cd-8afc-41ae2ff5d1a5'::uuid, 'How important is it to address Dr. Davis''s exhaustion and its possible impact on patient safety?', 'Very important', 'This is very important because fatigue can impair judgement and performance and may put patients at risk.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('6409b70d-0968-4053-a810-11f456d603a1'::uuid, 'ef3a5f71-bde3-46cd-8afc-41ae2ff5d1a5'::uuid, 'How important is it to encourage Dr. Davis to take a break or seek support so she can work safely?', 'Very important', 'This is very important because offering practical support is an appropriate first step when a colleague is struggling.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('dfd4cc65-31f8-4b4a-ba1f-27042ebeec90'::uuid, 'ef3a5f71-bde3-46cd-8afc-41ae2ff5d1a5'::uuid, 'How important is it to inform a senior if Dr. Davis remains too fatigued to work safely or refuses to take action?', 'Very important', 'This is very important because concerns that may affect patient safety should be escalated when they cannot be resolved directly.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('e9968850-3ac3-4949-9733-ad2b09ad09d4'::uuid, 5, 'Dr. Olivia is examining a baby in the paediatrics department when the baby''s mother becomes very distressed and says she does not want anyone else to examine her child.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('df269aec-b6bc-4191-8a43-16798da3d4cc'::uuid, 'e9968850-3ac3-4949-9733-ad2b09ad09d4'::uuid, 'How important is it to address the mother''s distress and reluctance to allow the examination?', 'Very important', 'This is very important because the mother''s distress may affect the child''s care and must be handled sensitively.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('f1246b4f-da45-4b4d-975b-3729b594c415'::uuid, 'e9968850-3ac3-4949-9733-ad2b09ad09d4'::uuid, 'How important is it to communicate calmly and empathetically, explaining why the examination is needed and listening to the mother''s concerns?', 'Very important', 'This is very important because clear and compassionate communication is central to building trust and supporting informed decisions.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('98ca6e1c-2ad6-4257-9b84-c8051c291316'::uuid, 'e9968850-3ac3-4949-9733-ad2b09ad09d4'::uuid, 'How important is it to involve a nurse or another appropriate colleague to help support and reassure the mother if needed?', 'Important', 'This is important because extra support may help de-escalate the situation, although the immediate priority remains calm communication with the mother.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('5a66411c-8abe-414f-8d2f-9aef2e9c237e'::uuid, 5, 'Alex Johnson is a surgical trainee. Over several weeks, a senior doctor has made repeated sexually suggestive comments towards Alex in the workplace, leaving Alex uncomfortable and distracted.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('f2c32994-85dc-40df-9d91-c812ad39fc36'::uuid, '5a66411c-8abe-414f-8d2f-9aef2e9c237e'::uuid, 'Alex Johnson documents the incidents and reports them through appropriate hospital channels, seeking support from a supervisor, educational lead, or HR.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because repeated sexual comments are unacceptable, and using proper reporting and support channels is a sensible and professional response.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('68b2961b-40bb-49e7-8a07-31447e4f534b'::uuid, '5a66411c-8abe-414f-8d2f-9aef2e9c237e'::uuid, 'Alex Johnson continues to ignore the comments and tries to focus only on work.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because the reaction may be understandable in a difficult power imbalance, but it still fails to address repeated unacceptable behaviour.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('1044d11c-7a71-4552-b18e-a7a233dd3574'::uuid, '5a66411c-8abe-414f-8d2f-9aef2e9c237e'::uuid, 'Alex Johnson confronts Dr. Davis publicly in the middle of the workplace to make it clear that the comments are unacceptable.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because, while the impulse to challenge the behaviour is understandable, doing so publicly in a workplace setting during a power-imbalance situation is likely to be counterproductive. It risks embarrassing both parties, triggering retaliation, and undermining any formal process that may follow. It is better than doing nothing, which is why it does not reach ''A very inappropriate thing to do'', but it falls short of any threshold of appropriateness when more effective and safer channels are available.', 2, 2, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('6901dc38-2304-4e01-bfe7-3085d7ef83e9'::uuid, 5, 'John, a medical student on ward rounds, overhears two doctors criticising their consultant in front of a patient and making comments that could undermine the patient''s confidence in the team.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('79a47698-8f8f-4f50-a3c9-6934c18f643e'::uuid, '6901dc38-2304-4e01-bfe7-3085d7ef83e9'::uuid, 'How important is it to approach the doctors privately and address the issue?', 'Very important', 'This is very important because the behaviour is unprofessional and should be challenged in a proportionate way.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('2a1ef13c-06ad-477a-a38b-22f5f2a2c49f'::uuid, '6901dc38-2304-4e01-bfe7-3085d7ef83e9'::uuid, 'Do nothing and allow the situation to resolve itself.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it allows unprofessional behaviour to continue and may damage the patient''s trust in the team.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('7057fc28-926c-427e-99bc-86d37f58299b'::uuid, '6901dc38-2304-4e01-bfe7-3085d7ef83e9'::uuid, 'How important is it to inform a supervising consultant or another senior if the behaviour is serious, repeated, or has clearly affected the patient?', 'Important', 'This is important because escalation may be needed when the concern is serious or cannot be resolved directly, but a private challenge is often the proportionate first step.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('680ece7c-c387-405a-8328-fe31a55acef0'::uuid, 5, 'Dr. Emily Rodriguez, a foundation year doctor, is helping manage a stable but urgent case in the emergency department when a nurse alerts her that another patient nearby has suddenly become acutely short of breath and needs immediate attention.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('1570f5d0-53b9-4f3e-910a-e12dbee62c91'::uuid, '680ece7c-c387-405a-8328-fe31a55acef0'::uuid, 'How important is it to alert a senior or another available clinician immediately so the deteriorating patient is not left waiting?', 'Very important', 'This is very important because a potentially deteriorating patient requires prompt attention, even if you are already busy.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('1f12edca-07e4-4250-83f7-0673ba90d488'::uuid, '680ece7c-c387-405a-8328-fe31a55acef0'::uuid, 'Dr. Rodriguez immediately alerts a nearby senior clinician and follows instructions so that the short of breath patient is assessed without delay.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it prioritises the unwell patient quickly while making sensible use of team support.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('109927cb-7efd-4322-abc5-e9a18af5cff2'::uuid, '680ece7c-c387-405a-8328-fe31a55acef0'::uuid, 'Dr. Rodriguez decides to take a short break first and deal with the short of breath patient afterwards.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it delays attention to a potentially urgent patient for no good reason.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('7e194396-91fc-4b61-9899-d4cdf49931c0'::uuid, 5, 'Dr. James Patel, a junior trainee in theatre, notices that the swab count may be incorrect during an operation and is not sure whether all items used during the procedure have been accounted for.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('7326903f-f6bf-4c10-a576-37cdef9e01a8'::uuid, '7e194396-91fc-4b61-9899-d4cdf49931c0'::uuid, 'How important is it to inform the senior surgeon immediately and seek guidance?', 'Very important', 'This is very important because a possible error during an operation is a patient safety issue and should be raised without delay.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('5f105b17-2dcf-484c-88f0-4ff5202eba0d'::uuid, '7e194396-91fc-4b61-9899-d4cdf49931c0'::uuid, 'Dr. Patel immediately voices the concern and asks the team to confirm the count before the operation proceeds further.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it raises the concern promptly and helps the team address a potential safety problem before harm occurs.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('39b6005e-8401-4413-9838-ce9afc9c127e'::uuid, '7e194396-91fc-4b61-9899-d4cdf49931c0'::uuid, 'Dr. Patel says nothing and allows the operation to continue as planned, despite the possible discrepancy.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because ignoring a possible safety issue during surgery could place the patient at significant risk.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('e363e811-91ad-4c41-9e8d-ace3cc510482'::uuid, 5, 'Dr. Michael Turner, a foundation year doctor, is called to see a post-operative patient who suddenly develops severe chest pain and appears unwell.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('123037b4-0811-43a1-a2fb-29a41122fee0'::uuid, 'e363e811-91ad-4c41-9e8d-ace3cc510482'::uuid, 'Administering pain relief medication to the patient without first assessing them or seeking help.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it may mask a serious problem and delays proper assessment of an unwell patient.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('8e25dd34-089f-4361-8482-633bf94b90dd'::uuid, 'e363e811-91ad-4c41-9e8d-ace3cc510482'::uuid, 'How important is it to notify the patient''s family before the patient has been assessed?', 'Of minor importance', 'This is of minor importance at this stage because the immediate priority is to assess the patient, initiate appropriate management, and seek senior help if needed. Family notification is not the first concern and should not divert attention from the patient''s urgent needs. It is not completely without relevance in every circumstance — for example, if family are already present or there is a welfare arrangement in place — but it remains a very low priority compared to the clinical response required.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('79258dba-09f2-4272-8ffc-0841e8cd439e'::uuid, 'e363e811-91ad-4c41-9e8d-ace3cc510482'::uuid, 'Quickly assessing the patient, checking observations, and calling for senior help if needed.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because a deteriorating patient should be assessed promptly and escalated appropriately.', 2, 2, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('bf2fe56b-a8eb-4fc5-88f0-f8378c5ad67b'::uuid, 5, 'Dr. Ahmed Rahman, a foundation year doctor on the obstetrics and gynaecology ward, is asked by Mary Johnson to arrange an elective procedure immediately because it would suit her personal plans, even though there is no urgent clinical need.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('a9333900-e142-4fa0-ac56-82411c8d9a6a'::uuid, 'bf2fe56b-a8eb-4fc5-88f0-f8378c5ad67b'::uuid, 'Politely declining Mary Johnson''s request without any further discussion.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because the request may not be suitable, but simply refusing without explanation does not support good communication or shared decision-making.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('8374d7a1-be03-4753-8095-65d313f07ccc'::uuid, 'bf2fe56b-a8eb-4fc5-88f0-f8378c5ad67b'::uuid, 'Performing the requested procedure simply to accommodate the patient''s wishes, without proper assessment or senior agreement.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because decisions about procedures should be based on clinical judgement, informed discussion, and appropriate supervision.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('2f926687-0e0b-4071-8c28-5045b7de60b3'::uuid, 'bf2fe56b-a8eb-4fc5-88f0-f8378c5ad67b'::uuid, 'Engaging in a thorough discussion with Mary Johnson about the reasons for her request, explaining the options, and involving a senior clinician if needed.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it respects the patient''s concerns while ensuring decisions are made safely and appropriately.', 2, 2, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('c160e967-5a68-481e-9e54-e1bf14bc5a18'::uuid, 5, 'Dr. Emily Rodriguez, a foundation year doctor, is asked by a registrar to write up a prescription. When checking the chart, she notices that the medication may interact with another treatment the patient is already receiving.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('c27fbbb4-ba04-4e1b-9756-bfe335bdad51'::uuid, 'c160e967-5a68-481e-9e54-e1bf14bc5a18'::uuid, 'Proceeding with the prescription exactly as instructed without checking the possible interaction.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it ignores a possible patient safety risk and fails to use professional judgement.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('ed11e1b1-67de-496f-b44a-5e6510b03d3a'::uuid, 'c160e967-5a68-481e-9e54-e1bf14bc5a18'::uuid, 'How important is it to seek guidance from a senior colleague, pharmacist, or another appropriate source before the prescription is completed?', 'Very important', 'This is very important because a possible prescribing problem should be clarified before a patient is exposed to harm.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('874d78a3-f21f-4c4f-ba64-fb561a9d90e5'::uuid, 'c160e967-5a68-481e-9e54-e1bf14bc5a18'::uuid, 'Pausing the prescription and asking a senior clinician to review it before it is written up.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it escalates the concern appropriately and helps prevent a possible medication error before the patient is exposed to any risk. Pausing rather than proceeding shows sound professional judgement, and involving a senior clinician ensures the decision is made safely.', 2, 2, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('1a58e13a-4b63-4ae6-8eca-70340517950c'::uuid, 5, 'Dr. Michael Turner, a foundation year doctor at City General Hospital, notices his colleague Dr. James Patel repeatedly not following basic infection control measures on the ward.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('dcd46719-2f4b-4597-9d52-65aec0eedd58'::uuid, '1a58e13a-4b63-4ae6-8eca-70340517950c'::uuid, 'Having a private conversation with Dr. James Patel about the importance of following infection control guidance.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it addresses the concern directly, respectfully, and proportionately.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('ca742a1a-95d4-4aa1-8ebe-8960f33ab5b3'::uuid, '1a58e13a-4b63-4ae6-8eca-70340517950c'::uuid, 'How important is it to report the behaviour to a senior member of staff if it continues or poses a risk to patients?', 'Important', 'This is important because repeated or unresolved infection control breaches may need escalation, although a direct conversation is usually the first proportionate step.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('0aac6133-1854-4971-be53-b990a9069af1'::uuid, '1a58e13a-4b63-4ae6-8eca-70340517950c'::uuid, 'Ignoring the situation because it may not be significant.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because infection control concerns can affect patient safety and should not be dismissed.', 2, 2, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('cb219164-40c6-4f86-9d76-8661037e7a98'::uuid, 5, 'Dr. Michael Turner discovers that a colleague, Dr. Patel, posted public messages on social media saying he ''faked a sickie'' to go to a party on the same day he had called in sick, leaving the team short-staffed.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('4a4180bf-ea79-4775-857d-c767e5706d28'::uuid, 'cb219164-40c6-4f86-9d76-8661037e7a98'::uuid, 'Confront Dr. Patel directly and ask for an explanation before deciding what further action is needed.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because seeking clarification directly before escalating is a fair and reasonable first step, and may resolve the situation more efficiently. However, it is not the best possible response because direct confrontation about suspected dishonesty carries risks — the colleague may deny it, delete the post, or feel intimidated — and there may be good reason to involve a senior early. It is better than ignoring the situation, but falls short of the fully considered response that a more structured escalation would provide.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('1ab2aafa-b43d-4d65-ab5d-d31da2d4e9d8'::uuid, 'cb219164-40c6-4f86-9d76-8661037e7a98'::uuid, 'Report the incident to a senior member of staff immediately without first speaking to Dr. Patel.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because the issue may warrant escalation, but where possible it is usually better to clarify the facts directly first unless there is an urgent reason not to.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('c97b250f-72d5-4fdf-a98c-72b4aa4acf31'::uuid, 'cb219164-40c6-4f86-9d76-8661037e7a98'::uuid, 'Ignore the situation and continue working as usual.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because the behaviour may be dishonest and has already affected colleagues and service provision.', 2, 2, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('59954cba-b931-4e66-9440-d055730e686f'::uuid, 5, 'Dr. Emily Parker, an experienced physician, is experiencing burnout and has become increasingly overwhelmed by work demands.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('fe576395-77fe-4d06-9857-0c1ea73385b7'::uuid, '59954cba-b931-4e66-9440-d055730e686f'::uuid, 'How important is it for Dr. Parker to speak to a supervisor or trusted colleague about her burnout and explore support options?', 'Very important', 'This is very important because seeking support early can protect both the doctor''s wellbeing and patient safety.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('1e4c1656-8df7-4e40-9a9a-0ebc4ae06773'::uuid, '59954cba-b931-4e66-9440-d055730e686f'::uuid, 'Taking a leave of absence without informing the hospital or arranging appropriate cover.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because taking time off may be reasonable, but doing so without communicating properly risks disrupting patient care and colleagues.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('9cad656e-4811-4858-9da3-835eaee63ebe'::uuid, '59954cba-b931-4e66-9440-d055730e686f'::uuid, 'Continuing to work excessive hours despite feeling unable to do so safely.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because working when too unwell or exhausted can compromise patient safety and the doctor''s own wellbeing.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('553d2874-b42f-49c5-8358-f4445949c761'::uuid, 5, 'Dr. Sam Johnson, a surgeon, notices that a team member is about to enter a procedure without following hand hygiene requirements.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('d44df457-8871-4d9f-8dcb-76f89b3d158c'::uuid, '553d2874-b42f-49c5-8358-f4445949c761'::uuid, 'How important is it for Dr. Johnson to address the failure to follow hand hygiene requirements before the procedure continues?', 'Very important', 'This is very important because infection prevention is a basic patient safety requirement.', 0, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('aaf06137-bd4b-4dec-8518-e5739f355730'::uuid, '553d2874-b42f-49c5-8358-f4445949c761'::uuid, 'How important is it to remind the wider team about the importance of hand hygiene and safe practice?', 'Important', 'This is important because broader reminders can reinforce good practice, although the first priority is to address the immediate lapse.', 1, 1, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('9c124bcb-7c86-40b7-bb89-01800f12e5bb'::uuid, '553d2874-b42f-49c5-8358-f4445949c761'::uuid, 'Dr. Sam does not address the situation and ignores it.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it allows a preventable patient safety risk to continue.', 2, 1, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('8e1d0f95-d246-4f3f-98c8-036576b682c5'::uuid, 5, 'Dr. Smith is reviewing a patient''s records before surgery and notices that the drug chart contains a medication error that could affect the safety of the procedure.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('de598509-69ca-402a-92b0-3ccc65f6ebc5'::uuid, '8e1d0f95-d246-4f3f-98c8-036576b682c5'::uuid, 'Ignore the error and proceed with the surgery as planned.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because known safety concerns should not be ignored before an operation proceeds.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('0dbb547e-d5c2-4190-9a50-861c21c630a6'::uuid, '8e1d0f95-d246-4f3f-98c8-036576b682c5'::uuid, 'Immediately stop any further progress towards surgery until the medication issue is clarified and corrected.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because patient safety comes first, and the error should be corrected before the procedure continues.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('4e4b0641-7953-4520-8f8f-17a677feb887'::uuid, '8e1d0f95-d246-4f3f-98c8-036576b682c5'::uuid, 'Ask the patient whether they know about the medication error and proceed depending on what they say.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because asking the patient about a medication error places an inappropriate burden on them and is the wrong process — resolving a prescribing error is the clinician''s responsibility, not the patient''s. It may also cause unnecessary distress. However, it is not as serious as knowingly ignoring the error and proceeding regardless, because there is at least an attempt to acknowledge the problem. That distinguishes it from ''A very inappropriate thing to do'' while still making clear it falls short of acceptable practice.', 2, 2, 'normal');
INSERT INTO timed_situational_judgement_scenarios (id, test_id, body) VALUES ('ebe5be4b-f236-4ca2-8567-e50fc96478a9'::uuid, 5, 'Sarah, a patient in her mid-50s, has been advised by her doctor, Dr. Miller, to undergo a complex medical procedure. She is anxious and unsure whether to consent.');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('ed2759a1-6b2d-4ac7-8764-c639272857e6'::uuid, 'ebe5be4b-f236-4ca2-8567-e50fc96478a9'::uuid, 'Encourage Sarah to consent immediately so that there are no delays in treatment.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it pressures the patient and does not support informed, voluntary consent.', 0, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('d120f15a-a41b-4768-9713-dafbc82d7bc4'::uuid, 'ebe5be4b-f236-4ca2-8567-e50fc96478a9'::uuid, 'Provide only basic information so that Sarah does not feel overwhelmed by too many details.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because the intention may be to avoid distress, but the patient still needs sufficient information to make an informed decision.', 1, 2, 'normal');
INSERT INTO timed_situational_judgement_questions (id, scenario_id, question_text, correct_answer, answer_reason, order_index, label_set, difficulty) VALUES ('13c7b619-6780-43d6-985c-f257798af3fe'::uuid, 'ebe5be4b-f236-4ca2-8567-e50fc96478a9'::uuid, 'Respect Sarah''s autonomy by providing clear information about the procedure, risks, benefits, and alternatives, and giving her time to ask questions.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because informed consent depends on clear information, time for questions, and respect for the patient''s autonomy.', 2, 2, 'normal');
